Object.assign(window.__LB,{"27500": ["其他", "此段述麦门冬（羊韭、禹葭等名）药性，味甘平微寒无毒，主治心腹结气、伤中伤饱、胃络脉绝、羸瘦短气、身重目黄、心下支满、虚劳客热、口干燥渴，止呕吐、愈痿蹶、强阴益精、消谷调中等。原文虽提“胃络脉绝”，乃病证名而非脉象，故脉象要素为空，归其他。", []], "27501": ["其他", "此段述干地黄与生地黄药性，味甘苦寒无毒，主治折跌绝筋、伤中、逐血痹、填骨髓、长肌肉，除寒热积聚，主五劳七伤、女子伤中胞漏下血、破恶血溺血，通血脉、益气力；生地黄主妇人崩中血不止及产后血上薄心闷绝等。全段为药物主治，无脉象，列其他。", []], "27502": ["其他", "此段述菊花（节花、日精等名）药性，味苦甘平无毒，主治风头、头眩肿痛、目欲脱泪出、皮肤死肌、恶风湿痹，治腰痛去来陶陶，除胸中烦热、安肠胃、利五脉、调四肢，久服利血气轻身耐老。原文“利五脉”指药效通利血脉，非脉象描述，故脉象要素为空，归其他。", []], "27503": ["其他", "此段述甘草（密甘、美草等名）药性，味甘平无毒，主治五脏六腑寒热邪气，坚筋骨、长肌肉、倍力，治金疮尰、解毒，温中下气、烦满短气、伤脏咳嗽、止渴、通经脉利血气、解百药毒，安和七十二种石等。全段为药物主治与配伍，无脉象，列其他。", []], "27504": ["其他", "本段为药物（人参）性味功用记载，未涉及脉象。原文以“味甘，微寒、微温，无毒”述药性，以“主补五脏，安精神，定魂魄”等述主治，通篇无脉诊内容，故脉象要素为空。其“通血脉，破坚积”虽涉血脉，仍属药理描述，非脉象所主病机，不可牵合脉学。", []], "27505": ["其他", "本段为药物（细辛类）性味主治条文，未言脉象。原文“味辛，温，无毒”述药性，“主治上气咳逆，结气，喉痹”述所治病症，“温筋通脉”乃药效通脉之语，非脉象描述。全段无浮沉迟数等脉形记载，故不能据以推断病机，脉象要素留空。", []], "27506": ["其他", "本段为药物（桂类）性味功用及配伍记载，无脉象内容。原文“味甘、辛，大热，有毒”言药性，“主温中，利肝肺气”及“通血脉，理疏不足，宣导百药”言药效，末附配伍禁忌。其中“通血脉”指药力通行血脉，非脉象所主，故脉象要素为空，不列病机。", []], "27507": ["其他", "本段为药物（芍药）性味主治条文，未载脉象。原文“味苦、酸，平、微寒”述药性，“主治邪气腹痛，除血痹，破坚积”述主治，“通顺血脉，缓中，散恶血”述药效。全段无脉形描述，“通顺血脉”属药理而非脉诊，故脉象要素为空，不作脉学病机分析。", []], "27508": ["其他", "本段为药物（桑耳、木耳类）性味主治记载，无脉象内容。原文“味甘，寒，无毒”述药性，“主治伤中，五劳，六极，羸瘦，崩中，脉绝”中“脉绝”指病证名而非脉形描述，其余言水肿、症瘕、月水不调等主治。全段未涉脉诊，故脉象要素为空。", []], "27509": ["其他", "本段为药物形态产地描述，原文“与菝葜相似而小异”“其茎叶小肥，其节疏”“叶圆有赤脉”等皆言植物性状，其中“赤脉”指叶上红色脉络，非人体脉象。全段无脉诊内容，故脉象要素为空，不涉病机主病，归入其他类。", []], "27510": ["其他", "本段为药物性味功用条文，未言脉象。原文“味辛、甘，平，无毒”述药性，“主去恶虫，除脾胃寒热，通利九窍、血脉、关节”述主治药效。其中“血脉”指药力通利血脉，非脉象描述，全段无浮沉迟数等脉形，故脉象要素为空，不作脉学病机推断。", []], "27511": ["其他", "本段为药物（泽泻类）性味功用记载，无脉象内容。原文“味苦，温，无毒”述药性，“主充肌肤，益气，令人暴肥”述药效，末言“血脉满盛，不可久服”乃药后血脉充盛之戒，非脉象描述。全段未涉脉诊，故脉象要素为空，归入其他类。", []], "27512": ["其他", "本段为巴椒（蜀椒）的功用主治，未涉脉象。原文述其能除五脏六腑寒冷、伤寒温疟、心腹留饮宿食，止肠澼下痢、泄精，散风邪瘕结、水肿黄疸，并开腠理、通血脉。所主皆寒凝、饮积、气结之病机，故能温散通达。'多食令人乏气，口闭者杀人'提示辛温耗气之弊，属药性宜忌而非脉诊。", []], "27513": ["其他", "本段述巴椒（当为巴豆类）性味大毒及主治，无脉象。原文'破症瘕，结坚积聚，留饮痰癖，大腹水胀，荡练五脏六腑，开通闭寒'，指明其病机为寒闭积结、水饮壅塞，故以峻药攻逐开通。'治女子月闭，烂胎'及'不利丈夫阴'言其堕胎伤阴之害，'益血脉，令人色好'则言制饵后之效，皆药性论而非脉理。", []], "27514": ["其他", "本段为旋覆花（金沸草）性味主治，未言脉。原文'主治结气，胁下满，惊悸，除水，去五脏间寒热，补中下气'，其病机为气结水停、寒热错杂于五脏；'消胸上痰结，唾如胶漆，心胁痰水，膀胱留饮'明言痰饮留结，故以咸甘微温之品软坚行水、下气消痰，通血脉而益色泽。", []], "27515": ["其他", "本段述羊髓性味主治，无脉象。原文'主治男女伤中、阴气不足，利血脉，益经气'，其病机为阴精亏虚、血脉不利、经气不足，故以甘温之羊髓补益阴气、通利血脉，以酒服助其行散。全段属药性功用，未及脉诊与症候对应。", []], "27516": ["其他", "本段述某药（味咸甘平）主治，未涉脉。原文'主治伤中，脉绝，阴不起，强志益气，长肌肉肥健，生子。小儿惊痫'，'脉绝'指血脉虚绝之病机，阴不起为肾阴不足，故以咸甘平之品补益强志、长肌肥健；小儿惊痫则示其能安镇。全段为药效记载，非脉象主病之论。", []], "27517": ["其他", "本段述髓及肾的性味主治，无脉象。原文'主治丈夫女子伤中脉绝，筋急痛，咳逆'，'脉绝'言血脉虚竭，筋急痛为血不养筋，咳逆为气机上逆，故以甘温之髓酒和服之补血养筋；'肾：平，主补肾气'则示补肾之功。全段属药性主治，未及脉诊。", []], "27518": ["其他", "本段述猪及其各部位的性味主治，未言脉。原文'主治惊痫，癫疾，鬼疰，蛊毒，除寒热，贲豚，五癃，邪气挛缩'，病机涉及邪气内结、气逆挛急；'凡猪肉：味苦，主闭血脉，弱筋骨，虚人肌，不可久食'明言猪肉闭血脉、虚肌之害，与诸部位主治形成宜忌对照，皆属药食性论。", []], "27519": ["其他", "本段述某虫类药（味苦微寒有毒）主治，无脉象。原文'主逐瘀血，破下血积，坚痞，症瘕，寒热，通利血脉及九窍，女子月水不通，积聚，除贼血在胸腹五脏者'，其病机为瘀血积结、血脉不通，故以苦寒有毒之品破血逐瘀、通利九窍；'腹有血者良'示其专入血分。全段为药性主治，非脉诊内容。", []], "27520": ["主病", "原文载药“主治血瘀，症坚，寒热，破积聚，喉咽痹。内塞无子，通利血脉”，虽未言脉，但所述病机为瘀血内结、症瘕积聚、寒热错杂、咽喉痹阻及胞宫闭塞无子。瘀血阻滞则脉道不利，临床可见涩或弦紧之脉；通利血脉即针对血瘀脉阻而设。", []], "27521": ["主病", "原文载药“主治女子赤沃，止血，养精，保血脉，益气”，未直接言脉。赤沃即赤白带下，属湿热或虚损伤及冲任，脉多滑数或细弱；养精保血脉则示精血亏虚可致脉细弱。全段以主病为主，脉象需结合症候推断。", []], "27522": ["主病", "原文述药“主补中益气……治中风汗出，逐水，利小便，破积血。复血脉，乳妇产后余疾”，未言脉。补中益气针对气虚脉弱；逐水利小便针对水气脉沉；破积血复血脉针对瘀血脉涩。诸效反映气虚、水停、血瘀并存之病机。", []], "27523": ["病机", "原文仅言“主气治脉溢”，未直接描述脉象。脉溢指脉气满溢，多因气机壅盛或血热妄行，致脉道充盈过度，可见洪大或数急之脉。药味苦能泄，故治气逆脉溢，使气血复常。", []], "27524": ["其他", "原文论药材锉制及根梢身分治，提出“生苗向上者为根，气脉行上；入土垂下者为梢，气脉下行。中截为身，气脉中守”，以“气脉”言药力走向，非诊脉之象。上焦病用根、中焦用身、下焦用梢，体现根升梢降中守的用药法度。", []], "27525": ["病机", "原文以五味调五脏立论，明言“脉软则和，故咸可以养脉”，又谓“气坚则壮，故苦可以养气”。脉软为柔和之象，非病脉，乃脉得咸味滋养而和缓。若过用则“太过亦病”，提示脉失柔和可因味过偏。全段以脉软为和，阐发气味养脉之理。", ["软"]], "27526": ["治法", "原文论服药时间与病位关系，提出“病在四肢、血脉者，宜空腹而在旦”，未直接言脉。病在血脉，空腹旦服可使药力速达血脉；在上者少服频服以滋荣，在下者多服顿服以峻补。此属服药法度，非脉诊内容。", []], "27527": ["其他", "原文详述人参产地、形态、种类及气味，谓“味甘，气温、微寒。气味俱轻，升也，阳也，阳中微阴”，未涉及脉象。所论为药物性味升降，非脉诊病机，故脉象要素为空。", []], "27528": ["病机", "原文虽以人参禁忌为论，但引“肺中虚热，用之何害”及“虚火可补”，脉虚提示肺虚有热，非实火。虚火宜补，故人参可用；若实热则忌。脉虚为辨证关键，说明病机属虚，与实热之喘嗽吐血相鉴别。", ["虚"]], "27529": ["其他", "本段专论黄耆产地、品种、采收、鉴别及伪品，未涉及脉象与病机。所述“功力殊劣”“极佳”“获效如神”等，均指药材质地，与脉诊无关，故脉象要素为空。", []], "27530": ["病机", "原文列内伤诸证后言“脉息虚微，精神短少”，虚微脉主元气亏虚、脾胃衰弱。参耆甘温补益，正合虚损之机。脉虚微与怠惰嗜眠、力乏形羸相应，说明病本在虚，治宜补中益气。", ["虚", "微"]], "27531": ["主病", "原文以“脉洪多热”概括地黄所主。洪脉为热盛之象，热邪内炽则脉道宽大。地黄气寒味苦甘，能清热凉血，故主热证。脉洪与多热相应，提示病机为热盛，治当清泄。", ["洪"]], "27532": ["其他", "本段讨论当归分根使用及瘀血、血虚部位用药，未及脉象。所述“气脉上行”“气脉下行”指气血运行部位，非脉诊之脉，故脉象要素为空，主旨属用药法度。", []], "27533": ["其他", "本段述牛膝性味、产地、雌雄鉴别、炮制及主治，未提脉象。所主“手足寒湿痿痹”“小便短少”等症，虽属病机，但无脉象可录，故脉象要素为空。", []], "27534": ["病机", "原文以麦门冬治“心腹结气能散”，脉散指气机涣散、结气不聚。散脉主气血耗散，与肺伏火邪、心劳伤损相应。麦门冬益精强阴，使散者收之，故能散结气、补虚损。", ["散"]], "27535": ["主病", "原文引白虎汤证“脉尺寸俱长，其热明矣”。长脉主热盛气充，尺寸俱长说明热邪弥漫三焦。与烦燥、不得眠相应，病机为阳明热盛，故用石膏知母苦寒清泄。", ["长"]], "27536": ["其他", "本段为药物（秦艽）性味归经功效描述，未涉及脉象。原文述其“气味俱轻，升也，阳也”，主“泻肝火，去心下痰结热烦”，治“偏头疼，胸胁刺疼及胆瘅疼痛”，并“解肌表热，早晨潮热并寒热往来”，皆从药性升降浮沉论治，非脉诊内容。", []], "27537": ["其他", "本段述天麻性味功效，未及脉象。原文称其“治小儿风痫惊悸，疗大人风热头眩”，又能“驱湿痹拘挛，主瘫痪蹇滞”，皆从药性“通血脉开窍”立论，非凭脉辨证，故无脉象要素可录。", []], "27538": ["其他", "本段为续断（又名接骨）之药性功效，未言脉象。原文强调“续筋骨调血脉，专疗跌扑折损”，又“缩小便频数，固精滑梦遗”，并“暖子宫，俾育妊孕”，皆属药物主治，非脉诊病机分析。", []], "27539": ["其他", "本段述漏芦（一名野兰）性味归经及炮制，未涉脉象。原文谓其“治身体风热恶疮，去皮肤瘙痒瘾疹”，主“乳痈发背”，又“补血排脓，生肌长肉”，皆从药性“行足阳明”论治，非脉象主病。", []], "27540": ["病机", "原文仅“白和血脉缓中”一句含脉象描述“缓中”，指白芍药能调和血脉、缓解中焦急迫。此处“缓”非脉象要素，乃药效之缓中，故脉象取“缓”字以应原文，实为药性功用，非诊脉所得。", ["缓"]], "27541": ["其他", "本段述荆芥（假苏）性味功效，未及脉象。原文称其“发表能解利诸邪，通血脉传送五脏”，又“下瘀血除湿痹，破结聚散疮痍”，并治“产后血晕”，皆属药物主治，非脉诊病机。", []], "27542": ["其他", "本段述泽泻性味归经功效，未言脉象。原文谓其“去阴汗大利小便，泻伏水微养新水”，引经云“除湿止渴圣药，通淋利水仙丹”，又“叶状水脏，通血脉，行乳汁催生”，皆从药性渗利论治，非脉象主病。", []], "27543": ["其他", "本段述丹参性味功效，未涉脉象。原文称其“专调经脉匀，善理骨节痛”，能“生新血去恶血，落死胎安生胎”，又“破积聚症坚，止血崩带下”，皆属药物主治，非脉诊病机分析。", []], "27544": ["其他", "本段为青蒿及白蒿、邪蒿、牡蒿、角蒿等药物的性味主治记载，通篇未涉及脉象。原文述青蒿“味苦，气寒”，能“退骨蒸劳热”“止虚烦盗汗”，皆从药性气味立论，非凭脉辨证。故无脉象要素可录，主旨属本草主治范畴，列于其他。", []], "27545": ["其他", "本段记芭蕉根、蕉油及蕉子之性味功用，如“味甘，气大寒”，绞汁服“主天行狂热闷烦”“产后胀闷”，捣敷“去小儿赤游丹毒”。全段言药性主治与采制，未及诊脉，故脉象要素为空，主旨归入其他，不涉病机脉理。", []], "27546": ["病机", "原文仅于炮制附子处提及“脉细者”，属药后或病体脉象之旁及，非以脉论病。附子“味辛、甘，气温、大热”“有大毒”，其“气因浮中有沉，功专走而不守”，故脉细者用此辛热走窜之品，当防耗散。脉细主虚，与附子大热通行之性相参，提示虚体用峻药须慎，非本段主论。", ["细"]], "27547": ["其他", "本段辨乌头与附子之异，述其“气味制度，俱与附同”，主治“风痹”“风痰”“寒邪”“寒痛”，能“破滞气积聚，去心下痞坚”，并载乌喙、射罔及中毒解法。通篇为药物名实、炮制、功用与禁忌，未涉脉象，故脉象要素为空，主旨归其他。", []], "27548": ["病机", "本段引丹溪言夏枯草“善补养厥阴血脉之功”，治“肝虚目疼、冷泪不止、羞明怕日、久视昏花”。其“禀纯阳之气，得阴气即枯”，故能补厥阴血脉而疗肝虚诸症。全段从药性推病机，属肝血虚之目疾，未载脉象，脉象要素为空，主旨归病机。", []], "27549": ["其他", "本段述连翘产地、形色、采收与修制，辨川蜀与江南所产之异，言其“气味俱薄，轻清而浮，升也，阳也”，入少阴心及手足少阳阳明经，“泻心经客热”“降脾胃湿热”，驱痈毒蛊毒。通篇为药性归经与主治，未及脉象，脉象要素为空，主旨归其他。", []], "27550": ["病机", "本段为牵牛之辨，驳《续注》“味苦、寒”之说，谓其“味则辛辣”“乃导气之药”，只能“泻气中湿热，不能泻血中湿热”。引仲景治湿不用牵牛，因“湿病之根在下焦，是血分中气病”，不可用辛辣气药反泻上焦太阴之气。全段论药性与湿病病机，未涉脉象，脉象要素为空。", []], "27551": ["病机", "本段论萆薢治杨梅疮后拘挛痈漏之理。原文谓“原因水衰，肝挟相火凌土，土属湿生肌肉，湿热郁于肌腠，故为痈肿”，引经“湿气害人皮肉筋脉”。萆薢“味甘、淡，去脾湿”，湿去则“筋脉柔，肌肉长”。全段以药测证，阐发湿热郁于肌腠之病机，未载脉象，脉象要素为空。", []], "27552": ["病机", "原文以芫花泻湿利水为要，指出水病由脾、胃、肾三经所主，分属五脏六腑十二经，故诊有浮、中、沉之异，脉有寸、关、尺之殊。浮沉对举，意在说明水湿为病须辨表里浅深：浮取候外而皮毛肌肉，沉取候内而筋骨脏腑。脉位不同则病经不同，误投则害非浅，故本条重在凭脉定位以审病机。", ["浮", "沉"]], "27553": ["其他", "本段专述桂类药物之性味、产地、采收与炮制，如箘桂、牡桂、官桂、木桂、筒桂、板桂、柳桂、肉桂、桂枝、桂心等，各因其材而名异。原文未及脉象，亦未论病机症候，仅言辛甘大热、浮而阳中之阳、有小毒，属药性辨识内容，故脉象要素为空，主旨归入其他。", []], "27554": ["病机", "原文围绕桂之止烦出汗与仲景无汗不得服桂枝、汗多用桂枝甘草汤展开辨析，提出桂善通血脉，调其荣血则卫气自和，邪无容地而自汗解；调和荣卫则邪去汗止。一药二用，殊途合辙。全段论药性作用机理与荣卫失调之病机，未涉脉象，故脉象要素为空。", []], "27555": ["其他", "本段述桑白皮性味甘辛气寒、可升可降，入肺经，能助元气、泻肺中火邪、止喘嗽唾血、利水消肿、解渴驱痰，并载采收炮制及配伍使药。原文未出现脉象描述，所论为药性功用与主治，非凭脉辨证，故脉象要素为空，主旨归其他。", []], "27556": ["其他", "本段述蜀椒（花椒）味辛气温大热、有毒，属火有金与水，浮而阳中之阳，载其采收、炮制、使药与畏恶，并列举却心腹冷疼、寒湿痹疼、杀鬼疰蛊毒、退目翳、驱六腑沉寒、通气脉开鬼门、暖腰膝缩小便等功用。全段为药性主治，未及脉象，故脉象要素为空。", []], "27557": ["其他", "本段述阳起石（或同类石药）味辛咸气温，属金有水与火，降而阴中阳，载产地、性状鉴别、炮制、畏恶与使药，并言追积杀三虫、补中安五脏、疗男子风寒湿痹时作痒疼等。原文未出现脉象，所论为药性鉴别与主治，故脉象要素为空，主旨归其他。", []], "27558": ["其他", "本段述密蒙花味甘气平微寒无毒，产自川蜀，叶青冬不凋，花紫瓣细碎，十房一朵故名密蒙；采花酒浸一宵、蜜拌蒸过再晒，专治眼科，去青盲肤翳、止眵泪赤涩、消赤脉贯睛内掩、除疳毒侵眦外遮。全段为药性与眼科主治，未涉脉象，故脉象要素为空。", []], "27559": ["其他", "本段述粳米味甘苦气平微寒无毒，水田堪莳，霜降才收，米黏曰粳，有赤白两种，入心肺二经；能益气填补中焦、止泄平和五脏，合芡实煮粥明目强志益精。又述伤寒方中桃花汤、竹叶石膏汤、白虎汤用粳米各有取义，陈廪米性缓调脾胃。全段论药食功用，未及脉象，故脉象要素为空。", []], "27560": ["其他", "此段论麦之性味与产地，非脉学内容。原文强调北地霜雪多而毒少、南方霜雪少而毒多，故北麦面可常餐、南麦面只堪暂用，又言浮小麦敛虚汗获效如神、砻磨成麸实大肠止泄。全段以麦之药用与食用宜忌为主，未涉及脉象主病，故脉象要素为空。", []], "27561": ["其他", "此段述粟米新陈之性味功效，非脉诊文字。原文分新粟米养肾气不亏、去脾热常益中脘，陈粟米止泄痢分渗、却胃热大解渴消，又及泔主霍乱转筋、臭泔除烦渴驱热。全段论谷食药用，未言脉象，故脉象要素为空，主旨归其他。", []], "27562": ["其他", "此段论麻子及麻油之性味功用，非脉学段落。原文言麻子行风气并头面浮风、治虚劳及身体客热、滑肠胃通便闭结、利血脉润发枯焦，又述麻油性冷、入药拯病惟益外科、治一切恶疡下三焦热毒。全段为药物主治，未涉脉象，故脉象要素为空。", []], "27563": ["其他", "此段详述麻子修制与药用，非脉诊内容。原文言麻子入药修制宜精，经入阳明大肠及足太阴脾脏，益气补中、催生下乳，去中风出汗、皮肤顽痹，润大肠风热、结涩便难，止消渴而小水能行，破积血而血脉可行。全段论药性归经主治，未及脉象，故脉象要素为空。", []], "27564": ["其他", "此段论酒之性味与饮用宜忌，非脉学文字。原文言酒气大热有毒，糯米面曲者为良，能引经行药势最捷，因走诸经不止称与附子同功；又分辛者能散通行一身之表、甘者能缓居中、苦者能下、淡则竟利小便而速下。少饮养脾扶肝，犹有狂药别号。全段未涉脉象，故脉象要素为空。", []], "27565": ["其他", "此段论生姜性味归经与炮制配伍，非脉诊段落。原文言气味俱轻、升也阳也，去皮热留皮凉，佐大枣益气厚肠、兼竹溺豁痰利窍，杀半夏毒不麻戟咽喉，同陈茶叶煎汁疫痢禁口者可苏，拌生盐炒泡汤宿食裹痰者即吐。全段为药性主治，未言脉象，故脉象要素为空。", []], "27566": ["其他", "此段论水英（芹菜）之性味功效，非脉学内容。原文言其益气养精、令肥健嗜食，止烦渴、杀诸石药毒，保血脉、退五肿急黄，利大小二肠亦利口齿，止赤沃带下仍止崩中，小儿身暴热可临、大人酒后热能解。全段为药物主治与食忌，未涉脉象，故脉象要素为空。", []], "27567": ["病机", "此段引东垣论杏仁治气、桃仁治血，俱治大便闭燥而有气血之分。原文以脉浮在气、脉沉在血为辨：昼便难行阳气，夜便难行阴血。年高人便闭不可泄者，脉浮在气宜杏仁陈皮，脉沉在血宜桃仁陈皮，取陈皮使手阳明与手太阴表里相应。浮沉二脉分主气分血分病机，故归病机。", ["浮", "沉"]], "27568": ["其他", "本段为药物（莲实）性味功用记载，非脉诊内容。原文言其“利益十二经脉血气，安靖上下君相火邪”，是从药性角度说明该药能通利十二经脉、清君相之火，而非以脉象判断病机。所主病机为血气不和、君相火动，故能“禁精泄清心，去腰痛止痢”，与脉象无关。", []], "27569": ["其他", "本段记榧实性味功用，非论脉。原文“经脉堪通，血脉能润”指该药能通利经脉、润养血脉，属药效描述而非脉象主病。其“多食动风生痰，且助肾火”提示过食可致风痰与肾火偏亢之病机，与脉诊无涉。", []], "27570": ["其他", "本段述朱砂产地、采制与品质鉴别，非脉学内容。原文“凡治病邪，惟取优等”强调用药须择上品，未涉及脉象与病机对应。全段主旨为药物鉴别，故不列脉象，亦不以脉论病机。", []], "27571": ["其他", "本段记灵砂（二气砂）性味功用，非脉诊。原文“止烦满，通血脉，安魂魄，养精神”言其能通血脉、安神定志，所主病机为血脉不畅、神魂不安，属药效说明，非据脉象判断，故脉象要素为空。", []], "27572": ["其他", "本段述空青、曾青产地与功用，非脉学。原文“益肝气，养子精，利九窍，通血脉”指其能益肝通窍、通利血脉，所主为肝气不足、九窍不利之病机，系药物功用记载，与脉象无关。", []], "27573": ["其他", "本段记磁石性味炮制与主治，非脉诊。原文“除大热烦满，去周痹酸疼”“强骨气，益肾脏，通关节”说明其主大热烦满、周痹、肾虚骨弱等病机，属药效论述，未以脉象为据，故脉象要素为空。", []], "27574": ["其他", "本段述金屑（金箔）性味功用，非脉学。原文“除邪杀毒，却热驱烦。安魂魄，养心神，坚骨髓，和血脉”言其能安神和血、坚骨除热，所主为邪热扰神、血脉不和之病机，系药物记载而非脉象主病。", []], "27575": ["其他", "本段为作者按语，论煎药择水之要，非脉诊。原文“水入于经，其血乃成。谷入于胃，脉道乃行”引先哲语说明水谷与血脉生成、脉道运行的关系，所主病机为水谷不足则荣卫散亡、脉道不利，属养生用药理论，非据脉象判断。", []], "27576": ["其他", "本段为马（驹）药性记载，非脉学原文。文中“续绝脉”指马药可续接断绝之血脉、治中伤，属药效描述而非脉象诊断。全段论毛色、炮制、房中术及食肉禁忌，未涉及具体脉象要素，故脉象要素为空，主旨归入其他。", []], "27577": ["其他", "本段论牛黄形成与鉴别，非脉学内容。文中“两眼血红”“内热气熏蒸”述牛因内热而结黄，“生黄”“角黄”“心黄”等皆指牛黄品类，无脉象描述。全段为药材辨识与炮制，故脉象要素为空，主旨归入其他。", []], "27578": ["其他", "本段为猪肤药性及猪副产品主治，非脉学原文。文中“少阴客热，惟此解之”言猪肤汤解少阴客热，“猪为水畜”释其入肾之理，皆属药性归经与方义，未及脉象。故脉象要素为空，主旨归入其他。", []], "27579": ["其他", "本段论鹿茸、麋茸采收与鉴别，非脉学内容。文中“血气嫩未全具”“气血反老衰残”以气血盛衰判茸之老嫩，“益气滋阴”“破留血”述药效，均无脉象描述。故脉象要素为空，主旨归入其他。", []], "27580": ["其他", "本段为羊（羖）角、羊肉药性主治，非脉学原文。文中“止血调荣，安神益卫”“主劳伤脏气虚寒”等皆属药效与所主症候，未涉及脉象。故脉象要素为空，主旨归入其他。", []], "27581": ["其他", "本段论鸡（丹雄鸡等）药性食用宜忌，非脉学内容。文中“性动风患筋挛切忌”“味助火病骨热须防”言其动风助火之弊，“通神健脉”为药效表述而非脉象诊断。全段无脉象要素，主旨归入其他。", []], "27582": ["其他", "本段为蜗牛（蛞蝓、蜒蚰）药性主治，非脉学原文。文中“治惊痫筋脉拘挛”言蜗牛所主症候，“筋脉拘挛”为病症名而非脉象。全段论形态、采收与主治，无脉象描述，故脉象要素为空，主旨归入其他。", []], "27583": ["其他", "本段为虻虫药性主治，非脉学内容。文中“逐瘀血血闭”“破积血症瘕痞坚”“通血脉九窍喉痹”皆述虻虫破血逐瘀之效与所主症候，未及脉象。故脉象要素为空，主旨归入其他。", []], "27584": ["其他", "本段讨论《神农本经》《素问》《脉诀》等古籍的成书与流传问题，涉及朱墨错乱、补亡混淆、后人增益等，未涉及具体脉象与病机，故无脉象要素可提取，主旨属文献考证，非主病或病机。", []], "27585": ["病机", "原文强调「安谷则昌，绝谷则亡」，水谷去则荣散卫亡，神无所居；又引仲景「水入于经，其血乃成，谷入于胃，脉道乃行」，说明荣卫化生于水谷，血温卫和则脉道通利，天命常存。全段论荣卫与脉道之根本在脾胃水谷，属病机范畴，未出具体脉象。", []], "27586": ["其他", "此段为方药歌诀，述太阴肺脉中焦起，用白芷、升麻、葱白等药，属用药治法内容，未涉及脉象形态与病机分析，故脉象要素为空，主旨归为其他。", []], "27587": ["其他", "本段以药根上中下部位类比人身三焦，论根升梢降及用药取象，属药性理论，未言脉象与病机，故无脉象要素，主旨归为其他。", []], "27588": ["病机", "原文引仲景「阳脉涩、阴脉弦，法当腹中急痛」，阳脉涩为表虚血少，阴脉弦为里急痛，故制小建中汤以芍药为君补中缓急。涩弦并见，反映荣卫不足、木克土而腹中急痛之病机，与桂枝汤治表虚相对，此则治里虚。", ["涩", "弦"]], "27589": ["主病", "许伯威中气本弱，伤寒误下又食梨，伤脾胃致四肢冷、昏愦。诊其脉「动而中止，有时自还，乃结脉也」，结脉主气血虚衰、脉道不利；伴心悸、吃噫、色变青黄、倦卧，皆中气虚弱、荣卫涸流之候，故以炙甘草汤复脉通心。", ["结", "动"]], "27590": ["病机", "原文提出疗病先察源候机，若「五脏未虚，六腑未竭，血脉未乱，精神未散，服药必效」，强调血脉未乱是正气尚存、可治之机；病成则半愈，病过则难存。全段论早期诊治与病机转归，未出具体脉象，故脉象要素为空。", []], "27591": ["病机", "本段论药食五味太过伤及五脏：过酸肝气津而脾气绝，过咸大骨气劳、心气抑，过甘心气喘满、肾气不衡，过苦脾气不濡、胃气厚，过辛筋脉沮弛、精神央。强调「谨和五味」则骨正筋柔、气血以流，属五味偏伤五脏之病机，未涉脉象。", []], "27592": ["病机", "原文言多食咸则脉凝泣而变色，咸味太过伤血，血凝则脉道涩滞不畅，故脉见凝泣之象。此非具体脉形，而是言过食咸味致血脉凝涩、色泽改变的病机，属五味偏伤、血脉瘀滞之候，与《内经》咸走血、血病无多食咸之旨相合。", []], "27593": ["其他", "此段论羌活、独活药性及主治，非论脉。言羌活气雄入足太阳，独活气细入足少阴，治太阳经头痛、肢节痛、一身尽痛。引巨阳从头走足、厥阴督脉会巅、逆而上行诸阳不得下以释头痛之理，属药性归经与病机阐释，与脉象无关。", []], "27594": ["主病", "原文言脉弦自汗，以弦脉主虚劳。弦为肝脉，虚劳日久脾胃虚弱，肝木乘土，故脉见弦；气虚不能固表则自汗。此脉弦自汗并见脾胃虚弱、疮疡血脉不行，属内伤虚损、肝脾不和之候，故用黄芪补肺气、实皮毛、泻肺中火以内托。", ["弦"]], "27595": ["其他", "此段辨黄芪品种真伪及功用，非论脉。言绵黄芪与苜蓿根之别，述其破症癖、肠风血崩、带下、赤白痢、月候不调、消渴痰嗽及头风热毒、目赤骨蒸诸治，并治气虚盗汗自汗、肤痛、咯血、柔脾胃，属药性主治与鉴别之文。", []], "27596": ["其他", "此段引《本草》述芍药主治，非论脉。言主邪气腹痛、除血痹、破坚积、寒热疝瘕，止痛利小便、益气通顺血脉、缓中散恶血、逐贼血、去水气利膀胱，皆属药性功用与所治病症，未涉及脉象要素。", []], "27597": ["其他", "此段引《本草》述地黄主治，非论脉。言主折跌绝筋伤中、逐血痹、填骨髓、长肌肉，除寒热积聚痹，主男子五劳七伤、女子伤中胞漏下血、破恶血溺血，利大小肠、去胃中宿食、补五脏内伤不足、通血脉益气力利耳目，属药性功用。", []], "27598": ["治法", "原文以脉洪实与脉虚分判生熟地黄之用。脉洪实者，火热亢盛、血分有热，故宜生地黄益肾水而治血；脉虚者，精血不足、元气亏虚，则宜熟地黄补肾中元气。此以脉之虚实定用药取舍，属凭脉施治之例，洪实为实热，虚为不足。", ["洪", "实", "虚"]], "27599": ["其他", "此段引《本草》述某药主治，非论脉。言主补中益气、中风汗出、逐水利小便、破积血、复血脉、乳妇产后余疾，长发可为沐药，久服肥健不老，皆属药性功用与所治症候，未言及脉象。", []], "27600": ["其他", "此段为《本草》论甘草功用，未及脉象。原文述其“主五脏六腑寒热邪气，坚筋骨，长肌肉，倍力”，又“通经脉，利血气，解百药毒”，为九土之精，安和诸石草。所主病机在于调和脏腑、补益中气、通利血气，故能治寒热邪气、金疮肿毒、烦满短气、伤脏咳嗽等症，非凭脉断病。", []], "27601": ["病机", "原文首标“脉尺寸俱长”，长脉主气机有余、邪热内盛。此段论知母苦寒润，入足阳明、手太阴，泻心清肾；白虎汤治不得眠之烦躁，以石膏为君、知母为佐，清肾之源。尺寸俱长示表里热盛，故用白虎汤清之。文中辨“胸中寒”“表热里寒”之“寒”字，乃寒邪化热之毒，非真寒，脉长正合热盛之机。", ["长"]], "27602": ["病机", "此段引《心》法论人参补气不足而泻肺火，甘温补阳利气。原文言“脉不足者，是亡血也，人参补之”，以脉不足示气血虚衰，故用人参补益。又益脾与干姜同用，里虚腹痛亦补之。所主病机为气虚血少、脾肺不足，脉不足即虚象，主亡血、里虚腹痛等症，治当甘温补气。", []], "27603": ["其他", "此段为《本草》论人参功用，未及脉象。原文述其“主补五脏，安精神，定魂魄，止惊悸，除邪气，明目，开心益智”，疗肠胃中冷、心腹鼓痛、胸胁逆满、霍乱吐逆，调中止消渴，通血脉，破坚积。所主病机为五脏虚损、气血不足、神志不安，故以人参补益安神、通脉破积，非据脉辨证。", []], "27604": ["其他", "此段为《本草》论某药（据文义当为旋覆花）功用，未及脉象。原文述其“主补中下气，消坚软痞，消胸中痰结，吐如胶漆”，又治脐下膀胱留饮、利大肠、通血脉。发汗吐下后，心下痞、噫气不除者宜此。所主病机为痰饮结聚、胃气上逆、中气不足，故能下气消痰、软痞通脉，非凭脉断病。", []], "27605": ["病机", "此段论天门冬（或麦门冬）功用，未直接出脉，然言“荣卫枯涸，湿剂所以润之”，以荣卫枯涸示津血亏虚之机。二门冬、人参、北五味子同为生脉之剂，取上焦独取寸口之意，主诸暴风湿偏痹、强骨髓、保定肺气、去寒热、养肌肤、益气力、利小便。所主病机为肺肾阴亏、荣卫枯涸，故以润剂生脉益肺。", []], "27606": ["病机", "此段引《象》论麦门冬（或五味子）治肺中伏火，原文关键在“脉气欲绝”四字，示肺中元气不足、脉道虚弱欲绝之象。伏火内灼，耗伤肺气，故脉气欲绝。加五味子、人参，三味为生脉之剂，补肺中元气不足。所主病机为肺中伏火、元气虚衰，脉气欲绝即其征，治当生脉补肺。", []], "27607": ["其他", "此段为《本草》论麦门冬（或天门冬）功用，未及脉象。原文述其“主心腹结气，伤中伤饱，胃络脉绝，羸瘦短气”，又身重目黄、心下支满、虚劳客热、口干燥渴，止呕吐，愈痿蹶，强阴益精，消谷调中，保神定肺气，安五脏。所主病机为胃络脉绝、阴精亏虚、虚劳客热，故能强阴益精、调中保神，非凭脉断病。", []], "27608": ["治法", "原文未出脉名，以“复脉通心”“生脉之剂”立论。麦门冬、地黄、麻仁、阿胶润经益血，二门冬、五味子、枸杞子同为生脉之剂，是治心肺虚热及虚劳。虚热耗血则脉失充盈，故以润养复其脉道；寒多人禁服，因苦泄专泄不专收，恐伤阳气而脉更弱。", []], "27609": ["主病", "原文未出脉名，主老癖症瘕结块、妇人血脉不调、心腹刺痛。症瘕结块乃气血瘀滞日久，脉道不利；血脉不调则脉来或涩或结。须炮用者，取其温通破结而不峻，使瘀消脉通，心腹刺痛自止。", []], "27610": ["病机", "原文未出脉名，言治气胀、血脉不调、通月经、消瘀血，色白破血中之气。气胀则脉多弦滞，血脉不调则脉来不畅；药破血中之气，使气行瘀消，脉道通利，月经自调，五劳得补。", []], "27611": ["主病", "原文未出脉名，治四肢游风、利血脉、心烦、胸膈壅闷。游风走注四肢，血脉不利则脉多浮弦；胸膈壅闷、心烦乃气机不畅。药利血脉、散游风，使壅闷除而心烦解。", []], "27612": ["主病", "原文未出脉名，仅言治风毒、通血脉。风毒外袭，血脉壅滞，脉多见浮弦或涩；通血脉则风毒得散，脉道复常。文简，未及具体脉症。", []], "27613": ["病机", "原文未出脉名，除脾胃寒热、通利九窍血脉关节，散痈肿诸结不消，堕胎去虫。脾胃寒热则脉或数或迟；血脉关节不利则脉涩。通利九窍血脉，使结散肿消，九窍关节通利。", []], "27614": ["主病", "原文未出脉名，主温中、利肝肺气、心腹寒热冷疾、霍乱转筋、头痛腰痛等，能堕胎、坚骨节、通血脉、宣导百药。寒热冷疾则脉或迟或紧；通血脉、利肝肺气，使寒热调、冷疾除。后辨桂之种类产地，与脉无关。", []], "27615": ["主病", "原文未出脉名，述槐耳主五痔心痛、女人阴中疮痛；槐花治五痔心痛眼赤、肠风泻血、赤白痢；槐胶主一切风、筋脉抽掣、急风口噤、四肢不收、顽痹、破伤风口眼偏斜、腰膝强硬。风毒入筋脉则脉多弦急，槐胶化痰祛风，使筋脉抽掣、强硬得缓。", []], "27616": ["其他", "原文载药治“伤中五劳六极羸瘦，崩中脉绝”，脉绝指崩中失血致脉气欲绝，属虚损危候；药能补虚益气，故所主病机为气血虚极、脉道不充。文中“去肺中水气”“水肿腹满”又示水气内停，虚实夹杂，然无具体脉象描述，故脉象要素从缺。", []], "27617": ["病机", "原文强调水饮为病“脉有尺寸之殊，浮沉之异”，浮沉分表里上下，尺寸别脏腑经络，故不可轻泻。水湿停聚，三焦气化不利，脉浮主病在气分、肌表，脉沉主病在血分、筋骨，当辨何经何脏而治，误泻则害深，此即水气病之脉机。", ["浮", "沉"]], "27618": ["其他", "原文主养脾气、补津液，又言“中满者勿食甘，甘者令人中满”，指出甘味药能补脾益气，但过用则壅滞气机，致心下痞满。所论重在药性利弊与证治宜忌，非论脉象，故脉象要素从缺，病机为脾虚气弱与甘壅中满两端。", []], "27619": ["病机", "原文以“脉浮在气，脉沉在血”分大便燥秘之病机：浮脉主气分，昼便难属阳气不运，用杏仁、陈皮泻肺行气；沉脉主血分，夜便难属阴血不足，用桃仁、陈皮活血润肠。脉浮沉辨气血，为年虚人燥秘不可过泄之凭据，亦示肺与大肠相表里。", ["浮", "沉"]], "27620": ["其他", "原文述药“利血脉，通宣五脏不足气”“破结气”，治产后血晕，其病机为血气壅滞、五脏气机不通，故用此宣通血脉、发汗除劳。所论为药效与主治，未及脉象，脉象要素从缺；多食“薰五脏神”则示辛散太过反伤正气。", []], "27621": ["病机", "原文言“治沉寒痼冷，肾中无阳，脉气欲绝”，脉气欲绝乃阳气衰微、不能鼓动血脉之危候，故以姜附汤温阳救逆。病机为肾阳式微、阴寒内盛，亦治中焦有寒，属虚寒重证，脉当沉微欲绝，文中未出具体脉名，故脉象要素从缺。", []], "27622": ["主病", "原文云“伤寒初觉头痛内热，脉洪”，洪脉主热盛，伤寒初起一二日邪在表而热已内盛，故见头痛内热、脉洪。治以葱豉汤取汗，不汗加葛根、麻黄，示脉洪为表热壅盛之征，当从汗解，与伤寒表证相应。", ["洪"]], "27623": ["其他", "原文主“五脏积聚，久热胃闭”“破留血，腹中痰实结搏”，病机为邪气结聚、痰血壅阻、经脉不通，故药能除邪破血、通经脉月水。所论为药效主治，未及脉象，脉象要素从缺；久热胃闭与痰实结搏并见，示积热与瘀结相兼为患。", []], "27624": ["主病", "原文未出脉名，专述药物主治。所谓主鬼疰、贼风蛊毒、杀精物恶鬼、腹中毒邪气，皆言其能祛邪解毒；女子赤沃漏下、带下百病、产难、胞衣不出、堕胎，则示其入血分、通血脉而善治妇人经产诸疾；养血、除五脏血脉中热、血痹血瘀，说明药性兼能凉血行血；小儿惊气入腹、阴痿不起，又见其安惊、起痿之功。全段以药测证，非论脉象。", []], "27625": ["主病", "原文未及脉象，只载丹朱性味功效。味甘微寒无毒，故能养精神、安魂魄，甘寒清心而安神；益气明目，示其补虚而升清；通血脉、止烦渴，则说明其能清血中虚热、生津除烦。所主皆神志不宁、血脉不和、津伤口渴之候，与脉学无直接关联，故脉象要素从缺。", []], "27626": ["主病", "原文未出脉名，述药之主病与炮用。主心腹痛内崩，是取其温通止痛、固摄下血；补虚安胎、坚筋骨，示其补益肝肾、强健筋骨；和血脉、益气止痢，说明能调畅血脉、补气厚肠。全段以功效反推证候，属虚寒腹痛、胎动不安、筋骨痿弱、久痢不止之治，非脉诊内容。", []], "27627": ["病机", "原文未言脉，借人尿同体以明药理。补肝而和阴引置阳，谓其能滋养肝阴、引阳入阴，使阴阳相济而不被格拒；能入心而通脉，则说明其入心经以通利血脉。所论重在阴阳格拒、心脉不通之病机，与脉象无涉，故脉象要素为空。", []], "27628": ["主病", "原文未出脉名，述寒号虫粪之主疗。主心腹冷气，示其性温散寒；小儿五疳，说明能消积杀虫；辟疫、治肠风，则示其辟秽解毒、凉血止血；通利气脉、女子月闭，又见其行气通脉、活血通经之功。全段以药效统摄寒凝、疳积、疫毒、肠风、经闭诸候，非论脉。", []], "27629": ["其他", "此段为著书自序，非论病之脉。文中“察脉络之往来”乃泛言考察草木性情与人体脉络之理，非具体脉象描述，故脉象要素从缺。全段重在说明作者幼好本草、考性味、辨地理、察脉络，积数年而成《医门揽要》，属著述缘起，归入其他。", []], "27630": ["其他", "此段为医戒之语，非脉诊专论。文中“合脉理参悟，其应如响”，强调行医者须将脉理与药性、病证合参，方能应验如响；又戒学者不可贪大利而泯救病之思。全段无具体脉象，主旨在于告诫医者重视脉理参悟与医德，故归其他。", []], "27631": ["其他", "此段为序文，推重《滇南草本》附《医门揽要》。文中“明脉理之精微”乃称许该书于脉理阐发精细，非描述具体脉象，故脉象要素从缺。全段历数其辨药性、明脉理、审见症、附汤方之备，赞其有益济世，并记刊刻流传之由，属序跋类文字，归入其他。", []], "27632": ["病机", "原文未出脉名，以“阴血虚弱，神气短少”立论，症见头晕耳鸣、心慌、五心烦热、午后怕冷、夜间发热、腰疼脚酸、白带漏下，皆阴血亏虚、任督二脉亏损所致。药性甘温补肝脾肾，正对虚损病机，属补虚调养之论，非凭脉断病。", []], "27633": ["治法", "原文未言脉象，仅述杏叶防风鲜汁点烧酒服，并于“欲发未发之前”将渣包于脉䐬上，过时方解。此为外敷截疟之法，脉䐬指脉诊部位，非辨脉主病，故归治法，不涉脉象要素。", []], "27634": ["病机", "原文点明“任督二脉虚损”，故脉见虚损。虚损则冲任不充，症见经闭、症瘕、白带、久不胎育；又兼痰火瘫痪、四肢麻木，为虚中夹实。药通经消块、补益任督，于督脉尤甚，示虚损为本、瘀阻为标。", ["虚"]], "27635": ["病机", "原文未出脉名，直指“妇人肝肾虚损，任督二脉亏伤”，故不能孕育，兼白带淋沥。肝肾亏则精血不充，任督伤则胞胎失养，病机属虚损，与#27634脉虚损条相承，主病在妇人胎育。", []], "27636": ["病机", "原文未言脉，论苋菜赤白二种：白入气动痰，赤入血破血，能通血脉、逐瘀血，治二便不通、化虫、去寒热。其病机在血脉瘀滞与寒热不和，故以通逐为用；又诫多食耗散胃气，示攻伐伤正之戒。", []], "27637": ["病机", "原文未出脉名，以“任督二脉亏损，脾气虚而中气下陷，肾气虚而不能纳血”释崩久漏下，喻如“已损之瓶，盛水必浸”。归、仙茅补任督强阳道，蛇果草涩血就下，示虚陷不摄为漏症之本，属病机推论。", []], "27638": ["病机", "原文未言脉象，述人参补五脏、安精神、定魂魄、止惊悸、除邪气，疗肠胃中冷、心腹鼓痛、胸胁逆满、霍乱吐逆，通血脉、破坚积。所主为五脏虚损兼寒积气逆，药性补中寓通，属补虚扶正、调中破积之病机。", []], "27639": ["病机", "原文未出脉名，言通经脉、治骨节风痛、活血行血，采叶塞鼻止鼻衄。其病机在经脉不通、血行不畅，故以通脉活血为治；鼻衄用塞鼻外治，示血热妄行可外取。全段简略，未及脉诊。", []], "27640": ["主病", "原文未言脉，专述还阳参性味功效。其味甘性大温，治诸虚百损、五劳七伤、气血衰败、头晕耳鸣、心慌怔忡、妇人白带漏下、肝肾虚弱、任督损伤，皆属虚损病机。然肺热者忌用，因温燥动火，可致咳血、痰带血丝、鼻衄、烦躁，提示虚寒可投而虚热当禁。", []], "27641": ["主病", "原文未及脉象，论荆芥辛温无毒，主治口眼歪斜，通利血脉、化瘀血死血、驱风利窍，治头风如神。其病机在风邪壅阻、血脉瘀滞，故能疏风化痰、养肌、止吐血、清目、解酒、治筋骨疼痛。作菜食可令不染瘟疫，男妇老幼不落齿，皆取其辛温走散、通利血脉之功。", []], "27642": ["主病", "原文未言脉，述蟹咸寒有小毒，主治胸中邪气热结痛、㖞僻面肿，病机为热结血瘀。能解结散血、散诸热、理经脉、消食，故疗漆疮、疥疮、疟疾黄疸，产后瘀血不下以酒食之，筋骨折伤生捣炒熏。然生不可同柿及荆芥食，发霍乱动风，示其寒滑易伤中。", []], "27643": ["主病", "原文未提脉象，论鲫鱼味甘，和五脏、通血脉。与五味煮食补虚损、温中下气，治痢疾痔漏；作羹治胃弱补中，又治妇人阴疳诸疮、杀虫消积；头烧灰治癞疮。其病机重在脾胃虚弱、血脉不和，故以甘平之品补中通脉，虚损得复则诸症自减。", []], "27644": ["病机", "原文仅言「通血脉而大补阴分」，未出具体脉名。泥鳅味甘淡性平，煮食主治五劳五热、小儿脾胃虚弱，久服健胃补脾。其通血脉、大补阴分，说明病机为阴分亏虚、血脉不畅，故以甘淡平补之品滋阴通脉，使虚热得清、脾胃得健，令人白胖。", []], "27645": ["主病", "原文未言脉，述狗肉味酸咸性温，安五脏、补纯阳、益气、补肾胃、壮阳道、补腰膝，治五劳七伤，补血脉厚肠胃、补下焦填精髓。其病机为阳气不足、脾肾虚寒、精髓亏耗。蹄治癫狂，血补五脏，心除忧恚气，肾治产后疟疾，皆取温补之力，性反商陆、大蒜、杏仁。", []], "27646": ["病机", "原文未出脉象，论盘地藤气味甘甜无毒，性走阳道，行任督二脉，通十二经络，分阴阳、利小便、除内热。其病机为经络壅滞、阴阳不调、内热蕴结，故以甘平之品通经络、分阴阳、利小便而清内热，久服延年、生津养肺、润五脏清六腑、乌须黑发。", []], "27647": ["其他", "此段为厚朴炮制及鉴别条文，非论脉。言黄白轻松者良，炮去内口鼻上米许大者心一小颗，拌糯米同炒，去米取用；独颗团不作两片无皱者号丹龙精，不入药用，误服令人筋脉不收，用黄精小蓝汁合服可愈。厚朴白薇为使，恶桃花，畏秦艽、莽草、礜石，属药性禁忌。", []], "27648": ["治法", "此段专论服药与进食的先后次序，非论脉象。原文提出病在胸膈以上者先食后服药，病在心腹以下者先服药后食，四肢血脉及下部宜空腹旦服，头目骨髓宜饱满夜服，并强调食不宜与药并行，以免药力混滞。所谓食先食后各有次第，属服药方法之治法范畴，与脉象病机无涉。", []], "27649": ["主病", "此段述何首乌性味功效，未及脉象。原文谓其味甘性涩气平，入足厥阴肝经，能养血荣筋、息风润燥、敛肝气之疏泄，故遗精最效；舒筋脉之拘挛，故偏枯甚良；又消瘰疬痈肿、止崩漏淋漓、消痔截疟。所主皆肝血亏虚、疏泄失敛、筋脉拘急之病，属主病范畴。", []], "27650": ["病机", "此段阐发何首乌滋肝养血之理，未言脉象。原文指出肝血温升则生化魂神，血败则温气亡泄、魂神脱矣，以宫室毁坏主人无恙为喻，说明阴为阳之宅。故何首乌滋肝养血则魂神畅茂，治中风左半偏枯甚佳，但宜扶阳而不可助阴，庸工补阴反致杀人，所论重在血败阳泄之病机。", []], "27651": ["主病", "此段述丹参功效，未涉脉象。原文谓其调经安胎、磨坚破滞，一切痈疽痂癞瘿瘤疥癣皆良，症瘕崩漏兼医；《本草》称其破宿血、生新血、落死胎、疏通血脉、治脚膝痿痹，走及奔马，为行血之良品。所主为瘀血阻滞、血脉不通之经产痈疽症瘕诸病，属主病。", []], "27652": ["主病", "此段述泽兰功效，未及脉象。原文称其辛温香散，能行血破瘀、通脉安胎，一切痈疽症瘕、金疮扑打、吐衄诸证皆医；又谓气味和平、不伤迅利，为行经化结之良品。所主为瘀血内结、经脉不通所致痈疽症瘕及跌打吐衄等，属主病范畴，未涉及具体脉象。", []], "27653": ["主病", "此段述益母草性味功效，未言脉象。原文谓其味苦辛、气平，入足厥阴肝经，能活血行经、破瘀通脉，故胎产崩漏、痈疽症瘕、跌打损伤悉效。所主皆肝经瘀血阻滞、血脉不通之胎产经带及痈疽跌打诸证，属主病，全段无脉象描述可录。", []], "27654": ["主病", "此段述三七性味功效，未及脉象。原文谓其味甘微苦，入足厥阴肝经，能和营止血、通脉行瘀。所主为营血不调、瘀血阻滞而致出血与瘀痛并见之证，既止营血之流溢，又通经脉之瘀塞，属主病范畴。全段简短，无脉象要素可提取。", []], "27655": ["主病", "此段述茜草性味功效，未言脉象。原文谓其味苦微寒，入足厥阴肝经，能通经脉瘀塞、止营血流溢。所主为肝经瘀血阻塞经脉而血不循经、溢于脉外之证，一通一止，针对瘀阻与出血并见之病，属主病范畴，全段无脉象描述。", []], "27656": ["主病", "原文以“通女子经脉闭结”言牛膝之效，脉闭结指经脉气血闭阻不通之病机。牛膝疏利水道、破坚症老血，故主小便淋涩疼痛、膝胫痿痹拘挛、女子经闭、男子宗筋软缩等症，皆由瘀血闭结、水道不利所致，通利则闭结自开。", ["结"]], "27657": ["病机", "原文“暖水荣木，复脉清风”点明仙茅功用在于温肾水以荣肝木，使脉复而风清。脉象未明言，然“复脉”示脉道因寒水不温、木失荣养而失常，故治玉麈痿软、皮肤风癞，皆水寒木郁、筋脉失荣之病机。", []], "27658": ["病机", "原文“驱逐脉风”指巴戟天能祛除侵入脉道之风邪。其温补精血、滋益宗筋，故治阳痿精滑、鬼交梦遗，皆精血亏虚、宗筋失养；脉风不去则痂癞生，温补兼驱风，标本兼顾，示病机为精血虚而风邪客于脉。", []], "27659": ["病机", "原文“舒筋脉挛缩”点明乳香所治在筋脉拘急。其活血行瘀，故心腹疼痛、痈疽结肿、跌打溃烂皆因瘀血阻滞；风癞瘙痒、口眼㖞斜乃风邪与瘀血相搏，筋脉失舒。脉象未言，病机重在瘀阻筋脉、风邪内动。", []], "27660": ["病机", "原文“疗女子经脉逆行”指韭菜汁能治经血不循常道而上逆。其治吐衄便溺诸血、打扑损伤诸瘀、胸膈刺痛如锥，皆由瘀血阻滞、血不归经所致。消散胃脘瘀血则逆行之血得降，示病机为瘀血内停、血行逆乱。", []], "27661": ["病机", "原文“筋脉挛缩”与“清散肝火”相应，羚羊角平肝清火，故治心神惊悸、筋脉挛缩，皆肝火炽盛、风动筋急之候；破瘀行血、消瘰疬毒肿，则兼瘀热互结。脉象未言，病机主肝火动风、筋脉失柔。", []], "27662": ["病机", "原文明言中风病因“木郁风动，血燥筋枯，外风虚邪表闭，筋缩四肢”，而木郁之由“全缘水寒土湿，生发不遂”。白花蛇外达筋脉反益枯燥，内行脏腑不能去湿寒，故斥为不善。此段论中风病机为水寒土湿、木郁风动、血燥筋枯。", []], "27663": ["病机", "原文引《素问》治女子血枯，症见唾血、四肢清、目眩、前后血，明言“血枯必由夫血脱，血脱之原，缘瘀滞不流，经脉莫容”。乌贼骨行瘀固脱兼擅，故止吐衄崩带、消䕡瘕。病机为瘀滞不流致血脱，经脉失容。", []], "27664": ["其他", "此段专论鲮甲药性，言其“善穿通走窜，透坚破结”，能开经络关节痹塞、通经脉、下乳汁、逐风湿，所主皆气血壅滞、经络闭阻之证。原文未及脉象，故无从以脉论病机；末言瘫痪㖞斜、缓急拘挛“未必能也”，而引达木荣筋之药可直透拳曲拘挛之处，提示其功在通破而非荣养，与脉诊无涉。", []], "27665": ["其他", "此段引《礼记》“医不三世，不服其药”及郑注、孔疏，考“三世”为《黄帝针灸》《神农本草》《素女脉诀》，并辨本草源流。全段属医史文献考证，虽涉“脉诀”之名，实未论脉象主病，故脉象要素为空，主旨归于其他，不得以脉诀二字附会病机。", []], "27666": ["其他", "此段论“儒者知医之理”，举和、缓通《周易》辨皿虫之义，又推神农为千古大儒，强调传正、识广、业神方足为医。通篇言医儒相通与本草传承，未及脉象、症候，故脉象要素为空，主旨属其他，不可强解为平脉或病机。", []], "27667": ["其他", "此段为药物条文，味甘寒，主眚盲耳聋，明目利九窍、通血脉、养精神，久服轻身延年。所述为药效主治，未言脉象，故脉象要素为空；其“通血脉”虽涉血脉，然非脉诊之脉，主旨仍归其他，不得据药效反推脉象。", []], "27668": ["其他", "此段味甘平，主心腹结气、伤中伤饱、胃络脉绝、羸瘦短气，久服轻身不饥。文中“胃络脉绝”指胃络气血阻绝之病机，非脉象描述；全段为药物主治，未及诊脉，故脉象要素为空，主旨属其他，不可将“脉绝”误作脉象要素。", []], "27669": ["其他", "此段味苦寒，主膀胱热、利小便、补中益精气，久服耳目聪明、轻身耐老，并附“地脉”异名及“脉作麦”之校勘。全段为药物条文，未论脉象；异名中之“脉”字系药名，非脉诊，故脉象要素为空，主旨归其他。", []], "27670": ["其他", "此段味辛寒，主身热、四肢寒厥，利小便、通血脉、明目去翳眇、下三虫、杀蛊毒。所述为药效主治，虽见“身热”“四肢寒厥”症候，然未提脉象，无从以脉析机，故脉象要素为空，主旨属其他，不得以寒热症候代填脉象。", []], "27671": ["其他", "此段味辛平，主去恶虫、除脾胃寒热、通利九窍血脉关节、令人不忘，一名附支。全段为药物主治条文，未及脉象；其中“血脉”“关节”指药效所通之处，非脉诊内容，故脉象要素为空，主旨归其他，不可附会为通脉之脉象。", []], "27672": ["其他", "本段为《吴普》对狗脊的释名与药性记载，文中'有赤脉'指药材根茎皮部赤色纹理，非诊脉之脉象。全段述狗脊别名、性味及形态特征，未涉及病机或主病，故脉象要素为空，主旨归入其他。", []], "27673": ["主病", "本段述木耳类药性味甘寒，主'伤中、五劳六极、羸瘦，崩中脉绝'，'脉绝'指崩中失血致血脉虚竭之症，非脉象描述。药能补虚益气，故所主为虚损劳伤、崩漏脉绝之病，兼及症瘕积聚、寒热无子等，属主病范畴。", []], "27674": ["主病", "本段载咸平之药主'伤中脉绝，阴不起'，'脉绝'言伤中致血脉虚绝，非脉象；又主强志益气、长肌肉、生子。悬蹄主惊痫、瘛疭、乳难等。全段以药物所主病症为主，脉绝为症状描述，故脉象要素空，归主病。", []], "27675": ["主病", "本段述苦微寒之药'主逐瘀血，破下血积、坚痞症瘕、寒热，通利血脉及九窍'。'通利血脉'指药效作用于血脉，非脉象。全段主旨为瘀血积块、症瘕寒热之病，故归主病，脉象要素为空。", []], "27676": ["主病", "本段载甘平之药'主女子赤沃，止血养精，保血脉，益气'。'保血脉'言药能护养血脉，非脉象描述。所主为女子赤沃下血之病，兼能止血养精、令人肥健嗜食，全段以药物主治为旨，故归主病，脉象空。", []], "27677": ["病机", "本段强调疗病'先察其原，先候病机'，以'五脏未虚，六腑未竭，血脉未乱，精神未散'为可治之机。'血脉未乱'指血脉未至败乱，属病机判断而非具体脉象，故脉象要素空。全段论病机浅深与预后，归病机。", []], "27678": ["治法", "本段论服药与进食先后：病在胸膈以上先食后服药，病在心腹以下先服药后食，病在四肢血脉宜空腹旦服，病在骨髓宜饱满夜服。'血脉'指病位在血脉，非脉象。全段言服药时机之法，故归治法，脉象要素为空。", []], "27679": ["治法", "本段论奇偶复方之制，好古言'伤寒见风脉，伤风得寒脉，为脉主证不相应，宜以复方主之'。'风脉''寒脉'指脉与证不符之象，然段旨在于复方治法，非专论脉象病机，故脉象要素不取，归治法。", []], "27680": ["病机", "原文以“脉有胃气曰生，无胃气曰死”立论，强调胃气即后天元气，以谷气为本。虽未出具体脉名，但脉之生死取决于胃气存亡，故脉象模糊时当察胃气之有无。胃气一败则百药难施，诸病如阴虚阳虚、中风中暑、泻利滞下、胎前产后等皆以保护胃气为先务，说明胃气盛衰决定脉之生机与病之预后。", []], "27681": ["兼症", "心脉弦而不洪，肝脉弦而不长，左尺脉浮洪。弦为血少，心脉不洪示心血不足；肝脉弦而不长，因多怒肝气不和，怒则气上逆。左尺浮洪，肾属水冬脉沉，浮洪为肾不足、肾家有火，故小便疾速不能忍且有余沥，大便燥结，语言謇涩，饮食少不易消，皆火盛津亏、舌络劲急之兼症。", ["弦", "浮", "洪"]], "27682": ["病机", "原文答曰“弦为血少”，心脉弦而不洪因心血不足；肝脉弦而不长因多怒肝气不和、久病多郁。肾属水冬脉沉，今左尺反浮洪，是“诸浮者，肾不足也”，肾家有火则真阴日亏、津液日少，舌络劲急故语言不利，火性急速故小便疾出不能忍且有余沥，大便燥结。脉应沉实而反浮洪，为失常候，揭示阴虚火旺、津亏舌络失养之病机。", ["弦", "沉", "浮", "洪"]], "27683": ["误治", "原文论伤寒温疫初发邪在表，当急表散，汗后“身凉脉静”则愈。若投药濡滞或病重药轻，不散之于表，致邪热内结，病属三阴须下乃愈；内虚之人不胜下药多致危殆，少阴咽痛等证又不宜下，或成狐惑、虫蚀肛门。虽未出具体脉名，但以“脉静”为邪解之征，强调失于早散、误治致邪陷之害。", []], "27684": ["主病", "脉浮无力为表虚之典型脉象。浮主病在表，无力为正气不足、卫外不固，故见自汗恶风、洒淅寒热、喜就温暖。表虚则腠理不密，营卫不和，汗出而恶风；阳气不足故喜就温暖。此脉此证，主表虚证，与桂枝汤证之营卫不和、卫强营弱病机相应。", ["浮", "虚"]], "27685": ["预后", "太阳病发热恶寒头痛项强身痛，脉虽浮洪而不数，多不传经；烦躁脉急者，是欲传经。浮洪为邪在表、阳气奋起抗邪，不数则热势未盛，故不传；脉急则邪热内迫、正邪交争剧烈，故预示传经。原文以脉之数急判断传经与否，指导先发汗解表，用羌活汤为主。", ["浮", "洪", "数", "急"]], "27686": ["主病", "正阳阳明胃家实热，证见不大便、自汗、潮热、口渴咽干鼻干、呕、目眴不得眠、畏人声木声火、不恶寒反恶热、甚则谵语狂乱循衣摸床，脉洪大而长。洪大而长乃阳明热盛、邪结于里、正气抗邪之象。若表证已罢，脉缓、小便利，是病解之征。脉象由洪大而长转为缓，反映邪退正和。", ["洪", "大", "长", "缓"]], "27687": ["预后", "阳明病衄血因失于发汗，邪热不得外解而迫血妄行。原文列多种脉象判断预后：脉滑而数者，热盛于里；脉反微涩者，正虚邪滞；脉浮紧、浮、浮迟、浮而涩，示邪在表或表虚；脉短者死，为正气衰败；脉和者不死，胃气尚存；脉弦者生，木气未绝。诸脉反映邪正盛衰与胃气存亡，决定病之吉凶。", ["滑", "数", "微", "涩"]], "27688": ["主病", "本段论少阳病脉证。脉弦细为少阳主脉，弦主肝胆，细为血少气结；脉小者示邪衰欲愈；脉沉紧主邪入少阳之里，胁下硬满、干呕不能食，故与小柴胡汤和解。诸脉皆围绕少阳枢机不利、胆火上炎之病机。", ["弦", "细", "小", "沉"]], "27689": ["治法", "伤寒瘥后更发热，示余邪未尽。脉浮者邪在表，故以汗解；脉沉实者邪在里，故以下解。此以脉定汗下之法，浮主表、沉实主里实，体现凭脉辨证、因势利导之治则。", ["浮", "沉", "实"]], "27690": ["主病", "百合病由百脉一宗、悉致其病，神思默然、如寒无寒、如热无热、口苦、小便赤，为心肺阴虚内热之候。原文未出脉象，以症测机，主阴虚内热、神志不宁，故以百合地黄汤等随汗吐下后分别施治。", []], "27691": ["治法", "暑伤气分，其气必虚，脉散为气耗不收之象。伤气则无气以动，故治当补气为本，用清暑益气汤、生脉散等。惟肺热多火者忌人参、术，恐助火耗气，示脉散主气虚而治有宜忌。", ["散"]], "27692": ["治法", "脉散主气虚无以收摄，故以人参、白术、半夏、橘皮、茯苓等健脾益气、和胃化湿，兼服生脉散以敛耗散之气。此段承上暑伤气分、脉散气虚之旨，示补气敛散之方药。", ["散"]], "27693": ["病机", "湿邪为病，其性重浊黏滞，故见诸痉强直、积饮痞膈、中满霍乱、体重胕肿肉如泥、按之不起。湿伤皮肉筋脉则筋骨疼痛、腰重不可转侧；湿在上则呕吐头重胸满，在中则腹胀泄泻，在下则足胫跗肿、脚气臁疮。原文未出脉，以症明湿邪弥漫三焦之病机。", []], "27694": ["其他", "此段为丹砂（朱砂）药性主治，非论脉。丹砂味甘微寒无毒，主身体五脏百病，养精神、安魂魄、益气明目、通血脉、止烦满消渴，杀精魅邪恶鬼，除中恶腹痛。其机在清镇少阴君火、安定神明，使五脏安和、血脉通利。", []], "27695": ["病机", "此段疏解丹砂药性之理。丹砂禀地二火气兼天七之气，色赤法火，中含水液，为清镇少阴君火之上药。火不妄炎则金木得平，魂魄自定，气力自倍；心火宁谧则阴分无热而血脉自通，烦满消渴自除。故能辟除阴恶杀厉之气，久服通神明。", []], "27696": ["其他", "原文仅以「脉涩不行」点出，涩为血行不畅、瘀阻之象，与广疮结毒烂坏鼻梁、阴蚀等恶疮结毒相应，示毒瘀互结、气血壅滞。然此段主体为钟乳、牛黄等方药与钟乳煎补益强壮、焚香透膈散治劳嗽，脉涩仅作引端，非全段主旨，故归其他。", ["涩"]], "27697": ["其他", "本段为朴硝性味功用，未出脉名。所述「五脏积聚」「久热胃闭」「破留血」「腹中痰实结搏」「通经脉」等，皆从药性苦辛大寒、推陈致新立论，非据脉辨证，故脉象要素为空，主旨归其他，不涉具体脉机。", []], "27698": ["病机", "此疏阐发芒硝苦辛大寒、咸能软坚辛能散结之性，谓「邪热盛则经脉闭」，热淫于内治以咸寒，结散热除则经脉自通、二便自利、月水复故；又言石淋膏淋由积热胶结，非辛苦大寒推荡不能除。全段以药性推病机，未出脉象，故脉空而主旨归病机。", []], "27699": ["其他", "引《仓公传》淳于意诊菑川王美人「脉躁」，躁者有余病，饮硝石一剂出血而安，此去蓄血之验，示脉躁主邪热有余、蓄血内结。然本段主体为朴硝含咽治喉痹、口舌生疮及硝石诸方，脉躁仅一例佐证，非通段主旨，故归其他。", ["躁"]], "27700": ["其他", "本段述益元散（天水散、六一散）解中暑伤寒疫疬、除烦热、通九窍六腑、去留结、通经脉、催生下乳等功用，全为方药主治，未及脉象，故脉象要素为空。其「去留结，通经脉」虽涉病机语，然段旨在于方药运用，归其他为宜。", []], "27701": ["其他", "本段为《本经》空青性味主治，言其主青盲耳聋、明目利九窍、通血脉、养精神、益肝气、利水道、下乳汁、破坚积等，纯属药性记载，未出脉名，亦无脉症对应，故脉象要素为空，主旨归其他。", []], "27702": ["病机", "此疏论空青甘酸大寒入肝主目，谓「肝肾虚则内热，怒则火起于肝」而生障翳；「水涸火炎耳聋」，肾热解则火息水生而聪复；九窍不和无非火壅，肝火则血热气逆而血脉不通，凉肝除热则精气自益、血脉自通。全以药性推阐目病、耳聋、血脉不通之火郁病机，未出脉象。", []], "27703": ["病机", "此疏辨紫石英气温味甘辛，入少阴厥阴，谓心属阳本热，虚则阳气衰而寒邪乘之，致上气咳逆、气结寒热心腹痛，药温能除寒、甘能补中；惊悸由心君怯弱，得镇坠则心安；女子风寒在子宫绝孕，因肾与心包络虚而风寒乘之。全段以药性推病机，未出脉象。", []], "27704": ["病机", "原文未直接言脉，但以“涩可去脱”论赤石脂之功。其气薄味厚，降而能收，故主大肠下后虚脱、腹痛肠澼、女子崩中漏下，皆取收涩固脱之义。又甘温入血益血，通畅血脉，涤除湿热，故主痈疽疮痔。全段以药性推病机，非论脉象。", []], "27705": ["病机", "原文引《内经》“咸走血，血病无多食咸，多食则脉凝涩而色变”。过食咸味，涩血脉而致凝滞，故脉见凝涩、色亦变异。凡血病及喘嗽、水肿、消渴皆忌咸，以其伤肺引痰、涩血脉、助水邪、走精液，皆由咸味凝涩为患。", ["涩"]], "27706": ["主病", "原文未言脉，专述二气砂甘温无毒，主五脏百病，养神安魂魄，益气明目，通血脉，止烦满，益精神。其功在调养五脏、安神益气、通利血脉，故所主为神魂魄不安、气虚目暗、血脉不通、烦满等症，属补益安神之品。", []], "27707": ["病机", "原文未言脉，论灵砂由硫汞制而成，水火既济，二气交合，能升降气血、除邪养正。故主五脏百病、益精神、安魂魄，又主上盛下虚、痰涎壅盛、头旋吐逆、霍乱反胃、心腹冷痛，取其镇坠之神丹，使阴阳交合、气血升降复常。", []], "27708": ["兼症", "原文载九窍出血因暴惊而得，“其脉虚者”，以惊则气浮，神魂发越，阳气暴壅，故脉虚而血不循经。治用灵砂丹镇坠，使神魂复安、血自循经。此脉虚非血热妄行，不可误用凉药，点明惊则气浮、阳气暴壅之病机。", ["虚"]], "27709": ["主病", "原文未言脉，述伏龙肝得火土之气，味辛微温，甘能补中，微温能调和血脉。故主妇人崩中、吐血、咳逆、止血，以失血过多中气必损；又消痈肿毒气，辛散咸软；催生下胞、小儿夜啼，取其镇重下坠、性本冲和。", []], "27710": ["主病", "原文未言脉，述代赭石味苦甘寒，主鬼疰、贼风蛊毒，杀精物恶鬼，腹中毒邪气，女子赤沃漏下、带下百病、产难胎衣不出、堕胎，养血气，除五脏血脉中热、血痹血瘀，大人小儿惊气入腹及阴痿不起。皆取苦寒凉血、镇重下坠、解毒泄火之功。", []], "27711": ["病机", "原文未言脉，疏代赭石禀土中阴气，气薄味厚，阴也降也，入手少阴、足厥阴。心君虚则气怯而百邪易入，故主鬼疰邪气、精物恶鬼、惊气入腹；肝心二经血热则血脉中热、血痹血瘀、赤沃漏下、带下；苦寒泄有余之火，故起阴痿；重而下坠，故主产难。", []], "27712": ["病机", "原文论古文钱辛凉走下焦阴分，散凝滞气血、开壅塞道路，故主目赤翳障、妇人产难、心腹痛、月隔、五淋及跌扑损伤。其病机核心为气血凝滞、道路闭塞，药性辛凉能散能开，诸证皆由壅塞不通而致，非脉象所主，故脉象要素为空。", []], "27713": ["主病", "原文列菊花主治风头眩肿痛、目欲脱泪出、皮肤死肌、恶风湿痹、腰痛去来、胸中烦热等，并言利五脉、调四肢。所主病机为风热上攻、血虚气滞、风湿痹阻，药性苦甘平能泄热益血散结，诸证相应，非以脉象立论，故脉象要素为空。", []], "27714": ["病机", "原文以菊花生发三时、独禀金精专制风木，释其去风之要。诸风掉眩皆属肝木，风为阳邪势必走上，血虚则热、热则生风、风火相搏，故主头眩肿痛、目欲脱泪出；腰痛去来为血虚气滞。全段紧扣风热、血虚、气滞之病机，非脉象描述。", []], "27715": ["主病", "原文述人参味甘微寒微温，主补五脏、安精神、定魂魄、止惊悸、除邪气、明目开心益智，疗肠胃中冷、心腹鼓痛、胸胁逆满、霍乱吐逆，通血脉破坚积。所主病机为五脏气虚、精神不安、阳气不足兼邪气内阻，药性甘温升补，诸证相应，非脉象所主。", []], "27716": ["病机", "原文论人参得土中清阳、禀春升少阳之气而生，气味俱薄、浮而升，为阳中之阳，又阳中微阴。辨《本经》微寒与《别录》微温二义相蒙，言微则寒温相近，实指其生长真元升发之气。全段阐发药性升降浮沉与寒温之辨，属药性病机分析，非脉象。", []], "27717": ["治法", "原文以人参配伍诸药列各方治：同附子干姜肉桂治寒厥指爪青黯，同附子五味子治阳气脱，君五味子麦门冬治肺虚气喘，名生脉散。脉散者，阳气外脱、肺气耗散之象，故以人参益气固脱、五味子收敛、麦冬养阴，使散越之气复敛，诸方皆围绕气虚阳脱、真气不归元之机。", ["散"]], "27718": ["病机", "原文论人参补五脏真阳之气，其性有所不宜，误用则不见其利徒见其害。所列当用诸证：虚羸尪怯、劳役饥饱所伤、努力失血致阳气短乏陷入阴分、中暑伤气、呕吐泄泻霍乱转筋、脾虚不磨食、真阳衰少完谷不化下利清水、中风失音、产后气喘，皆属阳气虚乏之病机。", []], "27719": ["病机", "原文论天门冬禀大寒初之气，味厚于气，阴也降也，为除肺肾虚热要药。热则生风、暴则属火，湿乃湿热之谓，苦泄湿寒除热，热去风止湿泄痹瘳；湿热下流客肾则骨痿，味苦气寒入肾除热坚软故强骨。全段紧扣肺肾虚热、湿热偏痹之病机，非脉象。", []], "27720": ["其他", "此段为甘草本草主治，未涉脉象。原文述其\"主五脏六腑寒热邪气，坚筋骨，长肌肉\"，以味甘平无毒、为九土之精立论，功在安和脏腑、解百药毒。所主乃药性功用而非脉诊病机，故脉象要素为空，不可据药效反推脉候。", []], "27721": ["病机", "此段为甘草疏解，阐发\"味甘，气平无毒，正禀土中冲和之阳气\"，谓其可升可降、阴中阳。以甘能益脾、脾主肌肉四肢，解\"长肌肉倍力\"；以甘入血分缓中除热，解\"金疮肿\"；以甘味属土、土位乎中，解\"温中下气\"。全在推药性所主之病机，非论脉。", []], "27722": ["其他", "此段为干地黄本草主治，述其\"主折跌绝筋，伤中，逐血痹，填骨髓，长肌肉\"，兼主五劳七伤、女子伤中胞漏下血、破恶血溺血等。味甘苦寒无毒，生者尤良。通篇言药效主治，未及脉象，故脉要素为空，不得附会脉候。", []], "27723": ["病机", "此段为干地黄疏解，以\"禀仲冬之气以生\"\"至阴之药\"立论，谓其补肾家要药、益阴血上品。解\"逐血痹\"为养血和肝、痹因虚而风寒湿客之；解\"填骨髓长肌肉\"为血王则髓满、阴足则肌肉自长；五劳七伤皆\"阴虚内热，真阴不足之候\"。纯论药性病机，无脉象。", []], "27724": ["其他", "此段述某药配伍主治：君莲实、山药、人参能实脾止泄嗜食，加五味子、肉豆蔻、砂仁治肾泄；合诸子能益脾肾、固精种子、明目；君术、人参、牛膝治腰膝积冷顽麻。引王好古\"补肝脏虚故去风，专主腰膝\"。全为配伍用法，未涉脉象。", []], "27725": ["其他", "此段为麦门冬本草主治，味甘平微寒无毒，主\"心腹结气，伤中伤饱，胃络脉绝，羸瘦短气，身重目黄，心下支满，虚劳客热，口干燥渴\"，止呕吐、愈痿蹶、强阴益精、令人肥健有子。通篇列药效主治，未言脉象，脉要素从缺。", []], "27726": ["病机", "此段为麦门冬疏解，谓其\"禀春阳生生之气\"\"实阳明之正药\"。解\"心腹结气\"为邪热结于中、清和微寒能散热结下逆气；\"胃络脉绝\"因脾无所禀而羸瘦短气；\"身重目黄\"属脾胃湿热；\"心下支满\"为脾虚湿滞；\"虚劳客热口干燥渴\"因虚劳热客中焦。论药性所主病机，非脉诊。", []], "27727": ["治法", "此段言麦门冬配伍治法：同人参、五味子为生脉散，\"能复脉通心\"，夏月暑伤气服之良。原文标\"脉散\"，指暑热伤气、气阴耗散而脉见散象，故以生脉散复脉通心；肺热者去人参，火盛加黄柏、砂仁、甘草。所论为据脉散施治之方，非单论病机。", ["散"]], "27728": ["病机", "原文言升麻“得葱白、白芷，缓带脉之纵急”，带脉纵急指带脉拘急之病机，多因阳气不升、清阳不达所致。升麻禀清阳之气，浮而升，入足阳明、太阴引经，能升阳气于至阴之下，故可缓纵急。此脉象反映阳气郁滞、带脉失约之病机，主中恶腹痛、时气毒疠等症。", ["纵", "急"]], "27729": ["病机", "原文未识脉名，但述薏苡仁“性燥能除湿，味甘能入脾补脾，兼淡能渗泄”，主筋急拘挛、风湿痹。其病机为湿邪害人皮肉筋脉，风寒湿合而成痹。湿去则脾胃安，中焦治则荣养四肢、通利血脉。此段论湿邪阻滞、脾失健运之病机，与筋急拘挛、水肿、不仁等症相应。", []], "27730": ["治法", "原文载“同人参、麦门冬，名生脉散，能复脉通心”，脉散指脉气耗散之象，多因气阴两虚、心脉失养所致。生脉散用人参、麦冬、五味子益气养阴复脉，故能治脉散。此段以方论治，说明脉散之病机为气阴耗散，主肺虚久嗽、肾泄等症，属治法范畴。", ["散"]], "27731": ["病机", "原文引仲景治少阴病发热、脉沉，用麻黄附子细辛汤及麻黄附子甘草汤。脉沉主里，少阴病发热而脉沉，为阳虚外感、寒邪直中少阴之病机，故用麻黄发散、附子温经、细辛通阳。此脉沉说明寒邪在里、阳气不振，与发热、喘满咳嗽等症相应。", ["沉"]], "27732": ["主病", "原文未识脉名，述药“主去恶虫，除脾胃寒热，通利九窍血脉关节”，疗脾疸常欲眠、心烦哕、耳聋、痈肿诸结不消等。其病机为脾胃寒热错杂、湿热内蕴，致九窍血脉关节不通。此段主病，说明该药能通利湿热、散结消痈，与脾疸、耳聋、痈肿等症相应。", []], "27733": ["病机", "原文未识脉名，论通草“禀清秋之气……能助西方秋气下降，故利小便，专泻气滞”。其病机为肺受热邪，津液气化之源绝，则寒水断流；膀胱湿热癃闭，则小便不通。证见胸中烦热、口燥舌干、小便淋沥或闭塞。此段阐发湿热气滞、水道不利之病机，与淋闭、胫酸脚热相应。", []], "27734": ["主病", "原文未识脉名，述芍药“主邪气腹痛，除血痹，破坚积，寒热疝瘕”，通顺血脉，散恶血，去水气，利膀胱大小肠。其病机为血痹、坚积、水气内停，气血不通。芍药苦酸微寒，能破坚积、通血脉、利小便。此段主病，与腹痛、血闭、疝瘕、泻血等症相应。", []], "27735": ["病机", "原文言芍药“禀天地之阴，兼得甲木之气”，气薄味厚，可升可降，为手足太阴引经药，入肝脾血分。脉自和指脉象调和，无太过不及。芍药酸收甘缓，补阴血、通气除肺燥，故能维持脉和。此段论芍药调和肝脾、养血通脉之病机，与腹痛、血痹、坚积等症相应。", ["和"]], "27736": ["病机", "原文论木芍药色赤主破散通利，专入肝家血分，故主邪气腹痛。其除血痹、破坚积，因血瘀则发寒热，行血则寒热自止；血痹疝瘕皆血凝滞而成，破凝滞之血则痹和疝瘕自消。凉肝通顺血脉，散恶血逐贼血；荣气不和逆于肉里结为痈肿，行血凉血则痈肿自消。妇人经行属足厥阴，入肝行血故主经闭；目赤为肝热，酸寒凉肝故治目赤；肠风下血为湿热伤血，血凉则止。全段以药测证，明血瘀、血热、肝经郁滞之病机。", []], "27737": ["病机", "原文以狗脊味苦气平、甘微温无毒，苦燥湿、甘益血、温养气，为补而能走之药，入足少阴。肾主骨，肾虚则腰背强、机关有缓急之病，滋肾益气血则腰背不强、机关无缓急之患。周痹寒湿膝痛，乃肾气不足而为风寒湿邪所中，得补则邪散痹除而膝利。老人肾气衰乏、肝血亦虚则筋骨不健，补肾入骨故利老人；失溺不节为肾气虚脱。腰痛亦指肾虚为湿邪所乘。全段紧扣肾虚立论。", ["虚"]], "27738": ["妇人", "原文列狗脊配伍应用：得鹿茸、白蔹、艾、茯苓、蛇床子，治室女冲任带脉三经虚寒下白带。冲任带三脉同司约束，虚寒则带脉失约、白带下注，故以温补冲任带脉之品治之。得牛膝、菟丝子、地黄、山茱萸、白胶、杜仲，则固精强骨壮腰肾，针对肾虚精滑、腰骨不健。得沉香、牛膝、石斛、木瓜、五加皮、白鲜皮、菊花、漆叶、蒺藜子，能通利关节、除五缓六急。全段以配伍见冲任带虚寒及肾虚、关节不利之病机。", ["虚"]], "27739": ["病机", "原文论紫菀味苦温兼辛，入手太阴兼入足阳明，苦泄辛散温行，辛先入肺，肺主诸气，故主咳逆上气、胸中寒热结气，去蛊毒亦辛之力。痿蹶者，阳明湿热熏蒸于肺，肺热津液不能下滴，伤其气化以困水之上源，故为痿蹶。肺为五脏华盖主诸气，肺安则朝百脉、散精布液于各脏，故安五脏；疗咳逆吐脓血、止喘悸，散肺气之邪；治五劳体虚不足；小儿惊痫亦虚而有热，热散则惊痫自止。全段明肺热气化不行、虚热之病机。", []], "27740": ["病机", "原文论白鲜皮苦寒兼咸，降多于升，入足太阴阳明兼手太阳。苦泄热、寒除热，故主头风有火证；性寒而燥能除湿热，故主五疸。咳逆为实火上冲，得寒而散则止。淋沥及女子阴中肿痛，皆下部湿热乘虚客肾与膀胱所致。湿痹死肌、不可屈伸起止行步，为地之湿气害人皮肉筋脉，脾主四肢恶湿喜燥，湿邪所干故四肢不安。时行腹中大热、饮水大呼欲走为邪热盛；小儿惊痫亦热则生风之候。散湿除热则诸证济。全段明湿热、实火、热生风之病机。", []], "27741": ["病机", "原文论藁本辛气温兼苦，入足太阳经，温能通、苦能泄、大辛善散、气厚上升。妇人疝瘕、阴中寒肿痛、腹中急，皆太阳经寒湿邪为病；风头痛为风中太阳经，药入本经故悉主之。凡痈疮皆血热壅滞、毒气浸淫肌肉以致溃烂不收，辛散苦泄则毒散滞消、肌肉自长。悦颜色即去风作面脂之义；辟雾露、疗风邪为辛温芬芳开发升散之力；亸曳、金疮及恶风鬼疰流入腰痛冷，能化小便通血。全段明太阳寒湿、血热壅滞之病机。", []], "27742": ["病机", "原文论地榆苦甘酸微寒，气薄味厚沉而降，入足厥阴少阴、手足阳明经。妇人乳痓痛为厥阴肝经有热、血分热壅所致；七情伤于带脉故带下；五漏为阳明大肠湿热伤血病；血热则肿而作痛，恶肉亦血热极则瘀、肿而成恶肉；金疮伤则出血，血出必发热作痛；脓血不止皆血热所致；诸瘘恶疮莫不由血热所生。苦寒凉血泄热，热散则血活肿消。味兼甘酸性行带补，故补绝伤及产后内塞。全段明血热、湿热伤血之病机。", []], "27743": ["病机", "原文论泽兰味苦甘入血，兼春气故微温，兼酸入足厥阴太阴。苦泄热、甘和血、酸入肝、温通荣血，故主痈肿疮脓及妇人吹乳、乳结，止衄血并中风余疾。佐益脾土之药、用防己为使，则主大腹水肿、身面四肢浮肿、骨节中水气。通九窍、利关脉、养血气、破宿血、消鹥瘕、产前产后百病；通小肠、长肉生肌、消扑损瘀血，治鼻衄吐血、头风目痛、妇人劳瘦、丈夫面黄；主产后腹痛、频产血气衰冷成劳瘦羸、通身面目大肿。全段明血瘀水停、血气衰冷之病机。", []], "27744": ["主病", "原文仅言「脉浮」而未展开，此段主旨实为防己的配伍与主治。脉浮在此提示风水在表，故陶氏称防己为「疗风水要药」，洁古用汉防己、龙胆草泻下焦湿热。防己大苦寒，泻血中湿热、通滞塞，须以二术、茯苓等补益药为主而防己为使，方能免瞑眩之患，说明浮脉所主之风水湿肿当以补泻兼施为法。", ["浮"]], "27745": ["病机", "本段未出脉名，专论牡丹皮药性。其味苦微辛、气寒，入血分凉血热，故「寒热者，阴虚血热之候也」；中风瘛疭、痉、惊痫皆因阴虚内热、荣血不足，热去血凉则新血生、阴气复而火不炎，热生风之证自除。痈疮由热壅血瘀而成，凉血行血故疗之。全段以阴虚血热、热壅血瘀为病机核心。", []], "27746": ["治法", "本段未涉脉象，列郁金诸方。郁金同韭菜、降香、当归、生地、童便治怒气伤肝吐血及鼻衄唾血、经脉逆行，是取辛散苦泄以行血降逆；配明矾丸治妇人癫狂十年不愈，因「惊忧痰血总聚心窍」，郁金入心去恶血、明矾化顽痰，故服后心胸间有物脱去而苏。所主病机为肝郁气逆、痰血蒙蔽心窍。", []], "27747": ["主病", "本段无脉名，集破故纸诸方。所治为「精气不固」「小便无度，肾气虚寒」「小儿遗尿，膀胱冷也，夜属阴，故小便不禁」及下元虚败、脚手沉重、夜多盗汗。诸证皆归肾气与膀胱虚寒、下元不固，故用破故纸温补，佐茴香、菟丝子、胡桃、沉香以壮筋骨、益元气，体现虚寒不固之病机。", []], "27748": ["主病", "原文引仲景《金匮要略》「治嗽而脉浮，用泽漆汤中有白前」，脉浮主表、主肺气不降。白前能保定肺气，治嗽多用，佐以温药尤佳；《深师方》治久咳上气、体肿短气、昼夜倚壁不得卧、常作水鸡声，是水气射肺之候，白前汤以白前配紫菀、半夏、大戟逐水降逆。浮脉在此示邪在肺卫、水气上逆之病机。", ["浮"]], "27749": ["病机", "本段未出脉名，论莎草根（香附）药性。其禀温燥之气，味甘苦辛，入足厥阴气分，为「血中之气药」，能行十二经八脉气分。辛主散、苦温主降泄，肝主怒而苦急，怒则气上逆、逆则胸中热，降则肝气平而胸中热除。所治心腹客热、膀胱连胁下气妨、忧愁不乐、霍乱吐泻，皆属气机郁滞、肝气上逆之病机。", []], "27750": ["病机", "本段无脉象，疏薄荷药性。其辛凉浮升，入手太阴、少阴，辛合肺主皮毛，故贼风伤寒邪在表者发汗则解；辛香通窍，治腹胀满霍乱，为小儿惊风、风热引经要药。文中特辨《食疗》所载宿食不消、下气、劳乏三疗俱非，因薄荷本非脾胃家药、上升之性难主下气、劳乏属虚非散可解，强调其病机在表邪与风热。", []], "27751": ["病机", "本段未出脉名，论附子气味大辛大热、有大毒，走而不守，浮中沉无所不至。《本经》主风寒咳逆邪气、寒湿踒躄、拘挛膝痛、脚疼冷弱不能行步，皆由风寒湿三邪客之，上焦则咳逆、下焦则踒躄；症坚积聚血瘕则属血分虚寒、凝而不行。全段以寒湿客邪、血分虚寒凝滞为病机，故取附子大热善走以祛邪。", []], "27752": ["主病", "原文言“小结胸痛，正在心下，按之则痛，脉浮而滑者”，浮为热邪偏表，滑为痰热内结，故脉浮滑主痰热互结于心下之小结胸证，按之则痛，治以小陷胸汤清热化痰开结。", ["浮", "滑"]], "27753": ["其他", "本段未直接论脉，主要阐述桔梗、甘草等药在胸中痞满、结胸、肺痈、咽痛等证中的运用，虽提及“脉数”但未展开，故脉象要素从略，主旨为方药主治。", []], "27754": ["其他", "本段为旋覆花性味功用记载，未涉及脉象，主述其能消痰饮、除水、通血脉等，故无脉象要素可录，归类为其他。", []], "27755": ["病机", "本段为旋覆花药性疏解，未直接论脉，但阐明其咸能软坚、甘能缓中、温能通行，故主结气胁下满、心脾伏饮惊悸等，病机为饮邪内结、气机不畅。", []], "27756": ["主病", "原文“治半产漏下，虚寒相搏，其脉弦芤”，弦主虚寒相搏、气机拘急，芤主失血，故脉弦芤主半产漏下后虚寒内搏、血虚失养之证，治以旋覆花汤通络散结。", ["弦", "芤"]], "27757": ["病机", "本段为射干药性疏解，未直接论脉，主述其苦能下泄、辛能散结，故主咳逆上气、喉痹咽痛、散结气等，病机为火金相搏、气结痰壅。", []], "27758": ["主病", "原文“治心下留饮坚满，脉伏，其人欲自利反快”，伏脉主水饮内结、阳气被遏，故脉伏主留饮坚满之证，治以甘遂半夏汤攻逐水饮。", ["伏"]], "27759": ["病机", "本段为豨莶草药性疏解，未涉及脉象，主述其苦寒入血分、祛风除湿活血，故主湿热生䘌、四肢麻痹、骨间疼痛等，病机为风湿热邪痹阻。", []], "27760": ["主病", "黑黄急病证见面黑黄、身如土色而脉沉，沉主里、主阴邪内郁，故脉沉为阴黄在里之征；原文又言“青脉入口者死”，是阴邪深入、肝色上现之危候，与烙口中黑脉及诸穴以泄阴邪相应。", ["沉"]], "27761": ["病机", "此段论仙茅辛热入命门补火，未及脉象。其病机在命门真阳一衰，则虚劳无子、阳道痿弱、老人失溺、腰脚挛痹、脾虚腹冷不能食；药性辛热正补命门火之不足，使真阳足、阴翳消，诸证自除。", []], "27762": ["其他", "此段述夏枯草配伍主治瘰疬、乳痈乳岩、痈疽肿毒及肝虚目睛疼、冷泪羞明，未言脉象。所主在肝虚血少、风热痰毒结聚，故以夏枯草配香附治肝虚目痛，配连翘、贝母等消瘰疬痈毒，皆从清肝散结立法。", []], "27763": ["病机", "此段论桂辛甘大热，主温中、利肝肺气、心腹寒热冷疾、霍乱转筋、头痛腰痛，能通血脉、宣导百药。元素谓补下焦不足、治沉寒痼冷，好古谓补命门不足、益火消阴，皆言其病机为阳气不足、阴寒内盛，故以辛热通阳散寒。", []], "27764": ["病机", "此段疏桂气味纯阳，桂枝气薄上行发表，肉桂气厚下行补肾。辛甘发散为阳，热亦属阳，故能散风寒、实表、入血行血、润肾燥；其主利肝肺气、头痛出汗止烦，皆由气味纯阳、自内充外、辛散热行甘和之功。", []], "27765": ["兼症", "原文以“脉不洪数”界定疮疡溃后热毒已尽之候，洪数为热毒炽盛之脉，脉不洪数则热毒已退，故宜参、耆、五味、当归、麦冬内塞长肉；若脉洪数则热毒未尽，不可温补。此段诸方兼症虽多，要旨在辨脉以定疮疡虚实。", ["洪", "数"]], "27766": ["病机", "桂枝汤治伤寒表虚，脉浮缓为表虚中风之征，浮紧为表实伤寒之脉；辛甘发散为阳，故桂枝能发汗解肌。然无汗不得用桂枝，汗家不得重发汗，汗多用桂枝甘草汤闭汗，一药二用，皆随脉之浮紧浮缓与汗之有无而施。", ["浮", "紧", "缓"]], "27767": ["病机", "此段论松脂苦甘温燥，燥则除湿散风寒，苦燥杀虫，甘除热。痹由风寒湿合病，湿气害人皮肉筋脉而成死肌；湿热散则血不瘀败、荣气通调，故主疽恶疮、头疡白秃、疥瘙风气，湿去则身轻，未及脉象。", []], "27768": ["主病", "原文以枸杞子配地黄、五味子、麦门冬、地骨皮、青蒿、鳖甲、牛膝，主治虚劳内热或发寒热，脉数正是阴虚内热、虚火内扰之象。虚劳日久，阴液亏耗，阳无所附而浮越，故脉数；热扰营卫则寒热交作。方中滋阴退热，使阴复热退则数脉自平，兼治肺热咳嗽之因阴虚者，亦从脉数所主阴虚内热推出。", ["数"]], "27769": ["病机", "原文未出脉名，以黄柏“禀至阴之气而得清寒之性”立论，谓阴不足则热结肠胃，黄疸、肠澼、痔漏、泄痢、女子漏下赤白、阴伤蚀疮、肤热目赤口疮皆湿热乘阴虚流客下部而成。其病机核心为阴虚生内热、湿热干犯肠胃，故用至阴之气补至阴之不足，阴回则热解湿燥而诸证自除，非凭脉象而言。", []], "27770": ["病机", "原文未出脉名，论干漆辛气温、气味俱厚，通行肠胃、入肝行血。谓风寒湿邪留而不去则肠胃郁而生虫，久则五脏六腑受病，或瘫痪或拘挛；又损伤从血论，瘀血清则绝伤自和。其主痞结腰痛、女子疝瘕，指下焦血分受寒血凝所致，全以气味厚薄推病机，未及脉象。", []], "27771": ["病机", "原文出“脉缓纵”，论五加皮辛温苦燥，入足少阴、足厥阴，主风寒湿邪伤于肝肾二经。经云“伤于湿者，下先受之”，肝肾居下主筋骨，湿性濡滞，故脉缓纵；湿邪流注下焦，则疝气腹痛、躄不能行、阴蚀疽疮、阴痿囊湿、小便余沥、女子阴痒、脊痛脚疼痹弱。辛散风、温除寒、苦燥湿，二脏得气则缓纵之脉可复。", ["缓", "纵"]], "27772": ["病机", "原文出“脉之长”，论牡荆实苦温，可升可降，入足阳明、厥阴。足阳明为十二经脉之长，厥阴为风木之位，外邪伤二经则寒热留连筋骨、胃气壅滞。脉长主邪气壅盛、胃气不利，苦温通行散邪，胃气利则寒热除，邪散气下则咳逆自止，故脉长所主在阳明厥阴受邪、胃气壅滞之病机。", ["长"]], "27773": ["病机", "原文未出脉名，论蔓荆实气清味薄、浮而升，入足太阳、足厥阴兼足阳明。谓六淫之邪风伤筋、寒伤骨而为寒热，甚则湿痹拘挛；足太阳夹脊循项络脑，目为厥阴开窍，邪伤二经则头痛脑鸣目泪出。药味辛气温，散风寒湿之邪则诸证悉除，邪去九窍自通，痹散则光泽脂致，坚齿则因齿床属阳明。", []], "27774": ["病机", "原文未出脉名，论辛夷气清而香、味薄而散、浮而升，入手太阴、足阳明。谓风邪中人必自皮毛肌肉以达五脏而变寒热；鼻为肺窍，头为诸阳之首，风客阳分则头痛面䵟、鼻塞涕出、面肿引齿痛；眩冒及身兀兀如在车船之上，乃风主摇动之象。辛温解肌散表、芳香上窜头目，逐阳分风邪则诸证自愈。", []], "27775": ["主病", "原文出“崩中脉绝”，论甘寒无毒之药主伤中、五劳六极、羸瘦、崩中脉绝，补虚益气，去肺中水气，唾血热渴，水肿腹满胪胀，利水道，去寸白，缝金疮。崩中而脉绝，乃失血过多、气血骤虚、脉道不续之候，故以补虚益气为治；水肿腹满胪胀则水气太过，利水道以去之，皆从脉绝所主虚损立论。", ["绝"]], "27776": ["病机", "原文以“脉绝者，气血两虚之至，故脉不来也”释脉不来，又言“之数者，皆由阴不足则阳有余，阳有余则火盛而内热”。脉不来属气血两虚之极，脉数则由阴虚阳亢、火盛内热所致。二者并见，说明虚火消烁元气，故见伤中、五劳、六极、羸瘦、崩中等症，皆由阴亏火旺、气血耗损而来。", []], "27777": ["病机", "本段未言具体脉象，而论中风病机为“阴虚火旺，煎熬津液，结而为痰，壅塞气道，不得升降，热极生风”，以致猝然僵仆、偏痹不仁。竹沥甘寒滑利，走窍逐痰，正对阴虚痰热之机。文中强调中风“未有不因阴虚痰热所致”，非外来风邪，故以益阴除热、搜剔痰结为治，脉象虽缺，病机属阴虚痰热生风。", []], "27778": ["主病", "原文言厥阴证“手足厥冷，脉细欲绝，其人内有久寒者”，用当归四逆加吴茱萸汤。脉细欲绝，为血虚寒凝、阳气不能外达四末之象，与手足厥冷相应。内有久寒，寒邪凝滞经脉，气血运行不畅，故脉道细而欲绝。治以温经散寒、养血通脉，正合此病机。", ["细"]], "27779": ["误治", "本段论龙脑（冰片）性属火而轻浮飞越，虽似寒而通利，实能引风入骨。原文指出“若风在血脉肌肉，辄用脑、麝，反引风入骨髓，如油入面，莫之能出”，又言中风因气血虚者忌之，慢脾风切不可服。此属药性误用致害之论，强调辨证不当、引邪深入之误治后果。", []], "27780": ["主病", "原文引《金匮》厚朴三物汤“治腹胀脉数”，脉数主热，腹胀由实热积滞、气机壅塞所致。厚朴苦温行气除满，配枳实、大黄通腑泄热，使积滞去而胀消。脉数在此提示腹满属实证、热证，与虚寒腹胀之脉迟弱不同，故以行气泄热为治。", ["数"]], "27781": ["病机", "本段未出脉象，而论海桐皮入足太阴、阳明经，主霍乱中恶、疳䘌久痢、疥癣等。原文谓“二经虚则外邪易入，为霍乱中恶，辛以散之；湿热内侵为疳䘌，久痢，苦以泄之”，说明脾胃虚弱则外邪易侵，湿热内蕴则生虫成癣。其病机为脾胃不足、外邪与湿热内侵，故以辛苦之剂散邪泄热。", []], "27782": ["病机", "本段未言脉象，论合欢味甘气平，入手少阴、足太阴经。原文谓“脾虚则五脏不安，心气躁急则遇事拂郁多忧”，甘主益脾，脾实则五脏自安；甘可以缓，心气舒缓则神明畅达而欢乐无忧。其病机为心脾两虚、情志拂郁，故以补心脾、生血脉、缓急安神为治，主轻身明目、消痈疽、缓筋骨。", []], "27783": ["主病", "本段未出脉象，仅列药性主治：味苦，平、微寒，无毒，主青盲、浮翳赤涩多眵泪，消目中赤脉，小儿麸豆及疳气攻眼。其病机为肝经风热或湿热上攻于目，故见目赤涩、生翳、多泪；小儿疳气攻眼亦属积热上蒸。药以苦寒清热、平肝明目，针对目疾实热之证。", []], "27784": ["病机", "原文论密蒙花为厥阴肝家正药，所主青盲、浮翳、赤肿眵泪赤脉及小儿豆疮余毒、疳气攻眼，皆归因于肝虚有热、肝血不足。以甘补血、寒除热，使肝血足而诸证愈，故本条重在阐发目病由肝血虚与肝热所致的病机，非论脉。", []], "27785": ["主病", "原文述巴豆辛温有大毒，主伤寒温疟寒热，破症瘕结聚坚积、留饮痰癖、大腹水胀，荡涤五脏六腑、开通闭塞、利水谷道，疗女子月闭烂胎等。所主皆实邪留滞、闭塞不通之病，体现其峻下攻逐、开通荡涤的主病功用。", []], "27786": ["病机", "原文谓巴豆入手足阳明，所主症瘕结聚坚积、留饮痰癖、大腹水肿、鬼毒蛊疰、女人月闭，皆肠胃所治之位中有实邪留滞所致。肠胃有病则五脏六腑闭塞不通，药禀火性急速兼辛温走散，入肠胃荡涤有形积滞，则闭塞开、水谷道利、月事通，阐明实邪滞肠胃之病机。", []], "27787": ["主病", "原文述蜀椒辛温大热有毒，主邪气咳逆、温中、逐骨节皮肤死肌、寒湿痹痛、下气，除六腑寒冷、伤寒温疟、心腹留饮宿食、肠澼下痢、泄精、女子字乳余疾，散风邪、瘕结水肿、黄疸、鬼疰蛊毒。所主广泛，总属辛温散寒、温中通血脉以治寒湿诸病。", []], "27788": ["病机", "原文谓蜀椒入手足太阴兼厥阴，所主邪气咳逆、皮肤死肌、寒湿痹痛、心腹留饮宿食、肠澼下痢、黄疸水肿，皆脾肺二经受病。肺虚则外邪客为咳逆，脾虚不能运化水谷为留饮宿食下痢水肿，二经受风寒湿则为痛痹死肌。辛温发汗开腠理、暖肠胃散结滞，故能除六腑寒冷。", []], "27789": ["病机", "原文谓皂荚禀木气兼火金之性，入厥阴、太阴、阳明。主风痹死肌、头风泪出，皆厥阴风木为病；得金气胜木、辛散利窍，则风邪散、关窍利、神明通。又厥阴客寒为囊结，辛温散寒则囊结解；入肺散邪则咳嗽止；咸软坚、辛开窍横走，故主腹胀满、消谷及妇人胞不落。", []], "27790": ["妇人", "原文引经论女子二七天癸至、任脉通、太冲脉盛、月事以时下，以月之盈亏、潮之朝汐喻月事一月一行。又述女劳复因热病新瘥后交感，余热未除、阴精复损而发热烦躁、少腹阴囊牵引痛，月水为阴中有阳之物能补阴除热，故主之；兼及金疮虎狼伤及童女首经回阳之说，属妇人科论。", []], "27791": ["其他", "原文论鹿乃纯阳之物，治劳伤羸瘦、益肾添精、暖腰膝、养血脉、强筋骨，为助阳道圣药；然肾虚有火者不宜，以其偏于补阳；上焦痰热及胃家有火者不宜，以其性热复腻滞难化；凡吐血下血系阴虚火炽者概不得服。本条实为辨鹿角类药之宜忌，属用药法度而非脉诊。", []], "27792": ["其他", "此段为药物性味功用描述，未涉脉象。原文'主润五脏，利大小便，益十二经脉'，以甘寒润养为功，所益在十二经脉之濡润，非据脉以断病。故不能以脉象要素归纳，亦不属主病、病机之脉诊条文，仅记药效而已。", []], "27793": ["其他", "此段疏解牛乳药性，'味甘，其气微寒，无毒'，能'养血脉，滋润五脏'，故主补虚羸止渴。全段论药之甘寒润养，非论脉。'养血脉'指药效所及，非脉象所见，故脉象要素为空，主旨归其他。", []], "27794": ["治法", "此段论酥炙之用法与功效，'取其润燥兼能益精髓，补血脉'，又引《外台》以好酥炼醍醐治肺病咳嗽脓血不止。全段言制药、服药之法及疗效，属治法范畴，未及脉象，故脉象要素为空。", []], "27795": ["主病", "原文'主伤中，脉绝，阴不起'，脉绝指血脉虚绝之候，非具体脉形，然为本段所主病证之一。药味咸甘平，主伤中而脉绝者，以甘能补血脉、咸温走下焦助真阳，故阴不起、强志益气、长肌肉肥健、生子及小儿惊痫皆可主。脉绝在此示气血虚衰之病机。", ["绝"]], "27796": ["病机", "疏文承《本经》'主伤中，脉绝，阴不起'而释其理：'非甘温则不主伤中脉绝，以甘能补血脉，温能通经络故耳。'脉绝由阳衰血脉不通所致，咸温补助真阳则阴自起、精自暖，故能有子、益气、强志、长肌肉。全段以药性推病机，脉绝为气血阳衰之征。", ["绝"]], "27797": ["病机", "原文'妇人冲任脉虚则为漏下恶血'，明确指出脉虚为冲任不足之象，虚则血失统摄而漏下，或瘀血在腹、石淋；男子肝肾不足则寒热惊痫、虚劳洒洒如疟、羸瘦腰脊痛、泄精溺血。鹿茸甘温补下元真阳，走命门、心包络及肾肝阴分，故诸虚证皆主之。脉虚为全段病机之眼目。", ["虚"]], "27798": ["病机", "此段辨鹿、麋阴阳属性及茸角功用，'麋茸补阴，鹿茸补阳'，角初生软嫩者禀壮健之性，峻补肾家真阳；熬成白胶则甘缓通周身血脉；生角咸温，散热行血消肿。'肝肾虚则为腰脊痛'，咸温入肾补肝故主之。全段论药性归经与所主病机，未出脉象，故脉象要素为空。", []], "27799": ["主病", "原文'主丈夫、女子伤中绝脉，筋急痛，咳逆'，绝脉指血脉虚绝之候，与伤中并见，示中焦气血虚衰、血脉不续。药味甘温，以酒和服，取其温通补益，故能主伤中绝脉及筋急痛、咳逆。绝脉在此为所主病证之脉候，非平脉描述。", ["绝"]], "27800": ["病机", "原文以鹿髓“性能补血而润燥”立论，指出其“主一切血脉不和”，并列举“伤中脉绝，筋急痛，及咳逆”。所谓“脉不和”指精血亏虚、血脉失于充润所致之脉道不利，非独立脉象。髓为精血之纯，内充以实骨，故补髓即所以和血脉、缓筋急，咳逆亦由血燥气逆而设。", []], "27801": ["病机", "此段未言具体脉象，以鹿肉“性能益脾胃，通血脉”为纲，主“补中，强五脏，益气力”，并疗中风口僻。其病机在于脾胃气虚、血脉不通，血脉通则口僻自正。所论“通血脉”是药性功用，非据脉断证，故脉象要素为空，归入病机类。", []], "27802": ["病机", "原文论狗阴茎“性专补右肾命门真火”，能“令阳道丰隆，精暖盈溢，使人生子”；女子带下十二疾“皆冲任虚寒所致”，以咸温入下焦“补暖二脉”。全段以命门火衰、冲任虚寒为病机核心，未及具体脉象，故脉象要素为空，主旨属病机。", []], "27803": ["病机", "犬肉气温味咸酸，为“脾胃家肉”，原文反复强调“温暖脾胃之功”，脾胃得补则“气血生长，腰肾受庇，阳道壮健而下焦暖”。所主安五脏、补绝伤、益阳事、填骨髓，皆由脾胃虚寒、气血不足推衍而来，非凭脉立论，故脉象要素为空，归病机。", []], "27804": ["误治", "此段辨伤寒阴证发躁与阳证之异：面赤、手温、烦呕、喜凉物似热，然“惟脉沉细，足冷”，渴而饮水不多且复吐出。脉沉细主阴寒在内，逼浮阳上聚胸咽，属真寒假热。原文特诫“不宜误用犀角凉剂”，故主旨落在误治之戒，脉沉细正是辨伪存真的眼目。", ["沉", "细"]], "27805": ["病机", "原文直言“乳属阳明，阳明脉弱则乳汁不通”，以脉弱点明阳明气血不足、乳汁化源匮乏，故用甘咸之品益阳明经气血以下乳。脉弱在此非泛泛虚象，而是乳汁不通的直接病机依据；段末兼及伤挞败疮血热作痛，取凉血止痛，仍紧扣气血与血脉立论。", ["弱"]], "27806": ["治法", "此段主述猪胆汁导法及白通汤加猪胆汁证治。少阴下利不止、厥逆无脉、干呕烦，属阴寒内盛、虚阳上越，加胆汁“使其气相从，无拒格之患”，即寒因热用、热因寒用。原文“无脉”是证候描述而非脉象要素，全段重心在治法，故归治法类。", []], "27807": ["病机", "猪肚属土、味甘气微温，为“补脾胃之要品”。原文以“脾胃得补则中气益、利自止”立论，进而主补虚损、骨蒸劳热、血脉不行，谓“补益脾胃则精血自生，虚劳自愈”。其病机为脾胃虚弱、中气不足致精血不生、血脉不行，未涉具体脉象，故脉象要素为空。", []], "27808": ["病机", "原文论麋角补左肾真阴不足，治虚损劳乏、筋骨腰膝酸痛、血液衰少。其要旨在“气血先虚，经络因之壅滞，血脉不通”，说明痹证外邪易入由气血先虚、血脉不通所致，麋角入血益阴、荣养经络，故主止血益气除痹，属阴长阳消之补阴病机。", []], "27809": ["妇人", "原文以乌骨鸡得水木精气、性属阴、走肝肾血分立论，补血益阴则虚劳羸弱可除，阴回热去则津液生而渴止，阴平阳秘则邪不得入。益阴使冲、任、带三脉俱旺，故除崩中带下及一切虚损，古方乌骨鸡丸治妇人百病，正取其补虚益阴入血分之功。", []], "27810": ["病机", "原文主乳难，取三年老雄鸡阳气充溢。论“风中血脉则口角僻㖞”，鸡冠血咸而走血、透肌肉，故涂颊治中风口㖞不正；丹雄鸡为阳禽，冠血为诸阳所聚，故治中恶客忤邪气。鸡属巽属风，顶血至清至高，故发痘最佳，皆取阳气走血透肌之义。", []], "27811": ["病机", "原文据雀屎所主推其辛苦温、性善消散，故外用疗目痛、决痈疖，内服治带下、溺不利、疝瘕。苏恭用男子乳研点目中胬肉赤脉贯瞳子即消，是取辛散拔出火毒之义。全段以辛温消散解释诸证病机，非论脉象。", []], "27812": ["治法", "原文论蜜润五脏、益血脉、调脾胃、通三焦，配芦根汁、梨汁、人乳、童便治噎膈大便燥结，有痰加竹沥。仲景蜜煎导治阳明病自汗、小便反利、大便硬者，纳谷道中少顷即通，是润下外导之法；又载产后口渴、痘疹作痒用蜜调服，皆属润燥缓痛之治。", []], "27813": ["病机", "原文辨蜡与蜜性异：蜜性缓质柔，主润脏腑经络；蜡性涩质坚，故疗久痢、泄澼后重、下脓血。甘能益血补中，温能通行经脉，故主续绝伤及金疮；中得补则气自益，故久服不饥轻身耐老。全段以涩坚甘温解释蜡之止痢续伤病机，并驳《别录》独利小儿之说。", []], "27814": ["病机", "原文谓鱓鱼得土中阳气以生，味甘气大温，甘温俱足故能补中益血；甘温能通经脉、疗风邪，故主沈唇及今人治口眼㖞斜。全段以甘温补中益血、通行经脉解释鱓鱼主治风邪口㖞之病机，未涉脉象。", []], "27815": ["病机", "原文谓蜂性有毒、得火气之甚，蜂房味苦气平，当作辛咸。辛散苦泄、咸可软坚，故主惊痫瘛疭、寒热邪气、癫疾、鬼精蛊毒、肠痔；疗蜂毒毒肿取以毒攻毒。烧灰酒服治恶疽附骨痈、历节肿、疔肿恶脉，煎水漱齿止风虫痛，皆取攻毒散邪杀虫之功。", []], "27816": ["病机", "原文未出脉名，以药性推病机：乌贼骨咸温入厥阴、少阴，针对肝血虚而漏下赤白、经闭、寒热症瘕，及肾虚湿客之阴蚀肿痛、阴中寒肿。所谓'虚则漏下''虚而有湿''虚而寒客'，皆言肝肾精血亏虚兼寒湿为患，故以咸温通血脉、祛寒湿，使精血足而有子。", []], "27817": ["病机", "原文未出脉名，从药性论病机：僵蚕辛咸微温，入厥阴风木与肺经。小儿惊痫夜啼、女子崩中赤白，为'风热乘肝脏'；产后余痛为'风寒入血分'；阴疡为'风湿浸淫'。辛散风寒、温通血脉，故诸证除，非脉象所主，乃气味升降所治之病机。", []], "27818": ["病机", "原文以'筋脉得之皆燥急'与'筋脉舒缓'对举：阴血亏竭、阳气躁扰则腠理不密，贼风乘虚入经络，风主摇动，故㖞僻挛缩、筋急。咸寒益阴润燥软坚，则燥急转为舒缓、经络通达。此以燥急、舒缓言筋脉之态，非诊脉所得，实为风邪伤筋之病机。", ["急", "缓"]], "27819": ["主病", "原文未出脉名，专述虻虫主治：逐瘀血、破下血积、坚痞症瘕、寒热，通利血脉九窍，治女子月水不通、积聚及贼血在胸腹五脏、喉痹结塞。所主皆瘀血结滞、血脉不通之实证，故以苦微寒有毒之品破血逐瘀，属主病之文。", []], "27820": ["主病", "原文举大黄䗪虫丸治虚劳干血、肌肤甲错、两目黯黑，又引'太阳病，身黄，脉沉结，小腹硬，小便自利，其人如狂'。脉沉主里、结主血行不畅，合小腹硬、如狂，正是蓄血在里之征，故虻虫入方破瘀，属主病兼蓄血证候。", ["沉", "结"]], "27821": ["误治", "承'伤寒发黄，脉沉结，少腹硬'立辨：若小便不利则为无血证、非蓄血，不宜用虻虫；瘀血未审、脾胃薄弱肝血枯竭而非血结闭塞、孕妇症瘕、气血虚甚形质瘦损者皆忌。脉沉结虽似蓄血，然须合小便自利等症方真，否则误破致害，故列禁忌。", ["沉", "结"]], "27822": ["病机", "原文未出脉名，以䗪虫咸寒入厥阴血分论病机：'血若凝滞则经络不通，阴阳之用互乖，而寒热洗洗生焉'。故主心腹血积、症瘕血闭，咸寒软坚则血和荣卫通、寒热除、月事时至而有子，又治疟母。所论为瘀血凝滞致寒热之病机。", []], "27823": ["病机", "原文未出脉名，论蛤蚧咸平入肺肾：久肺劳传尸、咳嗽、淋沥皆'肺肾为病'，劳极则肺肾虚而生热，外邪易侵、内证兼发。蛤蚧属阴补水之上源，肺肾得养则劳热咳嗽除；肺朝百脉、通调水道，肺气清则淋沥自通。所主为肺肾虚热之病机。", []], "27824": ["主病", "原文以“筋脉拘急”述症，非论脉象。药性甘咸温有毒，主中风、湿痹不仁，其“筋脉拘急、口面㖞斜、半身不遂”皆风邪中络、筋脉失养之候；骨节疼痛、大风疥癞、暴风瘙痒则属风毒浸淫。全段重在标明治风通络、祛湿蠲痹所主诸病，非脉诊内容。", ["急"]], "27825": ["主病", "原文未及脉象，仅述药味甘温无毒，主心腹冷气、小儿五疳、辟疫、肠风、通利气脉、女子月闭。其病机为寒凝气滞、血行不畅，故以温药行气血、消疳积、通月闭；“通利气脉”一语点出气血壅滞之所在，与心腹冷气、月闭相呼应。", []], "27826": ["病机", "此段为药性疏解，非论脉。以“气味俱厚，阴中之阴，降也”说明寒号虫粪性专行血，入厥阴、少阴，故主女子血闭；味甘而温，故疗心腹冷气、通利气脉。又谓其能消化水谷而主五疳，行肠胃瘀滞而治肠风，并推及血气刺痛、产后儿枕块、痰挟血成窠囊等瘀血诸证。", []], "27827": ["病机", "原文未涉脉象，专论五灵脂“长于破血行血”之功。凡瘀血停滞作痛、产后血晕、恶血冲心、少腹儿枕痛、留血经闭、血滞经脉而气不得行、攻刺疼痛，皆属瘀阻气滞之病机，故在所必用；反之血虚腹痛、血虚经闭、去血过多发晕、心虚有火作痛而无瘀滞者，则皆当忌，从反面界定其破血之性。", []], "27828": ["病机", "此段论藕实药性，未及脉。以“得天地清芳之气，禀土中冲和之味”立论，味甘气平入太阴、阳明，兼入手少阴。土为万物之母，母气既和则血气生、神得所养，故主补中养神、益气力、除百疾；其止渴去热、安心止痢、治腰痛泄精，皆归为补益心脾之功，体现甘平培土生血之机。", []], "27829": ["病机", "原文论大枣甘温之性，未言脉。引“里不足者，以甘补之”“形不足者，温之以气”，说明甘温能补脾胃、生津液，则十二经脉自通、九窍利、四肢和；正气足则神安，故主心腹邪气及大惊；中得缓则烦闷除，故疗心下悬急少气；脾得补则气力强、肠胃清，故主身中不足及肠澼，并甘能解毒和百药。", []], "27830": ["病机", "此段疏乌梅，未涉脉象。梅得木气之全，味最酸，酸能敛浮热、吸气归元，故主下气、除热烦满、安心；下痢为大肠虚脱，好唾口干为虚火上炎、津液不足，酸能敛虚火、化津液、固肠脱。又肝主筋，酸入肝而养筋，肝得所养则骨正筋柔、机关通利，故主肢体痛、偏枯不仁；白梅味咸软坚，故去死肌恶肉。", []], "27831": ["病机", "原文引仲景抵挡汤证：“表证仍在，脉微而沉，反不结胸，其人如狂”，断为“热结在下焦”。脉微而沉，示邪不在表而结于下焦血分，热与血结故少腹硬满、小便自利；瘀热上扰心神则如狂。桃仁承气汤证小便利而大便黑，亦属蓄血，故用破血逐瘀之剂，下血乃愈。", ["微", "沉"]], "27832": ["病机", "原文以「脉数无力」立论，数主热、无力为虚，正合「今时之人，火病、热病、痰病，往往皆是」之论。梨味甘微酸气寒，入手太阴兼足阳明，能润肺消痰、降火除热，故脉数无力之虚火痰热，宜此甘寒润降之品，而非古人温热桂附所宜。", ["数", "虚"]], "27833": ["病机", "此段未出脉名，专论胡桃「禀火土之气」而「气多热而性润」，为益血脉、补命门之药。其病机在血不充则消瘦、肌肤不泽、须发易白，故益血则肥健润肌黑发；又入肾固精使水窍常通，甘热解毒散结以傅瘰疬，润肠除湿以去五痔，皆从药性推其主病。", []], "27834": ["病机", "本段辨胡桃之宜忌，未涉脉象。其要在「性本热，惟虚寒者宜之」，故虚寒痰喘、命门火衰、血脉不润者可用；若「肺家有痰热，命门火炽，阴虚吐衄」则皆不得施。多食动痰饮、动风脱眉、咯血之说，正说明热药助火生风之病机，非泛论也。", []], "27835": ["病机", "此段未言脉，论胡麻「味甘气平无毒」，禀冲气、得稼穑之甘，入足太阴兼厥阴、少阴。其病机在气味和平、不寒不热，故能益脾胃、补肝肾，主伤中虚羸、补五内、益气力、长肌肉、坚筋骨、填髓脑，及吐后虚热羸困；甘平益血润燥，故疗金疮瘀痛。", []], "27836": ["病机", "此段为麻子《本经》正文，未出脉象。其病机以味甘平无毒为据：甘能补中益气，故主中虚；滑利下行，故逐水、利小便；甘能益血，血脉复则积血破，故主乳妇产后余疾、长发。久服肥健不老，皆从甘平滑利、补中益血之性推出，非另有脉证可凭。", []], "27837": ["病机", "此段疏麻仁，未言脉。其要在「性最滑利」，甘能补中益血，血脉复则积血破、产后余疾除。又引经「阴弱者，汗自出」，谓风并于卫则卫实荣虚，麻仁益血补阴使荣卫调和而汗止；滑利下行引水气从小便出，故逐水；甘缓脾润燥，故仲景脾约丸用之。", []], "27838": ["病机", "此段述麻仁多食之害，未涉脉象。其病机在「滑利下行，走而不守」：滑利太过则损血脉、滑精气，以致痿阳事；妇人食之则发带疾，亦因滑泄下走、耗伤精血之故。此与前段甘平益血之功相参，说明同一药性过用则偏，不可执补而忘其滑。", []], "27839": ["病机", "此段论生大豆，未出脉名。其病机以「禀土气以生，色黑象水」为据：甘平兼凉，为肾家之谷，故能活血解毒、祛风散热，主涂痈肿止痛、杀乌头毒、除胃中热痹、下瘀血、散五脏结积内寒；色黑属水、同气相求，故逐水肿腹胀。炒黑投酒治风痹瘫缓、产后诸风，亦取活血祛风之义。", []], "27840": ["主病", "原文述狐惑病“脉数，无热微烦，默默但欲卧，汗出”，脉数而身无大热，是热毒内蕴、营血受灼之象。热毒腐蚀咽喉、目眦，故目赤如鸠眼、目四眦黄黑；脉数主热，热盛肉腐则脓成。赤小豆当归散渗湿清热、活血排脓，正对脉数所主之热毒痈脓病机。", ["数"]], "27841": ["病机", "原文未出脉名，专论酒性“热谷之液，其气悍”“性热独冠群物”，其功在“通血脉，厚肠胃，润皮肤”“横行经络，走散皮肤，开发宣通”。所主病机为酒性悍热、开发宣通，能辟邪恶毒气，亦能致体弊神昏，全在取其走散宣通之性以助药势。", []], "27842": ["平脉", "原文未出脉名，论粳米“感天地冲和之气”“禀土德之正，味甘而淡，性平而无毒”，专主脾胃，使血脉精髓充溢、筋骨肌肉皮肤强健。所主为平人谷气充养、脾胃冲和之常，故曰“安谷则昌”，非病脉之候，乃平脉养生之基。", []], "27843": ["病机", "原文未出脉名，论大麦“性更平凉滑腻”“益气补中，实五脏，厚肠胃”“补虚劣，壮血脉，化谷食，止泄泻”。所主病机为脾胃虚弱、血脉不充而致虚劣泄泻，大麦平凉滑腻，能补中壮脉、化谷止泄，与粳米同功，非关脉象。", []], "27844": ["主病", "原文云伤寒初觉“头痛身热，脉洪，一二日，以葱豉汤治之”。脉洪为邪热怫郁在表、气血涌盛之象，故见头痛身热；葱豉汤宣透取汗，使邪从表解。后列栀子豉汤治汗下后虚烦、枳实栀子豉汤治劳复，皆承脉洪所主之热郁病机而分证论治。", ["洪"]], "27845": ["主病", "原文引仲景“少阴病，脉微细，但欲寐，咽中伤生疮，不能言语，声不出者，苦酒汤主之”。脉微细为少阴阳虚、气血不足之候，故但欲寐；虚火上灼咽部则生疮声不出。苦酒汤敛虚火、涤痰开结，正合微细脉所主之少阴虚实夹杂病机。", ["微", "细"]], "27846": ["病机", "原文未出脉名，论瓜蒂“味苦，气寒有小毒”“气薄味厚，浮而升”，主大水、身面四肢浮肿、黄疸，皆因“脾胃虚，水气湿热乘虚而客之”。苦以涌泄，使水湿之气外散；又“在高者，因而越之”，吐胸中邪则咳逆上气自止。所主为水湿湿热壅于上焦之病机。", []], "27847": ["主病", "原文列瓜蒂散诸证：胸中痞硬、气上冲咽，“寸脉微浮”，为寒痰壅塞胸中、阳气被遏；湿家头中寒湿“其脉大”，为湿邪在表；太阳中暍“脉微弱”，为暑湿伤中。诸脉不一，皆示邪壅上焦、当吐之病机，故以瓜蒂散因势涌越。", ["微", "浮", "大", "滑"]], "27848": ["治法", "本段为葱白治伤寒头痛、时疾发热、风湿身痛、胎动下血及阴毒腹痛厥逆诸方，末言'六脉欲绝'乃阴毒危候，用葱一束取辛温通阳以救脉绝，非以脉象立论，故脉象要素为空。主旨属治法，列葱白诸用及取汗、取吐、安胎、通阳诸法。", []], "27849": ["病机", "原文'右脉甚涩，关脉沉'，涩主血行不畅，沉主病在里，关候中焦，合而示胃脘瘀血内停。段中明言'瘀血在胃脘之口，气因郁而成痰，隘塞食道'，故食入屈曲下膈、硬涩微痛，脉涩沉正应瘀血痰气阻隔食道之噎膈病机。", ["涩", "沉"]], "27850": ["病机", "本段疏炉甘石药性，引经'荣气不从，逆于肉里，乃生痈肿'，说明甘温通畅血脉则肿痛散、血止肌生；又风热上壅致目赤烂浮翳，甘入脾益血、辛温散风热、性涩黏物，故能除翳点目。全段论药性所主病机，未涉脉象，故脉象要素为空。", []], "27851": ["病机", "原文'先候病机，五脏未虚，六腑未竭，血脉未乱，精神未散，服药必活'，以脏腑虚实、血脉乱否、精神散否判断病之深浅与预后。'脉未乱'指血脉未乱，为可治之机；病已成则半愈，病势已过则难全，全段主论察源候机、辨病势浅深之病机与预后。", []], "27852": ["病机", "本段强调听声察色诊脉以知未病，引仓公三死之戒，说明病皆关于邪，风寒暑湿饥饱劳逸皆可为邪，邪伤经络传入脏腑，随虚实冷热结以成病。全段论邪气伤人、随虚实冷热成病之病机，兼及信受服药之难，未出具体脉象。", []], "27853": ["治法", "本段论服药时间：病在胸膈以上先食后服药，病在心腹以下先服药后食，病在四肢血脉宜空腹而在旦，病在骨髓宜饱满而在夜。依病位上下内外定服药先后与时辰，属服药治法，原文未及脉象，故脉象要素为空。", []], "27854": ["其他", "本段论药之所主不可只执病名，中风有数十种、伤寒证候二十余条，当求类例、以本性为根宗、配合诸证以合药；又评仲景方为众方之祖，善诊脉、明气候、以意消息。全段属医方本草源流之论，非脉诊主病，故脉象要素为空。", []], "27855": ["其他", "本段以良将用兵喻良医用药，强调药性难穷，寒热温凉、辛甘缓急品类万殊，非一日七十毒者不能辨；又举《玉函》《金匮》诸方，言察脉用方难而辨药尤难，金石草木飞潜动植广众，风气南北不同，真伪难辨。全段论辨药之难，未涉脉象。", []], "27856": ["病机", "原文以五味养五体立论，谓\"脉䎡则和，故咸可以养脉\"，又言\"坚之而后可以䎡\"。脉贵柔和，坚劲则失和，故以咸软坚以养脉。此段非诊脉主病，乃借脉之软硬言药味调养之理，脉䎡为和、脉坚为病，属以脉论治则。", ["缓", "坚", "软"]], "27857": ["病机", "原文未出脉名，专论童男室女积想劳损：思虑伤心则血逆竭，神色先散、月水先闭，继则脾虚不食、金亏发嗽、水绝肢干、木不充多怒筋痿。五脏传遍则难治。此属情志内伤、气血先损之劳损病机，非据脉立论。", []], "27858": ["病机", "八要中列五虚五实：\"脉细\"与皮寒、气少、泄利、饮食不入并见为五虚，细乃气血不足之象；\"脉盛\"与皮热、腹胀、前后不通、闷瞀并见为五实，盛为邪气壅盛之征。以脉之细盛辨虚实两端，为八要辨证之纲。", ["细", "盛"]], "27859": ["其他", "原文未出脉名，论贵贱少长、新久虚实当分别论治。引歧伯\"形乐志苦，病生于脉\"，谓贵豪之家衣食足而心虑多，外实内虚，病生于脉，当各逐其人而治，不可一概依方。此属因人施治之论，脉为受病之所，非脉象主病。", []], "27860": ["治法", "原文未出脉名，辨\"医要在视脉，唯用一物攻之\"之说不可全信。谓病有大小新久虚实，初病小者可单攻，病久虚实夹杂须他药佐使，如硫黄性缓，须附子干姜桂佐使发之。此论视脉辨证后用药配伍之法，属治法范畴。", []], "27861": ["误治", "原文未出脉名，以用药如用刑为喻，斥庸医\"才到病家便以所见用药\"，孟浪乱投汤剂致困危杀人。强调高医须识病知脉、药证相当方能应手作效。此段主旨在于警戒不辨脉证而妄投之误治，非论某脉主某病。", []], "27862": ["妇人", "原文未出脉名，论妇人居帷幔之内，蒙臂既不能望色又不能殚切脉之巧，四诊有缺。引黄帝察形气色泽、观勇怯骨肉皮肤之法，指出\"脉病不相应\"时仅据脉供药难尽其术。此属妇人诊法之难，强调四诊合参。", []], "27863": ["妇人", "妇人病温十二日，脉六七至而涩，寸稍大尺稍小，寒热颊赤口干耳聋，经水适行，断为少阳热入血室。数而六七至为热，涩为血结，寸大尺小示热偏上焦血分。故主以小柴胡汤和解，继以抵当丸下瘀，脉渐匀而愈。", ["数", "涩", "大", "小"]], "27864": ["预后", "原文述妇人吐逆、二便不通、烦乱肢冷，继而“渐无脉”，此乃关格重证，气机闭塞、阴阳不相顺接，故脉气渐绝。予大承气汤通腑泄热后“脉渐生”，说明脉绝由实邪壅塞所致，腑气一通则脉复，属可治之候；若脉绝不复则危。原文强调“极难治，医者当审谨”，脉之生绝关乎预后判断。", []], "27865": ["死脉", "小儿虚滑、善食而瘦，时值五六月，脉洪大而“按之则绝”，六脉单洪。夏脉本应洪而兼胃气，今洪而无根、按之即绝，是“但洪无胃气”，胃气已败。原文引《经》“夏以胃气为本”，洪多胃气少曰病，但洪无胃气曰死，故断为死候，后果不逾旬而卒，脉象直接示胃气竭绝。", ["洪", "大"]], "27866": ["其他", "病疟月余，又经吐下，气弱而疾未愈。原文“观其病与脉”，断为夏伤暑、秋伤风，先予柴胡汤取安；后因饮食不节，寒热复作，吐逆不食、胁下牵急而痛、寒热无时，病名痰疟，以十枣汤下痰水而愈。此段以脉证合参辨病因，脉象未明言，重在凭脉审因、因证施治。", []], "27867": ["病机", "风痰头痛、颤掉吐逆，误温误下后厥，更见谵言、狂若见鬼、循衣摸床、手足冷而“脉伏”。脉伏非虚寒，乃胃中结热、阳气不能布于外、阴气不持于内，热深厥深，故外见肢冷而脉沉伏。原文断为“胃中有结热”，与大承气汤一剂而愈，说明伏脉在此主实热内结、阳郁不达。", ["伏"]], "27868": ["病机", "年五十四素羸多中寒，脉“左上二部、右下二部弦紧有力”。弦紧有力主寒凝筋脉、气血痹阻，故五七年来右手足筋急拘挛、言语稍迟。治以小续命汤加减，去人参、芍药、黄芩以避中寒，加薏苡仁治筋急，加当归养血，遂安。原文借此强调用方须逐证加减，弦紧之脉正示寒邪痹阻之病机。", ["弦", "紧"]], "27869": ["其他", "此段为药物条目，记槲脉“平”，烧作散主治痔疾，未涉及脉象诊法。原文“槲脉”系药名而非脉象，故脉象要素为空。主旨属本草主治内容，与病机、脉诊无关，归入其他类，不作脉理分析。", []], "27870": ["其他", "此段述朱砂性味甘微寒无毒，主身体五脏百病、养精神、安魂魄、益气明目、通血脉、止烦满消渴等，并载久服通神明、轻身神仙及产地采制、恶畏。全段为本草主治与炮制内容，未言脉象，故脉象要素为空，归入其他类。", []], "27871": ["其他", "此段为雷公炮制论，详述朱砂品类如妙硫砂、梅柏砂、白庭砂、神座砂等百等形色，及修事朱砂须焚香斋沐、香水浴过、碎捣研细等法。全段论药物鉴别与炮制，未涉及脉象诊法，故脉象要素为空，归入其他类。", []], "27872": ["其他", "本段为云母炮制与附方，未涉脉象。文中\"色黄黑者厚而顽\"\"光莹如冰色者为上\"辨药材优劣，\"水火勿令失度\"言炮制火候，皆非诊脉内容。所附治火疮、风疹方亦属外治，无脉证可参，故脉象要素为空，主旨归其他。", []], "27873": ["其他", "本段述玉泉（玉札）性味功用，\"主五脏百病，柔筋强骨，安魂魄\"\"利血脉\"\"疗妇人带下十二病\"皆药效记载，非脉诊。\"久服耐寒暑\"\"轻身长年\"为服食养生之辞，全段无脉象描述，故脉象要素空，主旨属其他。", []], "27874": ["其他", "本段记芒硝性味主治，\"主五脏积热，胃胀闭\"\"除邪气\"\"疗五脏十二经脉中百二十疾\"。原文\"脉中百二十疾\"之\"脉\"指经脉，非脉象，故不取为脉象要素。全段为药物功效叙述，无诊脉内容，主旨归其他。", []], "27875": ["其他", "本段载硝石炮制及附方，\"煅令通赤\"\"其硝石自然伏火\"言制法，\"治眼赤痛\"\"疗恶寒啬啬\"\"治五种淋疾\"为方治。全段无脉象描述，\"伏火\"之\"伏\"非脉名，故脉象要素空，主旨属其他。", []], "27876": ["其他", "本段述朴硝（芒硝类）性味功用，\"主五脏积聚，久热、胃闭\"\"破留血，腹中痰实结搏，通经脉\"\"破五淋，推陈致新\"皆药效，非脉象。全段无诊脉内容，脉象要素为空，主旨归其他。", []], "27877": ["其他", "本段述玄明粉（朴硝制伏）功效主治，\"治一切热毒风\"\"五脏秘涩\"\"三焦热淋\"\"妇人产后，小儿疳气\"等，为药物通治诸疾之记载。\"阴中有阳之药\"言药性，非脉象，全段无脉诊内容，故脉象要素空，主旨属其他。", []], "27878": ["其他", "本段述石胆产地、性状与鉴别，\"入吐风痰药用最快\"言药效，\"击之纵横解皆成叠纹\"\"粒细有廉棱\"辨真伪。原文\"浑浑无脉理\"之\"脉理\"指石之纹理，非脉象，故脉象要素空，主旨归其他。", []], "27879": ["其他", "本段述空青性味功用，\"主青盲，耳聋，明目，利九窍，通血脉，养精神\"\"破坚积\"皆药效记载，\"久服轻身，延年不老\"为服食之辞。全段无脉象描述，脉象要素为空，主旨属其他。", []], "27880": ["治法", "原文述风湿顽痹、筋骨挛缩、脚疼冷风掣、瘫缓、血脉断绝，取干沙曝热伏坐取汗，属外治发汗通痹法。虽未言脉，然所主病机为风寒湿邪深痹血脉，致气血不通、筋脉失养，故以热沙温通取汗，使邪从表解，血脉得通。", []], "27881": ["其他", "原文为海药按语，述黄硇砂产地、性状、主治风冷虚惫、肾冷、上气、腿膝虚羸、遗精、痔漏、老人风秘等，并载炮制、解毒法。未涉脉象，主在药性功用与修治，故归其他。", []], "27882": ["其他", "原文食疗诸方，治蠼螋尿疮、一切气及脚气、小儿脐风湿、肝风虚转筋入腹、胸心痰饮等。虽标题有“脉伤皮及诸大脉、大脉”字样，然正文未论脉理，主在方治，故脉取“大”而类别归其他。", ["大"]], "27883": ["其他", "原文图经述石膏产地、性状、与方解石鉴别，并及方解石疗体相似、疗热不减石膏等。全段为药物考订，未涉脉象病机，故脉空、类别其他。", []], "27884": ["其他", "原文衍义辨石膏与方解石，引《经》细理白泽者良、顺理细纹又白泽者为石膏，并及仲景白虎汤用石膏。标题脉象写法“脉洪大”当指白虎汤证脉，然正文未论脉理，主在药物辨析，故脉取洪大而类别其他。", ["洪", "大"]], "27885": ["其他", "原文陶隐居述金之产地、生金有毒、须炼熟可服，及仙经炼饵、医方所用皆炼熟金箔等。全段论金石药性及修治，未涉脉象病机，故脉空、类别其他。", []], "27886": ["其他", "原文述二气砂味甘性温无毒，主五脏百病、养神安魂魄、益气明目、通血脉、止烦满、杀精魅恶鬼气，久服通神明。并载水银、硫黄炼制法。未涉脉象，主在药性功效，故归其他。", []], "27887": ["其他", "原文述玄石味辛咸寒无毒，主周痹、风湿肢节中痛、不可持物、洗洗酸痟、除大热烦满耳聋，养肾脏、强骨气、益精、通关节、消痈肿等。引蜀本注释周痹为随血脉上下不能左右去。未涉脉象，主在药性主治，故归其他。", []], "27888": ["其他", "此段为矿物药石胆的产地、别名与辨伪记载，'夹两石间如石脉'仅以脉喻石之纹理，非论人体脉象。文中'酒渍服之，疗癖'属药效记述，与脉诊病机无关，故脉象要素为空，主旨归入其他。", []], "27889": ["其他", "此段述方石之性味主治，'通血脉''除胁肋肺间邪气'为药物功用，非脉象描述。'理如马齿'指石之纹理，非脉。全段无脉诊内容，故脉象要素为空，主旨属其他。", []], "27890": ["病机", "阴证伤寒见'六脉沉细而疾'，沉主里、细主虚、疾主寒盛格阳。原文伴指甲面色青黑、心下胀满结硬、燥渴、虚汗不止、时狂言、四肢逆冷、咽喉不利、腹疼，皆阴寒内盛、虚阳外越之候，故脉沉细而疾主阴证伤寒、寒盛阳衰之病机。", ["沉", "细", "疾"]], "27891": ["其他", "此段言掘土见𫅗羊不可触，触之令人面黄、上气身肿，'多断地脉'指地中之脉络，非人体脉象。全段为禁忌与地气致病之说，无脉诊要素，故脉象为空，主旨归其他。", []], "27892": ["兼症", "此段集录丹方诸治，其中治伤寒时气温病'头痛壮热，脉盛'，盛脉主邪气亢盛、正邪交争，与壮热头痛相应，属温热病邪盛之候。余方治逆产、客忤、蝎螫、吐逆、风痫，皆非脉诊，故仅取'盛'脉，主旨归兼症。", ["盛"]], "27893": ["治法", "此段述醋和药袋封腋下、先刺腋下脉去血以攻腋臭，及熬热投酒服主贼风反折。'刺腋下脉去血'为刺络治法，非脉象描述，全段主治疗之法，故脉象要素为空，主旨归治法。", []], "27894": ["其他", "此段述代赭性味主治，'除五脏血脉中热，血痹血瘀'为药物功用，'赤红青色如鸡冠有泽'指石色，非脉。全段无脉诊内容，故脉象为空，主旨属其他。", []], "27895": ["其他", "此段辨菊花水之说，'泉脉如此'指泉水之源脉，非人体脉象。全段论水味与菊无关，属本草考辨，无脉诊要素，故脉象为空，主旨归其他。", []], "27896": ["主病", "原文为药物主治，未及脉象。所述“主胸中留热，结气，黄疸，通血脉，去蛊毒”，提示此药苦辛大寒，能清胸中留热、散结气、通利血脉，故所主为热结气滞、血脉不通及蛊毒之病，与脉象无直接关联。", []], "27897": ["其他", "原文“水中亦有赤脉，不可断之”及“水有脉及沸”，此处“脉”指水脉、地脉，非诊脉之脉。全段言水府龙宫禁忌及井水沸不可食，属民俗禁忌，与病机脉象无关，故脉象要素为空。", []], "27898": ["其他", "原文为菖蒲炮制及附方，虽标题含“脉犹动”，但正文未论脉象。所载“日月未足而欲产”“产后崩中下血不止”“好忘”等，属产科、血证、健忘之方治，非脉诊病机内容，故不取脉象。", []], "27899": ["主病", "原文为菊花主治，未言脉象。“主风头眩、肿痛，目欲脱，泪出，皮肤死肌，恶风，湿痹”及“利五脉，调四肢”，说明菊花能治风邪上攻头目、湿痹肌肤之病，其“利五脉”指通利血脉，非脉象描述。", []], "27900": ["主病", "原文辨菊之真伪及白菊主治，未涉脉象。“亦主风眩，能令头不白”及“苦薏，味苦破血。妇人腹内宿血”，言白菊治风眩，苦薏破血调中，皆属药物主治，与脉象病机无直接对应。", []], "27901": ["主病", "原文为人参主治，未及脉象。“主补五脏，安精神，定魂魄，止惊悸，除邪气”及“疗肠胃中冷，心腹鼓痛，胸胁逆满，霍乱吐逆”，示人参补虚安神、温中调气，所主为五脏虚损、惊悸、中冷气逆之病。", []], "27902": ["主病", "原文海药言人参“主腹腰，消食，补养脏腑，益气安神，止呕逆，平脉，下痰，止烦躁”，其中“平脉”指调和脉气、使脉复常，非描述具体脉象。全段主在补虚安神、调中下痰，所主为脏腑虚弱、呕逆痰躁之病。", ["平"]], "27903": ["主病", "原文为甘草主治，未言脉象。“主五脏六腑寒热邪气，坚筋骨，长肌肉，倍力”及“温中下气，烦闷短气，伤脏咳嗽，止渴，通经脉，利血气”，说明甘草能和中缓急、通利经脉血气，所主为寒热邪气、中虚短气、咳嗽及血脉不利之病。", []], "27904": ["其他", "本段为甘草产地、性状与炮制鉴别，非论脉。文中“看之坚实者，是抱罕草，最佳”“理多虚疏”等语，是以药材质地坚、虚疏判别优劣，与脉象无关；末言“安和草石而解诸毒”，亦属药性功用，不涉病机脉理。", []], "27905": ["其他", "本段虽标“脉结代者”，实为甘草炮制、服食及救急诸方，非脉诊专论。结代脉主心气不足、脉道不利，故炙甘草汤类以甘草通经脉、和气血；文中“救急瘦疾”“儿当快吐胸中恶汁”皆取甘草安中解毒之功，与结代所主气血虚衰相呼应。", ["结", "代"]], "27906": ["主病", "本段述干地黄性味主治，未及脉象。“主折跌绝筋，伤中，逐血痹，填骨髓”“通血脉，益气力”等，明其主血痹、伤中、虚损之病机；地黄甘苦寒，能逐血痹、补五脏内伤不足，故所主为血虚血滞、骨髓不足、劳伤诸候，非凭脉断病。", []], "27907": ["其他", "本段辨干地黄产地、制法及生干蒸干之别，非论脉。“蒸干即温补，生干则平宣”指出炮制不同则药性异，温补者宜虚寒，平宣者宜血热；文中“主耳暴聋、重听”亦属地黄补肾之功，与脉象无涉。", []], "27908": ["其他", "本段述菟丝子鉴别、炮制与附方，未言脉。“偏补人卫气，助人筋脉”明其补卫助筋之性；“治卒肿，满身面皆洪大”乃水气病证，取菟丝子酒渍以消肿，属方药主治，非据脉辨证。", []], "27909": ["主病", "本段述牛膝产地、形态及功用，未及脉象。“治阴痿，补肾填精，逐恶血流结，助十二经脉”“治腰膝软怯冷弱”点明牛膝主肾虚精亏、恶血留结、腰膝冷弱之病机；虚羸者加用，正合补虚逐瘀之旨，非凭脉断证。", []], "27910": ["主病", "本段述麦门冬性味主治，未言脉。“主心腹结气，伤中伤饱，胃络脉绝，羸瘦短气”明其主胃络虚绝、气结羸瘦之病机；又“止呕吐，愈痿蹶，强阴益精，消谷调中”，故所主为虚劳客热、口干燥渴、肺气不定诸候，皆从药性推病，非脉诊。", []], "27911": ["其他", "本段辨独活、羌活产地、形态与气味，非论脉。“此草得风不摇，无风自动”释独摇草之名；“气味了不与羌活相类，用之微寒而少效”辨药材真伪效验，全属本草鉴别，与脉象病机无涉。", []], "27912": ["其他", "本段为薏苡仁本草考证，非脉学内容。文中仅言药性论云'能治热风，筋脉挛急'，指薏苡仁可治热风所致筋脉拘挛，属药理主治，非以脉象论病机。'脉挛急'为症状描述，非脉象要素，故不取脉。", []], "27913": ["其他", "本段为薏苡仁及根的主治与修制，载其主消渴、煞蛔虫、堕胎、治牙齿风痛、咽喉痈肿、蛔虫攻心腹痛、肺疾唾脓血等，全属方药主治，未涉及脉象与脉理，故脉象要素为空。", []], "27914": ["其他", "本段为泽泻的本草考证与主治，言其主肾虚精自出、治五淋、利膀胱热、宣通水道，又治五劳七伤、头旋耳虚鸣、筋骨挛缩等，皆属药性功用，非脉诊内容，无脉象可录。", []], "27915": ["其他", "本段为赤箭（天麻）的形态与产地考证，述其茎赤如箭杆、根如人足、有十二子为卫、有风不动无风自摇等，属本草性状描述，未言脉象及脉理，故脉象要素为空。", []], "27916": ["其他", "本段为赤箭的图经考证，述其苗独茎如箭杆、叶生其端、根类天门冬、无心脉、有游子十二枚周环等，并引《抱朴子》合离草之说，全属本草形态产地，未涉脉诊，故无脉象。", []], "27917": ["其他", "本段为芎䓖的产地与性状考证，言历阳所出节大茎细状如马衔、秦州种者形块大重实多脂润、山中采者瘦细，并及齿根血出含之等多瘥，属本草内容，未论脉象。", []], "27918": ["其他", "本段为黄连的产地、形态与采根时节，并载古方以黄连为治痢之最、九盏汤主下痢不问冷热赤白谷滞休息久下等，属本草与方治，未涉及脉象脉理，故脉象要素为空。", []], "27919": ["病机", "本段载柳太后感风不能言，脉沉而口噤。风邪中于经络，气血内滞，故脉沉；机关不利，故口噤不能言。沉脉在此示邪郁于里、阳气不达，与风中脏腑、舌强不语之症相应，属病机判断，非单主一病。", ["沉"]], "27920": ["主病", "原文载王太后病风不能言，脉沉难对。沉为邪郁在里、阳气不达，风邪内闭则舌本不利而言语不能，脉气沉伏难以应指对答，故医告术穷。以黄耆、防风煮汤熏蒸，取气如雾薄之，宣通阳气、祛风开闭，是夕即语，正说明沉脉所主为风邪闭郁、阳气不宣之病机。", ["沉"]], "27921": ["其他", "此段为防风产地与药材性状的考订，非论脉。文中辨沙苑、彭城、兰陵、郁州、襄阳、义阳、上蔡诸地所出，强调“实而脂润，头节坚如蚯蚓头者为好”，并辨陶注无沙苑之误。全段主旨在于药材真伪优劣鉴别，与脉象病机无关，故脉象要素为空。", []], "27922": ["其他", "此段述蒲黄之药用，非论脉。原文云蒲黄“通经脉，止女子崩中不住，主痢血，止鼻衄，治尿血，利水道”，又分生使破血消肿、炒用补血止血，并及萼之涩肠止泻血。全段为药物功用与炮制之别，未涉脉象，故不列脉象要素，主旨归其他。", []], "27923": ["其他", "此段考辨续断之形态与品种，非论脉。原文述续断蔓延、叶细、茎如荏大、根黄白有汁，又辨桑上寄生、接骨树、诺藤、虎蓟诸说之异，唐本注指陶注为非。全段旨在药材名实考订，未及脉象与病机，故脉象要素为空，主旨属其他。", []], "27924": ["其他", "此段论漏芦产地、形态及俗名，非论脉。原文言其疗诸瘘疥、久服益人，市人取苗用，根名鹿骊，苦酒摩疗疮疥；唐本注辨荚蒿、木藜芦有毒非漏芦。全段为药物名实与功用考订，未涉脉象，故脉象要素为空，主旨归其他。", []], "27925": ["其他", "此段为漏芦的图经考订，非论脉。原文列京东、秦、海诸州所生，述单州、沂州、秦州、海州花叶形态之异，叹“一物而殊类若此，医家何所适从”，终以单州出者为胜，并载采茎苗时日。全段属药材鉴别，未及脉象病机，故脉象要素为空。", []], "27926": ["其他", "此段述丹参产地、性用，非论脉。原文云茎方有毛、紫花，俗呼逐马，酒渍饮疗风痹；又引药性论治脚弱疼痹、主中恶、定精，萧炳言酒浸治风软脚，可逐奔马。全段为药物性用与别名考，未涉脉象，故脉象要素为空，主旨归其他。", []], "27927": ["其他", "此段辨漏芦与苦芺、马蓟之异，非论脉。原文述处处有、极似苦芺、叶下附茎有皮起似箭羽、花紫色，道家服之；唐本注分两种，言疗疳蚀、杀虫俱验，并斥俗以马蓟、苦芺为漏芦之非。全段属药材名实考订，未及脉象，故脉象要素为空。", []], "27928": ["其他", "此段为《肘后方》论飞尸、遁尸、风尸、沉尸、尸注五种尸病，非脉学内容。原文描述各尸病游走皮肤、附骨入肉、淫跃四肢、缠骨结脏、举身沉重等症，皆由尸气、风寒、节气变动触发，未及脉象。所附忍冬茎叶煎服为治尸病之方，与脉诊无关，故脉象要素为空。", []], "27929": ["其他", "此段为陶隐居及诸家论王不留行药材形态、采收与主治，非脉学原文。文中言其能治风毒、通血脉，治发背游风、风疹、妇人血经不匀及难产，皆属本草主治，未涉及脉象。所论药性功用与脉诊无直接关联，故脉象要素为空。", []], "27930": ["其他", "此段为某药性味主治之本草条文，味辛温无毒，主肢节风痛、筋脉不遂、折伤瘀血、五缓挛痛，并记产地与采收。全段未言脉象，所主病机为风寒湿邪痹阻筋脉、瘀血阻滞，属本草主治范畴，非脉学论述，故脉象要素为空。", []], "27931": ["其他", "此段引唐本论某药治风、下气、止血、宣诸络脉、微汗，久服令眼暗，属本草功用记载。文中未及脉象，所论病机为风邪上扰、气逆血溢、络脉壅滞，皆从药效反推，非脉诊原文，故脉象要素为空。", []], "27932": ["其他", "此段为葛根食疗及诸方主治，涉及时气头痛壮热、小儿热渴、伤筋、酒醉、干呕、金疮中风痉等。原文脉象写法仅见大脉、脉洪，然正文并未以脉论病，大、洪当属热盛津伤、气分热炽之象，与壮热、热渴相应。全段主旨为方药主治，非脉学专论，故归其他。", ["大", "洪"]], "27933": ["其他", "此段论苦参主治与用法，包括治胫酸、恶虫、伤寒呕吐、天行结胸满痛壮热、小儿身热、狂邪发恶等，并载炮制与诸方。全段未言脉象，所主病机为湿热蕴结、邪热内扰、痰火发狂，皆从方药主治推知，非脉诊内容，故脉象要素为空。", []], "27934": ["其他", "此段论麻黄产地、炮制及功用，言其疗伤寒解肌第一，治身上毒风𤸷痹、皮肉不仁、壮热、温疟、温疫，根节能止汗。全段未及脉象，所论病机为风寒束表、卫闭营郁、毒风痹阻，属本草主治，非脉学原文，故脉象要素为空。", []], "27935": ["其他", "此段为某药性味功用条文，味辛甘平无毒，主去恶虫、除脾胃寒热、通利九窍血脉关节、疗脾疸、耳聋、散痈肿结、堕胎、去三虫等，并记别名与产地采收。全段未言脉象，所论病机为脾胃寒热、血脉关节壅滞、虫积，属本草主治，非脉诊内容，故脉象要素为空。", []], "27936": ["其他", "本段为木通（燕𧄏）的本草考证，述其藤茎形态、产地及别名，并引《药性论》主治五淋、利小便、开关格、水肿浮大等。全文未涉及脉象，故无从论脉。所主病机为湿热壅滞、水道不利，属本草主治范畴，非脉学内容。", []], "27937": ["其他", "本段为芍药性味功用条文，言其主邪气腹痛、除血痹、破坚积、利小便、通顺血脉、散恶血、去水气等。全段无脉象描述，属本草主治与配伍禁忌，不能据以论脉。其病机核心为血痹瘀滞、水气内停，与脉诊无直接关联。", []], "27938": ["其他", "本段为芍药图经考证，述其形态、花色、根色及别名由来，兼引崔豹《古今注》赠芍药相别之说，末及张仲景治伤寒用芍药。通篇为药物形态与名物考释，未出现脉象，故脉象要素为空，主旨归其他。", []], "27939": ["其他", "本段考蠡实（马蔺子）名物，引陶隐居、唐本注、《月令》郑注及《蜀经》《日华子》诸说，主治金疮血内流、痈肿、妇人血气烦闷、产后血运、崩中带下等。全段无脉象，属本草主治，病机为血瘀热壅、冲任不固，非脉学论述。", []], "27940": ["其他", "本段为秦艽图经及附方，述其根形、花色、采根时节，并载《正元广利方》秦艽牛乳煎疗黄、心烦热、口干、皮肉皆黄，及崔元亮治发背疑似者服之得快利。全段无脉象，属本草与方治，病机为湿热发黄、热毒壅结。", []], "27941": ["其他", "本段述贝母炮制之法，雷公云柳木灰炮黄、去心、糯米同炒，并辨丹龙精不可用，误服令人筋脉永不收，以黄精、小蓝汁解之；末引别说言贝母散心胸郁结之气。全段无脉象，属炮制与药效，病机为心胸气郁、痰结不散。", []], "27942": ["其他", "本段考狗脊名物，引陶隐居言与菝葜相似、根凹凸如羊角，唐本注辨陶所说乃有刺萆薢非狗脊，又引吴氏、桐君、歧伯经述其性味与茎叶形态。全段无脉象，属本草名物考证，不涉脉诊病机。", []], "27943": ["其他", "本段考白茅（菅）名物，引陶隐居言其根甜美可断谷、俗方疗淋及崩中，唐本注言菅花主衄血吐血灸疮，又引《药性论》白茅破血消渴、根治五淋，陈藏器述茅针、屋茅主治。全段无脉象，属本草主治，病机为血热妄行、淋证水停。", []], "27944": ["其他", "本段为白藓皮药材辨识与主治记载，无脉象描述。文中言其治「一切热毒风、恶风、风疮疥癣赤烂」及「热黄、酒黄、急黄」等，皆属热毒壅盛、风湿浸淫之病机，与脉象无关，故脉象要素为空，主旨归入其他。", []], "27945": ["其他", "本段述艾叶采制与主治，未涉脉象。原文载其治「金疮，崩中，霍乱，止胎漏」「止泻痢」「治百恶气」「产后泻血不止」，皆从血证、冷气、霍乱吐下立论，属温经止血、散寒除湿之治，非脉诊内容，故脉象要素为空。", []], "27946": ["其他", "本段为恶实（牛蒡）根、子之主治记载，无脉象。原文云根主「牙齿疼痛，劳疟，脚缓弱，风毒痈疽，咳嗽伤肺，肺壅，疝瘕，积血」，子主「风毒肿，诸瘘」，皆属风毒壅结、肺气不利、血积成瘕之病机，与脉象无涉，故脉象要素为空。", []], "27947": ["其他", "本段述王瓜（土瓜）之形态与主治，未言脉。原文称其「疗黄疸，破血」，又主「蛊毒，小儿闪癖，痞满并疟」，取根叶捣汁服「当吐下」，皆属破血消痞、吐下蛊毒之治法，非脉诊所论，故脉象要素为空，主旨归其他。", []], "27948": ["其他", "本段辨析泽兰与兰草之品种异同，纯属药材名实考证，无脉象描述。文中引陶隐居、唐本注诸说，辨「茎方，节紫色，叶似兰草而不香」者为泽兰，未涉及病机脉候，故脉象要素为空，主旨归入其他。", []], "27949": ["病机", "原文载「膈间支满，其人喘满，心下痞坚，面黧黑，其脉沉紧」，此沉紧之脉主水饮内停、寒饮结聚。沉为病在里，紧为寒为饮，饮邪搏结膈间，故心下痞坚、喘满；面黧黑乃水气上泛之征。脉证相合，故以木防己汤通阳化饮，属病机与主病并见之论。", ["沉", "紧"]], "27950": ["其他", "本段述赤箭（天麻）之形态、产地与主治，无脉象。原文载其治「冷气𤸷痹，摊缓不遂，语多恍惚，多惊失志」，又主「热毒痈肿」，皆属风痰阻络、肝风内动之病机，与脉诊无关，故脉象要素为空，主旨归入其他。", []], "27951": ["其他", "本段为牡丹皮之产地、品种与主治记载，未涉脉象。原文云其「治冷气，散诸痛，治女子经脉不通，血沥腰疼」，又「通月经，消扑损瘀血」，皆属血瘀气滞、经脉不通之病机，从药治立论而非脉诊，故脉象要素为空，主旨归其他。", []], "27952": ["主病", "原文未出脉名，专述药性主治。味甘涩凉，主妇人血脉不调、心腹痛、落胎、消恶血、通月经、治气胀、消扑损瘀血、产后腹痛血晕及宿血不下。其病机为血行不畅、瘀血内停，兼气机壅滞，故以通血脉、消瘀血为治，非凭脉断病。", []], "27953": ["其他", "此段仅存药名「百脉根」，无脉象、无病机、无主治文字，属古籍条目残文。既未言脉，亦未述证，无法据以分析病机，故脉象要素为空，主旨归入其他，不作臆测。", []], "27954": ["主病", "原文未出脉名，述药性温无毒，利九窍、通血脉、排脓治血、止鼻洪吐血、产后心腹痛、一切血病。其病机重在血脉瘀滞与血热妄行，故能通血脉而止吐衄；肥白人、产妇可作蔬菜食，示其性和平，非峻攻之品。", []], "27955": ["其他", "此段辨附子、乌头、乌喙、天雄、侧子、木鳖子之形色炮制，脉微二字仅存于脉象写法，原文实未以脉论病。所述重在细认药材、勿误用，属药物鉴别与炮制内容，非脉诊病机之论，故主旨归其他。", ["微"]], "27956": ["治法", "脉息沉细，主阳气不足、寒湿内凝，故见风、腰脚冷痹疼痛、头风头痛、耳鸣久聋、一切冷气、遍身疼痛。沉细为虚寒之象，治用川乌头辛热温通，或敷或洗或浸酒，以散寒湿、益元气、固精益髓，属因脉施治之例。", ["沉", "细"]], "27957": ["其他", "原文述天雄、附子、乌头三物同出建平，故称三建，并辨西建、东建气力优劣及蜀道绵州、龙州所出为佳。全段论药材产地与品质，未涉脉象与病机，脉象要素为空，主旨归入其他。", []], "27958": ["其他", "原文述大黄产地、采制、色味及药材性状，言其味甚苦涩、色至浓黑、至劲利，道家用以去痰疾，将军之号取其骏快。全段为药物鉴别与炮制贮藏之论，未出脉象，亦未以脉断病，故主旨归其他。", []], "27959": ["主病", "脉洪而实，主邪热内盛、实积壅滞。大黄苦寒，入血分而泻热通肠、逐瘀破积，正对洪实之脉所主之实热积滞、瘀血内停。原文虽以图经述大黄产地形态为主，然脉洪而实点出此药所主病机为实热壅盛，非虚寒可投。", ["洪", "实"]], "27960": ["其他", "此段为桔梗产地、形态与采制记载，末引《古今录验》治卒中蛊下血如鸡肝、昼夜出血石余、四脏皆损唯心未毁者，以桔梗捣屑酒服。原文虽标脉数，实为蛊毒出血、脏损危候的引文，脉数当示热毒迫血、脏气衰败之象，非本条论述中心，故归其他。", ["数"]], "27961": ["主病", "此段述旋覆花性味功用，主结气胁下满、惊悸、除水、去五脏间寒热、消胸上痰结、唾如胶漆、心胁痰水、膀胱留饮、风气湿痹。全段未出脉名，以药测证，乃痰饮结聚、水气不化、寒热错杂之病机，故归主病，脉象要素为空。", []], "27962": ["其他", "此段为旋覆花产地、形态及诸家考辨，兼引《药性论》主胁胁气下、寒热水肿、膀胱宿水、大腹、开胃、止呕逆不下食。原文无脉名，重在药物名实与功用，非脉诊病机论述，故归其他，脉象要素为空。", []], "27963": ["治法", "此段述大戟形态产地，引李绛方疗水病无问年月深浅、虽复脉恶亦主之，以大戟、当归、橘皮顿服利水。原文虽言脉恶而未出具体脉名，主旨在水病用峻下逐水之法，故归治法，脉象要素为空。", []], "27964": ["病机", "原文引张仲景治肺咳上气、脉沉者，以泽漆汤主之。脉沉主水饮内停、肺气不降，水寒射肺则咳逆上气，故以泽漆逐水、半夏紫参前胡等降气化痰。此脉沉正是水气内结、肺失宣降之病机所在，与肺咳上气症候相应。", ["沉"]], "27965": ["主病", "此段述威灵仙治腰肾脚膝积聚、肠内诸冷病积年不瘥，及腰脚痛、大肠久冷、肾脏风壅积腰膝沉重等。原文无脉名，以药测证属风冷积滞、肾经风壅之病机，故归主病，脉象要素为空。", []], "27966": ["主病", "此段述菰根性味及菰菜功用，孟诜云利五脏、邪气、酒渣、面赤、白癞、疬疡、目赤等。原文无脉名，重在药物主治，所主为邪气壅滞、酒热面赤、疮疡目赤之候，故归主病，脉象要素为空。", []], "27967": ["主病", "此段述芭蕉子食疗主黄疸，生食大寒止渴润肺，性寒通血脉填骨髓；又引方治发背欲死、小儿赤游至心即死。原文无脉名，以药测证属热毒壅盛、血脉不通之病机，故归主病，脉象要素为空。", []], "27968": ["其他", "此段为刘寄奴本草考证，非脉学原文。文中'通妇人经脉症结'指药物主治妇人经血瘀结之症，非论脉象。'症结'在此为病名，指腹中积块，与脉象无关。全段述药性、采收、形态，无脉诊内容，故脉象要素为空，主旨归其他。", []], "27969": ["其他", "此段为连翘本草图经，述产地、形态、采收，无脉诊内容。文中'翘出众草'为植物形态描述，非脉象。全段未涉及脉象、病机或症候辨析，属药物考证，故脉象要素为空，主旨归其他。", []], "27970": ["治法", "此段为补肝散方治肝虚目睛疼、冷泪不止、筋脉痛、羞明怕日。'筋脉痛'指肝血不足、筋脉失养而痛，非脉象。全段以方药治法为主，未言脉诊，故脉象要素为空，主旨归治法，示肝虚目病从补肝论治。", []], "27971": ["其他", "此段为地锦草药性记载，'主通流血脉，亦可用治气'言其功效在活血行气，非论脉象。全段述产地、形态、药用部位，无脉诊内容，故脉象要素为空，主旨归其他，属本草条目。", []], "27972": ["其他", "此段为地锦草图经，述其味辛无毒、主通流血脉亦治气，并辨与络石条地锦同名异物。'通流血脉'为药效，非脉象描述。全段无脉诊内容，故脉象要素为空，主旨归其他，属本草考证。", []], "27973": ["其他", "此段为桂（肉桂）药性记载，述其温中、利肝肺气、通血脉、宣导百药等功效及配伍。'通血脉'指药效，非脉象。全段无脉诊内容，故脉象要素为空，主旨归其他，属本草药性条目。", []], "27974": ["其他", "此段为辛温药（如细辛类）药性记载，主上气咳逆、结气、喉痹、心痛胁痛、温筋通脉等。'温筋通脉'为药效描述，非脉象。全段无脉诊内容，故脉象要素为空，主旨归其他，属本草药性条目。", []], "27975": ["其他", "此段为治风方药主治记载，述主一切风、化涎、肝风筋脉抽掣、急风口噤、顽痹、破伤风口眼㖞斜等。'筋脉抽掣''腰脊强硬'为症候，非脉象。全段无脉诊内容，故脉象要素为空，主旨归其他，属方药主治条目。", []], "27976": ["其他", "本段为榆树皮、荚仁的药用记载，述其性滑利、令人多睡、断谷不饥，及榆荚主妇人带下、嫩叶消水肿等，通篇未涉及脉象，故无从论脉所主病机，仅属本草杂录。", []], "27977": ["其他", "本段记漆之产地、性状与生漆毒烈之性，言漆性急、畏漆者致死、外气致疮肿，并及仙方用蟹消漆之法，全无脉象描述，不能据以推断病机，属本草炮制与毒性杂说。", []], "27978": ["其他", "本段辨辛夷采收时节，述其树形、花未开时如小桃有毛，及南北方开花早迟之别，兼纠九月采实之误，通篇未言脉，故无脉象要素可录，亦不涉病机。", []], "27979": ["其他", "本段论桑上寄生之形态、寄根皮节、花色实赤，并辨俗呼续断之混，及与桑檽不同，皆属药材名实考订，原文无脉象字样，不能附会脉主何病。", []], "27980": ["主病", "本段列药之主伤中、五劳六极、羸瘦、崩中脉绝，补虚益气，去肺中水气，疗唾血热渴、水肿腹满胪胀，利水道。文中「脉绝」指崩中失血脉气欲绝之症，非脉象本身，故脉象要素为空；其主旨为药所主之病，属主病。", []], "27981": ["其他", "本段述桑耳、五木耳之种类与食用药用，及桑椹主消渴、叶除脚气水肿、灰灭痣蚀恶肉等，均为本草主治杂录，未及诊脉，故脉象要素空，不归病机。", []], "27982": ["治法", "本段载雷公炮制桑根之法，取向东嫩根、铜刀剥皮、勿令涎落，并录圣惠方治大风髭发脱落、外台治偏风一切风之桑枝煎服法，皆属治法方药，原文无脉象，故脉象要素为空。", []], "27983": ["治法", "本段述竹沥、竹叶、竹茹、竹根主治咳逆消渴痰饮喉痹、口疮目热、下热壅、心肺热毒，及外台疗折骨疮肿慎风、中风发痓急服竹沥之法，通篇为治法方药，未涉脉象，故脉象要素空。", []], "27984": ["主病", "原文载厚朴三物汤主腹胀而脉数，此数脉非热盛，乃气机壅滞、郁而化热之象。厚朴、枳实、大黄三物行气通腑，说明腹胀由实邪内结、腑气不通所致，脉数正是邪实壅遏、气血运行加速的反映，与腹痛胀满、大便不通等症相应。", ["数"]], "27985": ["其他", "本段纯为紫薇（陵霄花）名物考证，辨陶隐居、苏恭引《尔雅》陵时作陵霄之误，并指出陵霄非草类。全段未涉脉象与病机，故脉象要素为空，主旨属本草名实考订，不归主病、病机诸类。", []], "27986": ["主病", "原文治消渴脉浮、小便不利、微热，用猪苓散发其汗。脉浮为邪在表、气化不利，水蓄下焦而津不上承，故见消渴、小便不利；微热亦表邪未解之征。猪苓、茯苓、泽泻、滑石、阿胶利水兼解表，正合脉浮水停之病机，呕而思水者亦属水逆同类。", ["浮"]], "27987": ["其他", "本段仅载日华子言药性温，治血脉麻痹疼痛及目赤，煎洗外用。文中未出现脉象描述，亦未论及脉与病机关系，故脉象要素为空。主旨为记述该药主治与用法，属本草主治范畴，不涉及脉诊判断。", []], "27988": ["其他", "本段述药味甘平微寒，主青盲肤翳、赤涩多眵泪、目中赤脉及小儿麸豆疳气攻眼，并载产地形态采收。全段无脉象记载，未以脉论病机，故脉象要素为空，主旨属本草主治眼疾的记述，与脉诊无直接关联。", []], "27989": ["其他", "本段载药味辛温有大毒，主伤寒温疟寒热、破症瘕结聚坚积、留饮痰癖、大腹水胀，通利水谷道，疗女子月闭烂胎等。通篇为药物主治与毒性宜忌，未涉脉象，故脉象要素为空，主旨属本草主治范畴，不能归入主病或病机脉诊条目。", []], "27990": ["其他", "本段述药味辛温大热有毒，主邪气咳逆、温中、逐骨节皮肤死肌、寒湿痹痛，除六腑寒冷、心腹留饮宿食、肠澼下痢等，并载久服轻身、多食乏气口闭杀人。全段无脉象，主旨为药物主治与服食宜忌，脉象要素为空。", []], "27991": ["其他", "本段虽标实脉，实为雷公炮制皂荚之法及附方，言拣取圆满坚硬不蛀者入药，治时气头痛烦热、卒中风口㖞。文中实脉非论病机，乃借以形容皂荚子坚实之性状，故不主病；主旨属炮制与单方应用，脉象要素仅取实字。", ["实"]], "27992": ["其他", "本段为樗木与椿木的形态鉴别及樗皮主治，未涉脉象。文中「樗木疏、椿木实」以木质疏实为别，非论脉之虚实；所主赤白久痢、疳虫、鬼疰传尸等，皆从樗皮苦毒杀虫燥湿之性推衍，与脉诊无关，故脉象要素为空，主旨归入其他。", []], "27993": ["其他", "本段载椿木根炮制、食疗宜忌及诸方主治，未言脉象。文中「若和猪肉、热面频食，则中满，盖壅经脉也」以食滞壅遏经脉释中满，是言病机而非脉象；「偏利溺涩」亦属药效。全段无脉名可录，故脉象要素为空，主旨属其他。", []], "27994": ["其他", "本段仅述某药味甘苦平、主痔止血疗血痢止渴及「取脉炙用之」的炮制用法，未及脉诊。「取脉」指取该药之茎脉入药，非诊脉之脉；所主痔、血痢、渴，皆从药性甘苦平推得，无脉象可辨，故脉象要素为空，主旨归其他。", []], "27995": ["其他", "本段辨栾荆与石南、石荆之真伪，并录药性论所主四肢不遂、通血脉、明目益精光，未涉脉象。文中「通血脉」是药效通利血脉，非脉象之血脉；「决明为使」为配伍。全段无脉名，脉象要素为空，主旨属其他。", []], "27996": ["其他", "本段述芫花产地、采收及药性主治，未言脉象。文中「去水气」「泻水肿胀满」「寒痰涕唾如胶」「通利血脉」皆从芫花辛苦有大毒、逐水涤痰之性言其药效，非据脉辨证；「肢挛急，不能行步」为症。无脉象可录，故脉象要素为空，主旨归其他。", []], "27997": ["其他", "本段主述熊脂、熊肉、熊骨、熊胆的药用与宜忌，脉象仅「脉五缓」一语，然上下文为食疗禁忌与诸方主治，非以脉候病。文中「主风痹筋骨不仁」「主历节风」「小儿惊痫瘛疭」皆从熊肉、熊骨、熊胆之性推衍，与五缓脉无直接脉证对应，故仅录「缓」字，主旨归其他。", ["缓"]], "27998": ["其他", "本段述某物微寒，润五脏、利大小便、益十二经脉，治赤白痢及小儿服之弥佳，未涉脉诊。文中「益十二经脉」是药效滋养经脉，非脉象；「微动气」言药性微动气机，亦非脉。全段无脉名可录，脉象要素为空，主旨属其他。", []], "27999": ["其他", "本段述某药味咸甘平，主伤中、脉绝阴不起、强志益气、长肌肉肥健、生子及小儿惊痫，未言诊脉。文中「脉绝阴不起」指阴脉断绝、阴器不举之病证，非脉象要素；所主诸症皆从药性咸甘平补益推得。无脉名可录，故脉象要素为空，主旨归其他。", []], "28000": ["其他", "本段为马肉食用宜忌及外治杂方，未涉脉象。文中\"马自死，肉不可食\"\"五月勿食，伤神\"\"白马黑头，食令人癫\"皆言食禁致病，非脉诊所主。\"主肠中热，除下气，长筋骨\"为马肉功用，与脉无关。故无从据脉论病机，仅属食疗禁忌与杂治内容。", []], "28001": ["主病", "本段言髓味甘温，主\"伤中，绝脉，筋急痛，咳逆\"。\"绝脉\"指血脉虚绝、脉道不利，非具体脉象；髓能填精养血，故主伤中而血脉断绝、筋脉失养拘急作痛，兼咳逆者精亏不能纳气。以酒和服取其温通助药力。全段以主治立论，未出脉形。", []], "28002": ["其他", "本段专述鹿茸炮制与鹿角、麋角鉴别采制，未及脉象。\"其角要黄色、紧重、尖好者\"之\"紧重\"状角质，非脉之紧；\"色苍白者上\"亦言角色。全段属药料修治与品种辨识，无病机脉理可析，故归其他。", []], "28003": ["主病", "本段罗列牛体各部主治：牛鼻中木卷疗小儿痫，白牛悬蹄主妇人崩中漏赤白，特牛茎主妇人漏下赤白、无子，乌牛胆主明目及疳湿，尿主消渴、黄疸、水肿、脚气。皆以物性归经论所主，未出脉象，故不能据脉析机，只述主治病证。", []], "28004": ["主病", "本段言羊髓味甘温无毒，主\"男女伤中，阴气不足，利血脉，益经气\"。阴气不足则血脉不充、经气不利，羊髓甘温填补，以酒服助其温行。全段以功用主治为纲，未提脉形，故脉象要素为空，主旨属主病范畴。", []], "28005": ["主病", "本段述犬肉功用：\"益阳事，补血脉，厚肠胃，实下焦，填精髓\"，日华子云\"补胃气，壮阳，暖腰膝，补虚劳，益气力\"。所主为阳衰精亏、脾胃虚寒、下焦不实之证，故以温补立论。文中\"去血则力少\"\"瘦者多是病\"言取材，非脉候，全段未出脉象。", []], "28006": ["主病", "本段论兔肉及兔皮、毛、头、骨、膏主治，兼载妊娠忌食。\"兔皮、毛合烧为灰酒服，主产难后衣不出，及余血抢心，胀欲死者\"，是取其活血下瘀；\"久食弱阳，令人色痿\"言过食伤阳。诸条皆以物论治，未涉脉形，故脉象为空，主旨归主病。", []], "28007": ["主病", "本段言兔肉性冷，\"大都绝人血脉，损房事，令人痿黄\"，又载兔皮烧末疗妇人带下、兔脑髓涂手足皲裂、兔屎合虾蟆烧灰敷月蚀疮。\"绝人血脉\"言久食伤血，非脉绝之象；全段以食忌与单方主治为主，未出脉形，故脉象要素为空。", []], "28008": ["其他", "原文论猪肉味苦，主闭血脉、弱筋骨、虚人肌，属食忌而非脉诊。其“闭血脉”指猪肉滋腻碍血行，“弱筋骨”“虚人肌”言久食耗损形质，故病人与金疮者尤忌，恐滞血妨愈。全段无脉象可辨，主旨为食物禁忌与病机推演。", []], "28009": ["其他", "此段杂述猪之别名及猪心、肺、肝等性味主治，非论脉。言“食之多暴肥，盖风虚所致”，指猪肉助湿生痰、虚风内动之弊；猪心“能耗心气”，猪肺“令人气滞，发霍乱”，皆从食性推病机，无脉象可录。", []], "28010": ["其他", "原文述猪肉味苦微寒，能“疗热闭血脉”，又“虚人动风”“发痰”，疟疾人食必再发，皆言食性致病。舌汁健脾补气，猪肤汤治少阴下利咽痛，属方治内容。全段无脉象，主旨为食物宜忌与方药，非脉学病机。", []], "28011": ["其他", "此段论麋性淫快、麋脂及麋角功用，言麋肉不可合虾及生菜梅李果实食之“皆病人”，麋角“补虚劳，填髓”。所涉为食忌与补益，未及脉象，故脉要素为空，主旨归其他。", []], "28012": ["其他", "原文述獭肉性寒，主骨蒸热劳、血脉不行、营卫虚满、女子经络不通、血热秘涩，又“消阳气，不益男子”。此从食性推病机，言寒性消阳、滞血，非凭脉断证，故无脉象可录，主旨属食物主治与禁忌。", []], "28013": ["其他", "此段述鼹鼠形类鼠而肥、多膏，肉性寒，主风热久积、血脉不行、结成疮疽，小儿食之杀蛔虫。所论为食性与主治，未涉脉诊，脉要素为空，主旨归其他。", []], "28014": ["病机", "原文引《素问》心腹满、旦食不能暮食名鼓胀，治以鸡矢醴，注云鸡矢利小便微寒。脉“上下行微弦”言气机壅滞、肝木乘脾，弦为胀满之象，微则病未甚。鸡矢醴通利小便以泄胀，正合脉弦主胀之病机，故列病机。", ["弦", "微"]], "28015": ["其他", "原文论雀性利阴阳，雀卵和天雄丸令茎不衰，雀肉起阳道令人有子，雀屎主症癖久痼冷病、痃癖伏梁，和干姜桂心艾为丸能烂痃癖。所涉为食药功用与禁忌，妊身人尤禁雀肉，未及脉象，故脉要素为空，主旨归其他。", []], "28016": ["主病", "原文为药物条目，未及脉象。所主劳损、积血、惊邪癫痫、发热狂走，皆属瘀血内阻、神明失守之病机；'利血脉，安神'点明治法方向，与脉学无涉，故脉象要素为空。", []], "28017": ["其他", "此段述龟类品种、产地及龟溺疗耳聋等，属本草考订，未言脉。'疗蛇毒''滴耳中瘥'为单方主治，与脉象病机无关，故不取脉。", []], "28018": ["主病", "玳瑁肉主诸风毒、行气血、去胸膈风痰、镇心脾、逐邪热、通妇人经脉，甲壳同疗心风邪、破症结、止惊痫。全段为药性主治，未涉脉象，故脉象要素为空。", []], "28019": ["主病", "露蜂房条述其治恶疽、附骨痈、疔肿恶脉、阴痿、上气、赤白痢、遗尿失禁等，皆属热毒壅结、脏腑根深之病。原文未及脉，故脉象要素为空。", []], "28020": ["其他", "此段辨蟹类品种、毒性及中毒救治，兼述蟹髓续筋骨。'食水莨所为''目相向者亦杀人'言中毒之由，非脉诊内容，故脉象要素为空。", []], "28021": ["主病", "味咸微寒有毒，主逐瘀血、破血积坚痞症瘕、通利血脉九窍、女子月水不通、除贼血在胸腹五脏、喉痹结塞。所主皆瘀血积聚、血脉壅塞之病机，原文未言脉，故脉象要素为空。", []], "28022": ["主病", "味咸寒有毒，主血瘀症坚、寒热、破积聚、喉咽闭内塞、无子、通利血脉。其病机为瘀血坚结、血脉不通，故见症瘕、喉闭、无子。原文未及脉象，脉象要素为空。", []], "28023": ["主病", "衍义述䗪虫治乳脉不行，研一枚水服。乳脉不行属瘀血阻络、乳汁壅滞之病机，取虫药破瘀通脉。原文未言脉，故脉象要素为空。", []], "28024": ["其他", "此段为白鱼食疗本草，未涉脉象。原文言白鱼主肝家不足气、助血脉、补肝明目，理经脉，是从食治角度补肝益血；又言不堪多食、久食令人心腹诸病、患疮疖人不可食，说明其性虽补而多食反伤脾胃、助疮发脓，与脉诊病机无关，故脉象要素为空。", []], "28025": ["主病", "原文以脉拘急与筋脉拘急并见，言白花蛇主中风、湿痹不仁、口面㖞斜、半身不遂。风邪湿邪痹阻经络，气血不能濡养筋脉，故筋脉拘急而脉道亦拘紧不柔；脉拘急正反映风痰湿瘀阻络、筋脉失养之病机，与中风偏枯、痹证相应。", ["急"]], "28026": ["主病", "此段述寒号虫粪主治，未及脉象。原文主心腹冷气、小儿五疳、辟疫、治肠风、通利气脉、女子月闭，提示其病机为寒凝气滞、气血不通，故见心腹冷气与月闭；通利气脉即针对气脉壅滞而言。因原文无脉象描述，脉象要素从缺，主旨归为主病。", []], "28027": ["其他", "此段为莲藕本草考证，未言脉象。原文载藕主热渴、散血、生肌，久服令人心欢，并以庖人削藕皮误落血中而血散不凝之事故，说明藕有散血止血之功；所论皆药性主治与名物，不涉脉诊病机，故脉象要素为空，主旨归其他。", []], "28028": ["兼症", "原文以脉急与筋脉急并见，言治伤中筋脉急、上气咳嗽，用枣合酥常含缓之。筋脉拘急多因中焦受伤、气血不足，筋脉失于濡养而拘紧，故脉见急；上气咳嗽为兼见之症。此段主旨落在伤中筋脉急这一兼症及食疗缓急之法，脉急反映筋脉失养、拘急不柔。", ["急"]], "28029": ["主病", "此段述乌梅及梅根、梅核仁主治，未及脉象。原文言梅实利筋脉、去痹，梅根疗风痹，乌梅止渴、通大便，提示其病机在酸收生津、舒利筋脉、去痹通滞；利筋脉去痹即针对筋脉痹阻而言。因原文无脉象描述，脉象要素从缺，主旨归为主病。", []], "28030": ["其他", "此段为木瓜图经名物考证，未言脉象。原文述木瓜产地、形色及榠楂辨别，末言木瓜大枝可作杖策之，云利筋脉，根叶煮汤淋足胫可已蹶，提示木瓜有舒利筋脉、缓解足胫转筋之用；所论重在名物与功用，不涉脉诊病机，故脉象要素为空。", []], "28031": ["主病", "此段述柿及椑的性味主治，未及脉象。原文言火柿杀毒、疗金疮火疮、生肉止痛，软熟柿解酒热毒、止口干、压胃间热，干柿厚肠胃、涩中、健脾胃气、消宿血，红柿补气、续经脉气，提示其病机涉及清热生津、涩肠健脾、续利经脉气血；因无脉象描述，脉象要素从缺，主旨归为主病。", []], "28032": ["其他", "此段为杏仁炮制与食疗方，非脉诊专论。文中仅以「脉强紧浮者」作引，实述杏仁「主热风头痛」及治偏风、失音等。脉强紧浮提示风邪外袭、经气壅盛，故用杏仁宣降肺气、疏风通络。然全段主旨仍在炮制去毒与诸方应用，脉象仅作兼及，不可据以断病机核心。", ["浮", "紧", "强"]], "28033": ["其他", "本段述石榴壳、枝、根、叶炮制及赤白痢、疔肿、肠滑久痢诸方，未及脉象。文中「为寒，可疗」指下痢水谷不消属寒，与脉无直接对应。石榴皮酸涩收敛，故主久痢滑脱；针疮灸痛以散疔毒。全段为方药杂录，无脉理可析，脉象要素付阙。", []], "28034": ["病机", "原文谓某果「味酸甘，温，不可多食」，多食则「发热涩气，令人好睡，发冷痰，生疮疖，脉闭不行」。此处「脉闭不行」非脉象描述，而是过食酸甘温之物致气机壅滞、血脉闭阻的病机结果。酸收涩气、甘温助热，故痰热内生而脉道不利，属食伤致病的病机推断。", []], "28035": ["兼症", "本段述食疗主谷痢、泄精，根治白虫蛔虫、消渴好睡；又林檎味苦涩平，「食之闭百脉」。此「闭百脉」与上段「脉闭不行」同类，指过食酸涩致血脉凝滞，非脉象本身。后附小儿痢、闪癖瘰疬羸瘦外敷方，属兼症治疗。全段以方药主治为主，脉象无载。", []], "28036": ["其他", "本段述胡桃不可多食、动痰饮，又云「通经脉，润血脉，黑鬓发」，并载常服法及疗损伤、石淋诸方。文中「通经脉」「润血脉」为胡桃功用，非脉象。胡桃性热，多食动痰，少服则润养血脉，故能养痔疾、益发。全段属食疗方药杂录，无脉诊内容可析。", []], "28037": ["病机", "原文述某物微寒无毒，「主妇人经脉不通，丈夫营卫中血脉不行」，久食令人不饥。此以「经脉不通」「血脉不行」言病机，指气血壅滞、营卫不畅，非脉象描述。其性微寒，能通利血脉，故主妇人经闭及男子营卫瘀滞。全段为药物主治，脉象要素无。", []], "28038": ["病机", "原文谓某物「发毒热，秘大小肠，聚胸中痰壅，不宜多食，涩血脉」。此「涩血脉」指过食致血脉涩滞不利，属病机推断而非脉象。毒热内发则二便秘、痰壅胸中；涩血脉则气血运行受阻。日华子云除烦渴、治气，示其另有清利之用。全段以病机与禁忌为主。", []], "28039": ["其他", "本段述麻子味甘平无毒，主补中益气、中风汗出、逐水利小便、破积血、复血脉、乳妇产后余疾等。「复血脉」指恢复血脉通畅，为药效而非脉象。麻子润利，故能逐水破瘀、通复血脉，兼益中气。全段属本草主治记载，未涉脉诊，脉象要素从阙。", []], "28040": ["其他", "本段为麻蕡、麻勃、麻子、麻根的本草考证与主治记载，非脉诊内容。文中辨陶隐居以麻勃为花之误，指出麻蕡即麻实；言麻子仁性滑利，麻根汁主瘀血、石淋、产难衣不出、破血壅胀、带下崩中，沤麻汁主消渴。所论皆药性主治，未涉脉象，故无脉象要素可录。", []], "28041": ["其他", "本段述麻子性寒，主五劳，肥健不老，治大小便不通、发落、破血，取汁煮粥去五脏风、润肺、通血脉治气；青叶长发，麻子汁沐发生长。又载不饥服食方及洞神经服子末下虫、见鬼诸方。全为食疗本草主治与服食法，未言脉象，故脉象要素为空。", []], "28042": ["其他", "本段言麻油大寒无毒，治虚劳、滑肠胃、行风气、通血脉、去头浮风、润肌；生啖与乳母食则孩子不病；客热可作饮汁。又述久食抽人肌肉，生寒炒热，油敷疮疥癣、杀诸虫，合鸡子芒硝服治热毒。皆药性主治，未及脉诊，故无脉象。", []], "28043": ["其他", "本段为外台秘要诸方：治胸喉间症虫上下，用油煎葱豉引虫；治伤寒三五日发黄，用生乌麻油、水、鸡子白和服；治呕用白油麻清酒煎服；治小儿急疳疮嚼油麻敷；治发症用香泽煎油诱饮。全属方治，未涉脉象，故脉象要素为空。", []], "28044": ["其他", "本段按陈藏器本草述大豆炒黑投酒主风痹瘫缓口噤产后诸风，生服去心胸烦热、热风恍惚、明目镇心；煮食下热气肿、压丹石烦热、解药毒消肿。又言炒热煮冷、黄卷及酱平，穞豆去贼风风痹、产后冷血。皆药性主治，未言脉象。", []], "28045": ["其他", "本段图经述大豆黄卷及生大豆产地、修治与效用，言豆性本平而修治有数等之效：煮汁凉压丹石毒，作腐寒而动气，炒食热，投酒主风，作豉极冷，黄卷及酱皆平；杀乌头毒，多食令人体重。文中脉象写法仅标『脉洪起一』，然正文实未论脉，洪字无病机可系，故存脉象要素而归于其他。", ["洪"]], "28046": ["其他", "本段述大豆黄卷以豆为蘖芽干之，煮大豆主温毒水肿殊效；小豆性逐津液，久服令人枯燥；赤小豆和桑白皮煮食主湿气痹肿，和通草煮下气名脱气丸，消热毒痈肿、散恶血、治水肿皮肌胀满、小儿急黄烂疮。皆本草主治，未涉脉象。", []], "28047": ["其他", "本段论酒性大热，独冠群物，药家用以行势；饮之体弊神昏是其有毒。引三人晨行触雾，饮酒者健、食粥者病、空腹者死，明酒势辟恶。又述诸酒醇醨不同，唯米酒入药；陈藏器言酒杀百邪、去恶气、通血脉、厚肠胃、润皮肤、散石气、消忧发怒。全论酒性，未及脉象。", []], "28048": ["其他", "此段论粳米之性味功用，非脉学内容。原文述粳米「平，主益气，止烦泄」，又言新熟者动气、再年者发病，火稻「温中益气，补下元」。所论为谷食宜忌与脏腑补益关系，未涉脉象，故脉象要素为空，主旨归入其他。", []], "28049": ["其他", "此段述黍米性寒、少毒，不堪久服，「昏五脏，令人好睡」，又治鳖瘕、杖疮。原文全论黍米之药性与主治，未及脉诊，故无脉象可录。其「性寒有少毒」之说属本草药性范畴，与脉象病机无涉，归入其他。", []], "28050": ["其他", "此段集食疗、千金、肘后诸方，论黍米与葵菜、牛肉同食之禁忌，及治豌豆疮、小儿鹅口、妊娠尿血、汤火灼伤等方。原文「肺之谷也，肺病宜食」点明黍米归肺，然通篇为食禁与方治，未言脉象，故脉象要素空，归入其他。", []], "28051": ["其他", "此段论小麦药用：「合汤皆完用之，热家疗也」，作面则温，面热麸冷；又述小麦曲止痢、平胃、主小儿痫，女曲、黄蒸消食止泄、下胎破冷血。全属本草炮制与主治，未涉脉诊，脉象要素为空，主旨归其他。", []], "28052": ["其他", "此段言小麦「平，养肝气」，面有热毒因陈黦及磨石末所致，宜作粉食「补中益气，和五脏，调经络，续气脉」。所论为小麦养肝调脉之功与诸方主治，非凭脉辨证，故脉象要素空，归入其他。", []], "28053": ["其他", "此段论大麦及大麦糵：「平胃，止渴，消食，疗胀」，糵能「消化宿食，破冷气，去心腹胀满」。又言久食头发不白、暴食稍似脚弱。全为本草药性主治，未及脉象，脉象要素为空，主旨归其他。", []], "28054": ["其他", "此段述绿豆「平」，补益和五脏、安精神、行十二经脉，研汁治消渴、去浮风；日华子言其冷，益气除热毒风、厚肠胃、作枕明目。所论为绿豆药性与食法宜忌，未涉脉诊，脉象要素空，归入其他。", []], "28055": ["其他", "此段言某物「平，无毒」，补五脏、益中、助十二经脉、调中暖肠胃，叶利五脏下气，嫩者可作菜常食。原文纯述食药补益之性，无脉象描述，故脉象要素为空，主旨归入其他。", []], "28056": ["其他", "本段为粟米食疗诸方，未涉脉象。原文言粟\"补中益气，坚筋骨，通血脉，起阳道\"，又\"止痢\"\"暖五脏六腑之气\"，皆从谷食补养中气立论，非凭脉辨证。所谓\"通血脉\"指粟能益中焦之气以充血脉，非脉象所主。故无脉可析，主旨属食疗本草，列其他。", []], "28057": ["其他", "本段述胡荽性味功用及禁忌，无脉象。原文\"利五脏，补筋脉\"\"消谷能食\"，又戒\"久冷人食之，脚弱\"\"患气，弥不得食\"，皆从食性寒温与脏气宜忌立说。所谓\"补筋脉\"是言其辛温能通养筋脉，非脉诊所得。全段为食疗禁忌，故不列脉。", []], "28058": ["其他", "本段言青蒿类菜辛温平无毒，主\"胸膈中臭烂恶邪气，利肠胃，通血脉，续不足气\"。\"通血脉\"\"续不足气\"是药性功用，非脉象主病。原文又诫\"生食微动风气\"\"不与胡荽同食\"，属食忌。全段无脉名脉形，主旨为食疗本草，故列其他。", []], "28059": ["其他", "本段述兰香（罗勒）辛温微毒，\"调中消食，去恶气，消水气\"，又诫\"不可过多食，壅关节，涩营卫，令血脉不行\"。此处\"血脉不行\"言过食壅滞营卫之害，非脉象所见。全段为食性宜忌及外治诸方，未及诊脉，故列其他。", []], "28060": ["其他", "本段述黄瓜（胡瓜）苦平小毒，主小儿闪癖，实甘寒有毒，\"不可多食，动寒热，多疟病，积瘀热\"\"损阴血脉气\"。\"损阴血脉气\"言过食伤阴耗血之弊，非脉象。全段为食忌及外治，无脉可辨，主旨属食疗本草，列其他。", []], "28061": ["其他", "本段述荏（白苏）食疗，\"主咳逆下气\"，子压油\"少破气\"，又\"补中益气，通血脉，填精髓\"。\"通血脉\"为药性功用，非脉象主病。原文兼载梅师方外敷治虺，全段无脉名脉形，属食疗本草，故列其他。", []], "28062": ["其他", "本段述苦苣苦平，\"除面目及舌下黄\"，\"调十二经脉，利五脏\"，又治\"霍乱后胃气逆烦\"。\"调十二经脉\"是言药性调和经脉，非脉诊所得。原文诫\"不可同血食，食作痔疾\"，属食忌。全段无脉象，主旨为食疗本草，列其他。", []], "28063": ["其他", "本段述荆芥（姜芥）去邪除风，\"治恶风贼风，口面㖞邪，遍身𤸷痹\"，\"通利血脉，传送五脏不足气，能发汗，除冷风\"。\"通利血脉\"为药性功用，非脉象主病。全段引诸家本草言荆芥主治及外敷法，未及诊脉，故列其他。", []], "28064": ["其他", "本段为荆芥本草考证，辨荆芥与析蓂非一物，并述其去邪除风冷、发汗通利血脉之功。文中无脉象描述，故脉象要素为空。所主病机为风冷外袭、血脉不利，故能发汗去邪、通利血脉；产后中风身强直取末酒服，亦取祛风通脉之意，非凭脉断病。", []], "28065": ["主病", "原文载治伤寒时气温病，头痛壮热，脉盛，取蘘荷根叶捣汁服。脉盛为邪热亢盛之象，温病壮热头痛而脉盛，正合热邪充斥、正气奋起抗邪之病机。其余风冷失声、喉舌生疮、吐血蛊毒诸证，皆据症用药，非以脉立论，惟此脉盛一句点出温病热盛之机。", ["盛"]], "28066": ["其他", "本段述胡葱性平，主消谷能食，久食令人多忘、发痼疾，又治食毒肉吐血痿黄。文末言利五脏不足气，亦伤绝血脉气，多食损神，是熏物。全段无脉象记载，所论为胡葱功用与过用之害，属本草主治范畴，未涉及凭脉辨证，故脉象要素为空。", []], "28067": ["主病", "原文述水英味甘平无毒，主女子赤沃、止血、养精、保血脉、益气，令人肥健嗜食。所主病机为精血不足、血脉不固所致女子赤沃与出血，故以养精保血脉、益气止血为治。全段无脉象描述，属本草主病之文，脉象要素为空，不可附会脉名。", []], "28068": ["病机", "本段论芹，唐本注云芹花味苦，主脉溢。脉溢指血溢脉外、脉络充盈妄行之病机，故以苦味芹花治之。文中又言水芹性大寒，捣汁去小儿暴热、大人酒后热毒、鼻塞身热，利大小肠，皆从寒凉清热、通利之性立论。全段未载具体脉象，脉象要素为空。", []], "28069": ["主病", "本段述渣芹平，主女子赤白沃、止血、养精神、保血脉、益气嗜食，去头中热风；又载食芹致蛟龙瘕，发则似癫、面色青黄、小腹胀如怀妊。所论为芹菜主治及过食致病，病机涉精血不固与龙精入芹之瘕病，全段无脉象描述，脉象要素为空。", []], "28070": ["主病", "原文述白苣味苦寒，主补筋骨、利五脏、开胸膈拥气、通经脉、止脾气，令人齿白聪明少睡。所主病机为胸膈气拥、经脉不通，故以苦寒通利开泄为治；又言患冷气人食之腹冷，产后不可食令人寒中腹痛，是从寒性伤阳立论。全段无脉象记载，脉象要素为空。", []], "28071": ["主病", "本段述百蕊草生河中府等地，根黄白色，形如瓦松，四时采根晒干用，下乳，亦通顺血脉、调气甚佳。所主病机为产后乳汁不通、血脉不畅、气机失调，故取通顺血脉调气以下乳。全段仅言药性与主治，未载脉象，脉象要素为空，不可强拟脉名。", []], "28072": ["主病", "原文载药“主肢节风冷，筋脉急痛”，脉急指筋脉拘急挛缩之象。风冷客于肢节，寒性收引，气血凝滞，筋脉失养，故见脉急而痛。此脉象反映寒邪外束、筋脉挛急之病机，主肢节风冷疼痛之证，与“筋脉急痛”症候相应。", ["急"]], "28073": ["病机", "原文谓药“主充肌肤，益气，令人暴肥，不可久服，血脉满盛”。虽未明言脉象，然“血脉满盛”即言药力壅盛，久服则气血充溢、脉道满实。此段主旨在于提示过服温补致血脉壅满之病机，与“暴肥”相应，属药邪致害之候。", []], "28074": ["病机", "原文述菟丝子“禀中和凝正阳气受结，偏补人卫气，助人筋脉”，虽未出脉名，然“助人筋脉”点明其功在温养筋脉。卫气不足则筋脉失煦，脉当见弱或细；此药补卫助筋，正对卫虚筋弱之机，与筋脉弛缓无力之症相应。", []], "28075": ["误治", "原文载误服丹龙精“令人筋脉永不收”，此非脉象而属药毒致害。毒伤筋脉，气血失养，拘急不收，脉当见弦急或细促。此段主旨为误服伪药致筋脉废用之变，与“筋脉永不收”症候相应，属误治坏病之列。", []], "28076": ["病机", "原文论酒“通血脉”“厚肠胃”，又谓多饮“伤神损寿”“腐烂肠胃，渍髓，蒸筋”。虽未言脉，然酒性大热有毒，少饮通脉，多饮则热毒壅滞血脉，脉当见数或洪。此段阐发酒之利弊，主热毒伤及血脉肠胃之病机，与痰疾、髓损筋蒸诸症相应。", []], "28077": ["主病", "原文载羊辟膝骨“主男女虚劳，寒中，羸瘦，阴气不足。利血脉，益经气”。虚劳寒中，阴气亏虚，脉当见虚细或沉弱。此药利血脉益经气，正对虚劳寒中、血脉不利之机，与羸瘦、阴气不足之症相应，属虚损主病之候。", []], "28078": ["病机", "原文述药枕“病之来皆从阳脉起，今枕药枕，风邪不得侵入矣”。虽未出具体脉象，然“阳脉起”指外邪初犯阳脉，脉当见浮。药枕辟邪，使风邪不得侵，此段主旨为外邪从阳脉而入之病机，与风邪侵袭之候相应，属预防辟邪之法。", []], "28079": ["病机", "原文论五味过食致病：酸收致膀胱不利癃闭，苦燥致三焦闭塞呕吐，辛致荣卫不时心洞，咸致胃竭咽燥病渴，甘致中满心闷。虽未言脉，然五味偏胜，脏气偏倾，脉当随证而变。此段阐发五味过用伤及脏腑气机之病机，与癃闭、呕吐、消渴、中满诸症相应。", []], "28080": ["病机", "原文未出脉名，然论五味偏嗜伤脏：多食咸则\"脉凝泣而变色\"，指出咸味过甚使血脉凝涩、色变，属脉道不利之病机；多食辛则\"筋脉沮㢮\"，辛散耗气致筋脉松弛。全段以\"多者生疾，少者为益\"为纲，说明饮食偏嗜通过伤脏损脉而生疾，非论具体脉象，故脉象要素为空。", []], "28081": ["治法", "原文述药食\"味甘寒，无毒\"，主丹毒、风疹、烦热，能\"和五脏，行经脉\"。其主旨在于以甘寒之品清热和脏、通利经脉，属治法范畴。\"行经脉\"指药性可疏通脉道，非描述脉象本身，故不取脉象要素；所主为热毒郁于血脉、五脏不和之证。", []], "28082": ["治法", "原文言药食\"味甘，平，无毒\"，功能\"调中，暖肠胃，助经脉\"，并云\"肾病宜食\"。此为以甘平之味调补中焦、温养肠胃、助益经脉的治法，适用于中虚及肾病者。\"助经脉\"言药效助脉气运行，非脉象描述，故脉象要素为空。", []], "28083": ["治法", "原文述药食\"味甘、大寒，无毒\"，治虚劳，\"滑肠胃，行风气，通血脉，去头风，润肌肤\"，并载食后生啖及乳母食之令子不生病。主旨为甘寒润养、通利血脉以治虚劳风热之治法。\"通血脉\"指药效通利脉道，非脉象，故脉象要素为空。", []], "28084": ["治法", "原文论酒\"味苦甘辣，大热，有毒\"，能\"行药势，杀百邪，通血脉，厚肠胃，润皮肤，消忧愁\"，又戒\"多饮损寿伤神，易人本性\"。主旨为酒之行药通脉之功与过饮伤神之害，属治法及慎用之诫。\"通血脉\"言酒性行血，非脉象描述，故脉象要素为空。", []], "28085": ["治法", "原文载以地黄绞汁酿酒，\"治虚弱，壮筋骨，通血脉，治腹内痛\"。此为药酒补虚壮骨、通利血脉以止腹痛的治法。\"通血脉\"指地黄酒通行脉道之效，针对虚而脉道不利、腹内作痛者，非直接描述脉象，故脉象要素为空。", []], "28086": ["治法", "原文述药食\"微寒，润五脏，利大小便，益十二经脉，微动气\"。主旨为微寒润养之品润脏通便、益养经脉的治法，兼记其\"微动气\"之偏。\"益十二经脉\"言药效滋养脉气，非脉象本身，故脉象要素为空；所主为五脏失润、二便不利之证。", []], "28087": ["治法", "原文言药食\"味甘，温\"，主治男女伤中、阴气不足，能\"利血脉，益经气\"。此为甘温补益中气、滋养阴气、通利血脉经气的治法，适用于男女伤中、阴气亏虚者。\"利血脉，益经气\"皆言药效作用于脉气，非脉象描述，故脉象要素为空。", []], "28088": ["主病", "原文载药“主伤中，脉绝”，脉绝指血脉虚竭欲断之候，非具体脉象。药味咸甘无毒，能补益中气、续接绝脉，故所主病机为中气伤损、血脉不续，症见脉气衰绝、肌肉消瘦、阴气不足等，服之可强志益气、长肌肉、令人有子。", []], "28089": ["主病", "原文述药“通血脉，润泽皮肤”，所主痈肿恶疮、风痹、四肢拘缓，皆因邪阻血脉、肌肤失养所致。药性辛温，能宣通血脉、祛风解痹，故病机为血脉壅滞不通、风邪痹阻，症见疮肿、肢体拘急缓纵，皮肤枯槁。", []], "28090": ["主病", "原文言“主男女伤中，绝脉，筋急，咳逆”，绝脉即血脉虚绝之候。药甘温，能补中续脉、缓急止咳，故病机为中气亏虚、血脉断绝、筋脉失养而挛急，兼肺气上逆致咳，以酒服助药力温通。", []], "28091": ["主病", "原文载药“补绝伤，益阳道，补血脉，厚肠胃，实下焦，填精髓”，所主病机为五脏虚损、血脉不足、下焦不固、精髓亏空。药味咸温，功偏温补，故能安五脏、续绝伤，症见阳道不兴、肠胃薄弱、下焦虚寒、精髓空虚等。", []], "28092": ["主病", "原文谓药“主闭血脉，弱筋骨，虚肥人”，其性苦而久食动风。病机为血脉闭阻、筋骨失养而弱，肥人虚浮者尤易受其害；风动则变生他症，金疮患者血脉本伤，更忌闭阻，故“尤甚”。", []], "28093": ["主病", "原文载药“补中益气”，但“不宜多食，损阳事，绝血脉，令人痿黄”。病机为过食辛平之品，耗损阳气、断绝血脉，致阳气不振、血脉不荣，症见阳事不举、肌肤痿黄；妊娠食之更伤胎元，故令子缺唇。", []], "28094": ["主病", "原文述药“主胸中邪热结痛，通胃气，调经脉”，所主病机为邪热结聚胸中、胃气不通、经脉失调。药味咸有毒，能清热散结、通降胃气、调和经脉，故症见胸中热结疼痛、胃气壅滞、经脉不和。", []], "28095": ["主病", "原文载药“主心腹邪气，安中养脾，助经脉，生津液”，所主病机为心腹邪气内扰、中焦脾胃不和、经脉失助、津液不足。药味甘无毒，能安中养脾、助脉生津，故症见心腹邪气、脾虚不运、津伤口燥等。", []], "28096": ["病机", "原文未出脉名，仅言药性苦寒有毒，能发五脏风壅经脉、动痔病、令人昏闷。其病机在于苦寒之品扰动五脏，风邪壅遏经脉，气血不得宣通，故痔病发动；风壅上扰清窍，则令人昏闷。此段以药测证，提示风壅经脉、气血壅滞为痔病与昏闷之由，非直接论脉。", []], "28097": ["治法", "原文未识脉名，述药味甘无毒，功能补中益气、治血脉。其病机为中气不足、血脉失养或血脉不和。甘味入脾，补中气以资化源，气旺则血充，故能治血脉。此段从药效反推，主中虚血脉不荣之证，属补益治法，非脉象主病之文。", []], "28098": ["治法", "原文无脉名，言药味苦冷无毒，主利五脏、开胸膈壅气、通血脉。病机为五脏气机不利、胸膈壅塞、血脉不通。苦冷之品能降能泄，故利五脏、开壅气；气行则血行，故通血脉。此段以药效说明胸膈气壅、血脉瘀滞之证可用苦冷通利，属治法范畴。", []], "28099": ["治法", "原文未出脉名，述药味甘平无毒，通经脉、下气、开胸膈。病机为经脉不通、气机上逆、胸膈闭塞。甘平之品能和能缓，通经脉；下气则逆降，胸膈自开。此段从药物功用反推，主气逆胸膈壅塞、经脉不畅之证，属通降治法，非脉诊主病之论。", []]});